Object.assign(window.TEM8_DICTIONARY, {"post":{"media":{"uk":"media/uk/post__gb_1.mp3","us":"media/us/post__us_1.mp3"},"oxford":{"phon":"pəʊst","pos":"prefix","senses":[{"en":"after","cn":"在…之后","ex":{"en":"a postgraduate","cn":"研究生"}},{"en":"the official system used for sending and delivering letters, packages, etc.","cn":"邮政；邮递；邮寄","g":"[uncountable]","lab":"British English","sc":"letters","ex":{"en":"I'll send the original to you by post.","cn":"我将把原件邮寄给你。"},"pos":"noun"},{"en":"letters, packages, etc. that are sent and delivered","cn":"邮件；信件；邮包","g":"[uncountable]","lab":"British English","sc":"letters","ex":{"en":"There was a lot of post this morning.","cn":"今天上午邮件很多。"},"pos":"noun"},{"en":"an occasion during the day when letters, etc. are collected or delivered","cn":"收集（或投递）邮件的时间；邮班","g":"[uncountable, singular]","lab":"British English","sc":"letters","ex":{"en":"to catch/miss the post","cn":"赶上／错过邮班"},"pos":"noun"},{"en":"a message sent to a discussion group on the internet; a piece of writing that forms part of a blog","cn":"（发送到互联网讨论组的）帖子，信息；博文；网志文章","g":"[countable]","sc":"internet","ex":{"en":"I love reading her posts because I learn so much.","cn":"我喜欢读她的帖子，因为我能学到很多东西。"},"pos":"noun"},{"en":"a job, especially an important one in a large organization","cn":"职位；（尤指）要职","g":"[countable]","lab":"especially British English","sc":"job","ex":{"en":"an academic/a government post","cn":"教学／政府职位"},"pos":"noun"},{"en":"an act of sending somebody to a particular place to do their job, especially for a limited period of time","cn":"派驻","lab":"especially North American English","sc":"job","ex":{"en":"an overseas post","cn":"派驻海外"},"pos":"noun"},{"en":"the place where somebody, especially a soldier, does their job","cn":"哨所；岗位","g":"[countable]","sc":"for soldier/guard","ex":{"en":"a police/military/customs post","cn":"警察/军队/海关哨所"},"pos":"noun"},{"en":"a piece of wood or metal that is set in the ground in a position pointing upwards, especially to support something or to mark a point","cn":"柱；桩；标志杆","g":"[countable]","sc":"wood/metal","ex":{"en":"She tied the dog to a post.","cn":"她把狗拴在柱子上。"},"pos":"noun"},{"en":"the place where a race finishes, especially in horse racing","cn":"（尤指赛马的）终点，终点标志","g":"[singular]","sc":"end of race","ex":{"en":"The first horse past the post wins the race.","cn":"第一匹跑过终点的马获胜。"},"pos":"noun"},{"en":"one of the two posts that form part of a goal","cn":"球门柱","g":"[countable, usually singular]","sc":"football","ex":{"en":"The ball hit the post and bounced in.","cn":"球击中门柱反弹入网。"},"pos":"noun"},{"en":"to send a letter, etc. to somebody by post","cn":"寄；邮寄","g":"[transitive]","lab":"British English","sc":"letters","ex":{"en":"The cost of posting a letter has gone up again.","cn":"寄信的邮资又涨了。"},"pos":"verb"},{"en":"to put a letter, etc. into a postbox","cn":"把（信件等）投入邮筒；投递；邮寄","g":"[transitive]","lab":"British English","sc":"letters","ex":{"en":"Could you post this letter for me?","cn":"请把这封信替我寄了好吗？"},"pos":"verb"},{"en":"to put something through a hole into a container","cn":"把…放入（或塞入）","g":"[transitive]","sc":"something through hole","ex":{"en":"Let yourself out and post the keys through the letter box.","cn":"你先出去，再把这些钥匙塞进信箱吧。"},"pos":"verb"},{"en":"to put information or pictures on a website","cn":"（在网站上）发布（信息或图片）","g":"[transitive, intransitive]","sc":"give information","ex":{"en":"More details will be posted on the website tomorrow.","cn":"明天将在网站上公布更多细节。"},"pos":"verb"},{"en":"to announce something publicly or officially, especially financial information or a warning","cn":"发布，公布，宣布（尤指财经信息或警告）","g":"[transitive]","lab":"especially North American English","sc":"give information","ex":{"en":"The company posted a $1.1 billion loss.","cn":"这家公司公布了 11 亿美元的亏损。"},"pos":"verb"},{"en":"to send somebody to a place for a period of time as part of their job","cn":"派驻","g":"[transitive, usually passive]","sc":"somebody for job","ex":{"en":"She's been posted to Washington for two years.","cn":"她被派往华盛顿工作两年。"},"pos":"verb"},{"en":"to put somebody, especially a soldier, in a particular place so that they can guard a building or area","cn":"使驻守；布置…站岗","g":"[transitive, usually passive]","sc":"soldier/guard","ex":{"en":"Guards have been posted along the border.","cn":"边界上已部署了边防岗哨。"},"pos":"verb"},{"en":"to put a notice, etc. in a public place so that people can see it","cn":"张贴；公布","g":"[transitive, often passive]","sc":"public notice","ex":{"en":"A copy of the letter was posted on the noticeboard.","cn":"布告牌上张贴了这封信的内容。"},"pos":"verb"},{"en":"to pay money to a court so that a person accused of a crime can go free until their trial","cn":"交付（保释金）","g":"[transitive]","lab":"especially North American English","sc":"pay money to court","ex":{"en":"She was released after posting $100 cash bond and her driver's license.","cn":"交了 100 美元现款保释金及驾驶执照以后，她获得保释了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"邮政；邮递","en":"The post is the public service or system by which letters and packages are collected and delivered.","ex":{"en":"You'll receive your book through the post","cn":"书会邮递给你。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"邮件；邮包；包裹","en":"You can use post to refer to letters and packages that are delivered to you.","ex":{"en":"He flipped through the post without opening any of it","cn":"他飞快地翻了一下邮件，但一封也没有打开。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"投递邮件；邮班","en":"Post is used to refer to an occasion when letters or packages are delivered. For example, first post on a particular day is the first time that things are delivered.","ex":{"en":"Entries must arrive by first post next Wednesday","cn":"参赛作品必须在下周三第一批邮件之前寄达。"}},{"pos":"VERB 动词","cn":"邮寄；投递","en":"If you post a letter or package, you send it to someone by putting it in a post box or by taking it to a post office.","ex":{"en":"If I write a letter, would you post it for me?","cn":"如果我写封信，你能替我寄出去吗？"}},{"pos":"VERB 动词","cn":"张贴，贴出（通知、标牌等）","en":"If you post notices, signs, or other pieces of information somewhere, you fix them to a wall or board so that everyone can see them.","ex":{"en":"Officials began posting warning notices","cn":"官员们开始张贴警告。"}},{"pos":"VERB 动词","cn":"发布，公布（信息）","en":"If you post information on the Internet, you make the information available to other people on the Internet.","ex":{"en":"A consultation paper has been posted on the Internet inviting input from Net users.","cn":"一份征询意见书已贴在了因特网上，欢迎网络用户发表意见。"}},{"pos":"PHRASE 短语","cn":"向…提供最新信息；使及时了解","en":"If you keep someone posted, you keep giving them the latest information about a situation that they are interested in.","ex":{"en":"Keep me posted on your progress.","cn":"让我随时了解你们的进展。"}},{"pos":"N-COUNT 可数名词","cn":"职位;职务","en":"A post in a company or organization is a job or official position in it, usually one that involves responsibility.","ex":{"en":"She had earlier resigned her post as President Menem's assistant","cn":"她早些时候辞去了梅内姆总统助理一职。"}},{"pos":"VERB 动词","cn":"委派;派驻","en":"If you are posted somewhere, you are sent there by the organization that you work for and usually work there for several years.","ex":{"en":"After training she was posted to Brixton","cn":"培训结束后她被派往布里克斯顿。"}},{"pos":"N-COUNT 可数名词","cn":"岗位；哨位","en":"You can use post to refer to the place where a soldier, guard, or other person has been told to remain and to do his or her job.","ex":{"en":"Quick men, back to your post!","cn":"迅速返回各自岗位！"}},{"pos":"VERB 动词","cn":"使驻守；布置…站岗","en":"If a soldier, guard, or other person is posted somewhere, they are told to stand there, in order to supervise an activity or guard a place.","ex":{"en":"Police have now been posted outside all temples","cn":"现在所有神殿外都已安排警察站岗。"}},{"pos":"N-COUNT 可数名词","cn":"柱；桩；杆","en":"A post is a strong upright pole made of wood or metal that is fixed into the ground.","ex":{"en":"You have to get eight wooden posts, and drive them into the ground","cn":"你得找来8根木桩，并把它们敲入地里。"}},{"pos":"N-COUNT 可数名词","cn":"同 goalpost","en":"A post is the same as a goalpost .","ex":{"en":"Wimbledon were unlucky not to win after hitting the post twice.","cn":"温布尔登队运气不佳，两次将球踢到门柱上，最终没有获胜。"}},{"pos":"N-SING 单数名词","cn":"（赛马场上的）终点柱","en":"On a horse-racing track, the post is a pole which marks the finishing point."},{"pos":"See also:","cn":"","en":"to pip someone at the post→see: ;"}]},"examples":[{"en":"the US Postal Service.","cn":"在美式英语中，post 出现在 the US Postal Service（美国邮政管理局）等短语中。"},{"en":"the Royal Mail.","cn":"在英式英语中，mail 有时用于 the Royal Mail（皇家邮政）等短语中。"}]},"politely":{"oxford":{"phon":"pəˈlaɪtli","pos":"adverb","senses":[{"en":"in a way that shows good manners and respect for the feelings of others","cn":"有礼貌的；客气的；儒雅的","ex":{"en":"The receptionist smiled politely.","cn":"接待员礼貌地微笑着。"}},{"en":"in a way that is socially correct but not always sincere","cn":"应酬的；礼节性的；客套的","ex":{"en":"The boring speech finished and everyone clapped politely.","cn":"无聊的演讲结束了，大家礼貌地鼓掌。"}}]},"media":{"uk":"media/uk/politely__gb_1.mp3","us":"media/us/politely__us_1.mp3"},"examples":[{"en":"She’s always very polite.","cn":""},{"en":"We left the party as soon as it was polite to do so.","cn":""}]},"pod":{"oxford":{"phon":"pɒd","pos":"noun","senses":[{"en":"a long thin case filled with seeds that develops from the flowers of some plants, especially peas and beans","cn":"荚；豆荚；荚果","ex":{"en":"a pea pod","cn":"豌豆荚"}},{"en":"a small plastic container with something inside it","cn":"小包；小袋","ex":{"en":"Single-use coffee pods are the fastest growing segment of the industry.","cn":"一次性咖啡包是该行业增长最快的部分。"}},{"en":"a long narrow container that is hung under an aircraft and used to carry fuel, equipment, weapons, etc.","cn":"（飞机的）吊舱，发射架"},{"en":"part of a spacecraft or a boat that can be separated from the main part","cn":"分离舱"},{"en":"a small group of sea animals, such as dolphins or whales, swimming together","cn":"（海豚或鲸等海洋动物的）一小群","g":"[countable]","ex":{"en":"a pod of adult dolphins","cn":"一小群成年海豚"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"荚；荚果；豆荚","en":"A pod is a seed container that grows on plants such as peas or beans.","ex":{"en":"...fresh peas in the pod.","cn":"豆荚里的新鲜豌豆"}}]},"media":{"img":["media/pic/peas_beans_comp.jpg","media/thumb/pea.jpg"],"uk":"media/uk/pod__gb_1.mp3","us":"media/us/pod__us_1.mp3"},"examples":[{"en":"a pod of adult dolphins","cn":"一群成年海豚"},{"en":"a vanilla pod","cn":"香子兰蒴果"}]},"pole":{"oxford":{"phon":"pəʊl","pos":"noun","senses":[{"en":"a long thin straight piece of wood or metal, especially one with the end placed in the ground, used as a support","cn":"竿；杆子；杖；篙","ex":{"en":"a tent pole","cn":"帐篷支柱"}},{"en":"either of the two points at the opposite ends of the line on which the earth or any other planet turns","cn":"（行星的）极；地极","ex":{"en":"the North/South Pole","cn":"北极；南极"}},{"en":"either of the two ends of a magnet, or the positive or negative points of an electric battery","cn":"磁极；电极","lab":"physics"},{"en":"either of two opposite or very different extremes","cn":"（对立或截然不同的）一方；极端","ex":{"en":"Their opinions were at opposite poles of the debate.","cn":"他们的意见在辩论中截然相反。"}},{"en":"to move a boat by pushing on the bottom of a river, etc. with a pole","cn":"用篙撑船；摆船","ex":{"en":"He hired a punt and poled upstream.","cn":"他租了一艘平底船，撑着竿向上游走去。"},"pos":"verb"},{"en":"a person from Poland","cn":"波兰人"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"波兰人","en":"A Pole is a Polish citizen, or a person of Polish origin."},{"pos":"N-COUNT 可数名词","cn":"（尤用于支撑的）杆","en":"A pole is a long thin piece of wood or metal, used especially for supporting things.","ex":{"en":"The truck crashed into a telegraph pole","cn":"卡车撞到了电线杆上。"}},{"pos":"N-COUNT 可数名词","cn":"（地）极","en":"The earth's poles are the two opposite ends of its axis, its most northern and southern points.","ex":{"en":"For six months of the year, there is hardly any light at the poles.","cn":"在南北极，每年有6个月时间几乎没有光照。"}},{"pos":"N-COUNT 可数名词","cn":"（特质、意见或信仰）截然相反的两极之一；极端","en":"The two poles of a range of qualities, opinions, or beliefs are the completely opposite qualities, opinions, or beliefs at either end of the range.","ex":{"en":"The two politicians represent opposite poles of the political spectrum.","cn":"这两位从政者代表了政界的两个极端。"}},{"pos":"PHRASE 短语","cn":"（信仰、意见或性质）截然相反，南辕北辙","en":"If you say that two people or things are poles apart, you mean that they have completely different beliefs, opinions, or qualities."}]},"media":{"uk":"media/uk/pole__gb_1.mp3","us":"media/us/pole__us_1.mp3"},"examples":[{"en":"Their opinions were at opposite poles of the debate.","cn":"他们的意见在辩论中截然相反。"},{"en":"the North/South Pole","cn":"北极；南极"}]},"pour":{"oxford":{"phon":"pɔː(r)","pos":"verb","senses":[{"en":"to make a liquid or other substance flow from a container in a continuous stream, especially by holding the container at an angle","cn":"使（液体）连续流出；倾倒；倒出","g":"[transitive]","ex":{"en":"Pour the sauce over the pasta.","cn":"把酱汁浇在意大利面食上。"}},{"en":"to serve a drink by letting it flow from a container into a cup or glass","cn":"倒，斟（饮料）","g":"[transitive, intransitive]","ex":{"en":"Will you pour the coffee?","cn":"你来倒咖啡好吗？"}},{"en":"when rain pours down or when it’s pouring (with) rain, rain is falling heavily","cn":"（雨）倾盆而下；下大雨","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"It's pouring outside.","cn":"外面下着瓢泼大雨。"}},{"en":"to flow quickly in a continuous stream","cn":"涌流；倾泻；喷发","g":"[intransitive]","lab":"figurative","ex":{"en":"Tears poured down his cheeks.","cn":"眼泪顺着他的面颊簌簌地落下。"}},{"en":"to come or go somewhere continuously in large numbers","cn":"不断涌向（或涌现）","g":"[intransitive]","ex":{"en":"The crowd poured into the streets.","cn":"人群涌向街道。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使（液体等）连续流出；倾倒；倒出","en":"If you pour a liquid or other substance, you make it flow steadily out of a container by holding the container at an angle.","ex":{"en":"Pour a pool of sauce on two plates and arrange the meat neatly","cn":"在两个盘子里倒少许沙司酱，然后把肉摆放整齐。"}},{"pos":"VERB 动词","cn":"（给…）斟，倒（饮料等）","en":"If you pour someone a drink, you put some of the drink in a cup or glass so that they can drink it.","ex":{"en":"He got up and poured himself another drink","cn":"他站起身来，给自己又倒了一杯。"}},{"pos":"VERB 动词","cn":"（液体等）倾泻，涌流，喷发","en":"When a liquid or other substance pours somewhere, for example through a hole, it flows quickly and in large quantities.","ex":{"en":"Blood was pouring from his broken nose","cn":"血从他受伤的鼻子里涌出来。"}},{"pos":"VERB 动词","cn":"（雨）倾盆而下，倾泻","en":"When it rains very heavily, you can say that it is pouring.","ex":{"en":"It has been pouring in Delhi almost non stop for the past three days, disrupting normal life","cn":"德里市在过去的3天里一直在下着倾盆大雨，几乎没有停过，扰乱了人们的正常生活。"}},{"pos":"VERB 动词","cn":"（人）大量涌入（或涌出），蜂拥","en":"If people pour into or out of a place, they go there quickly and in large numbers.","ex":{"en":"Any day now, the Northern forces may pour across the new border","cn":"北方的军队现在随时都可能大批越过新边界。"}},{"pos":"VERB 动词","cn":"（信息等）大量涌来，源源而来","en":"If something such as information pours into a place, a lot of it is obtained or given.","ex":{"en":"Martin, 78, died yesterday. Tributes poured in from around the globe","cn":"马丁于昨天去世，享年78岁。世界各地的人们纷纷致以哀悼。"}},{"pos":"PHRASE 短语","cn":"向（计划或想法）泼冷水","en":"If someone pours cold water on a plan or idea, they criticize it so much that people lose their enthusiasm for it.","ex":{"en":"The education secretary poured cold water on the recommendations of a working party.","cn":"教育大臣对一个工作小组的建议泼冷水。"}},{"pos":"","cn":"","en":"to pour scorn on something→see: ; to pour cold water on something→see: ;"},{"pos":"","cn":"","en":"相关词组：pour into pour out"}]},"media":{"uk":"media/uk/pour__gb_1.mp3","us":"media/us/pour__us_1.mp3","img":["media/ldoce/img/pour.jpg"]},"examples":[{"en":"She poured out her troubles to me over a cup of coffee.","cn":"她一面喝着咖啡，一面向我倾吐着她的烦恼。"},{"en":"Although I poured it carefully, I still managed to spill some.","cn":"尽管我倒这东西很小心，还是洒了一些。"}]},"populous":{"media":{"uk":"media/uk/populous__gb_1.mp3","us":"media/us/populous__us_1.mp3"},"oxford":{"phon":"ˈpɒpjələs","pos":"adjective","senses":[{"en":"where a large number of people live","cn":"人口众多的；人口密集的","ex":{"en":"one of America’s most populous states","cn":"美国人口大州之一"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"人口众多的；人口稠密的","en":"A populous country or area has a lot of people living in it.","ex":{"en":"Indonesia, with 216 million people, is the fourth most populous country in the world.","cn":"有2.16亿人的印度尼西亚是世界第四人口大国。"}}]},"examples":[{"en":"one of America's most populous states","cn":"美国人口最多的州之一"},{"en":"Hong Kong is one of the most populous areas in the world.","cn":"香港是世界上人口最稠密的地区之一。"}]},"polish":{"media":{"uk":"media/uk/polish__gb_1.mp3","us":"media/us/polish__us_1.mp3","img":["media/ldoce/img/polish.jpg"]},"oxford":{"phon":"ˈpɒlɪʃ","pos":"noun","senses":[{"en":"a substance used when rubbing a surface to make it smooth and shiny","cn":"擦光剂；上光剂；亮光剂","g":"[uncountable, countable]","ex":{"en":"furniture/floor/shoe/silver polish","cn":"家具上光漆；地板蜡；鞋油；银光剂"}},{"en":"an act of polishing something","cn":"抛光；上光；擦亮","g":"[singular]","ex":{"en":"I give it a polish now and again.","cn":"我不时把它抛一抛光。"}},{"en":"the shiny appearance of something after it has been polished","cn":"擦光的面；打磨光亮的面","g":"[singular]"},{"en":"a high quality of performance achieved with great skill","cn":"（表演的）完美，娴熟，精湛","g":"[uncountable]","ex":{"en":"She played the cello with the polish of a much older musician.","cn":"她演奏大提琴颇有资深演奏家的风范。"}},{"en":"high standards of behaviour; being polite","cn":"文雅；优雅；品味；礼貌","g":"[uncountable]","ex":{"en":"She thought that her husband’s family lacked polish.","cn":"她认为丈夫的家庭缺乏光彩。"}},{"en":"to make something smooth and shiny by rubbing it","cn":"擦光；磨光；抛光","g":"[transitive, intransitive]","ex":{"en":"Polish shoes regularly to protect the leather.","cn":"要经常擦鞋，以保护皮革。"},"pos":"verb"},{"en":"to make changes to something in order to improve it","cn":"修改；润饰；润色","g":"[transitive]","ex":{"en":"The statement was carefully polished and checked before release.","cn":"这项声明是经仔细润色检查后才发表的。"},"pos":"verb"},{"en":"from or connected with Poland, its people or its language","cn":"波兰的","pos":"adjective"},{"en":"the language of Poland","cn":"波兰语"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"波兰的；波兰人的；波兰语（或文化）的","en":"Polish means belonging or relating to Poland, or to its people, language, or culture.","ex":{"en":"The press conference was broadcast live on Polish television.","cn":"波兰电视台现场直播了记者招待会。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"波兰语","en":"Polish is the language spoken in Poland."}]},"examples":[{"en":"The hotel has polished up its act (= improved its service) since last year.","cn":"这家酒店自去年以来已经改善了服务水平。"},{"en":"The statement was carefully polished and checked before release.","cn":"这项声明是经仔细润色检查后才发表的。"}]},"pollen":{"oxford":{"phon":"ˈpɒlən","pos":"noun","senses":[{"en":"fine powder, usually yellow, that is formed in flowers and carried to other flowers of the same kind by the wind or by insects, to make those flowers produce seeds","cn":"花粉","ex":{"en":"bees gathering pollen","cn":"正在采集花粉的蜜蜂"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"花粉","en":"Pollen is a fine powder produced by flowers. It fertilizes other flowers of the same species so that they produce seeds."}]},"media":{"uk":"media/uk/pollen__gb_1.mp3","us":"media/us/pollen__us_1.mp3"}},"polished":{"oxford":{"phon":"ˈpɒlɪʃt","pos":"adjective","senses":[{"en":"shiny as a result of polishing","cn":"抛光的；磨光的；擦亮的","ex":{"en":"a highly polished floor","cn":"擦得很亮的地板"}},{"en":"confident, impressive and/or showing a lot of skill","cn":"精湛的；娴熟的","ex":{"en":"polished manners","cn":"优雅的风度"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优雅的；有教养的","en":"Someone who is polished shows confidence and knows how to behave socially.","ex":{"en":"He is polished, charming, articulate and an excellent negotiator.","cn":"他文雅、迷人、能言善辩，是一名优秀的谈判人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"完美无缺的；炉火纯青的","en":"If you describe a performance, ability, or skill as polished, you mean that it is of a very high standard.","ex":{"en":"It was simply a very polished performance.","cn":"这简直就是一场完美的演出。"}}]},"media":{"uk":"media/uk/polished__gb_1.mp3","us":"media/us/polished__us_1.mp3"},"examples":[{"en":"highly polished boots","cn":"擦得很亮的靴子"},{"en":"a polished performance","cn":"精彩的演出"}],"base":"polish"},"pots":{"lemma":"pot","media":{"uk":"media/uk/pot__gb_1.mp3","us":"media/us/pot__us_1.mp3"}},"pork":{"media":{"uk":"media/uk/pork__gb_1.mp3","us":"media/us/pork__us_1.mp3"},"oxford":{"phon":"pɔːk","pos":"noun","senses":[{"en":"meat from a pig that has not been cured (= preserved using salt or smoke)","cn":"猪肉","ex":{"en":"roast pork","cn":"烤猪肉"}},{"en":"local projects that are given a lot of government money in order to win votes; the money that is used","cn":"分肥项目，分肥拨款（议员等为争取选票而促使政府拨款给所属地区的发展项目）","lab":"North American English, informal，，"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（通常指新鲜的）猪肉","en":"Pork is meat from a pig, usually fresh and not smoked or salted.","ex":{"en":"...fried pork chops.","cn":"炸猪排"}}]},"examples":[{"en":"roast pork","cn":"烤猪肉"},{"en":"a leg of pork","cn":"猪腿肉"}]},"powered":{"oxford":{"phon":"ˈpaʊəd","pos":"adjective","senses":[{"en":"operated by a form of energy such as electricity or by the type of energy mentioned","cn":"由…驱动的；电动的","ex":{"en":"a powered wheelchair","cn":"电动轮椅"}}]},"media":{"uk":"media/uk/powered__gb_1.mp3","us":"media/us/powered__us_1.mp3"},"examples":[{"en":"a solar-powered calculator","cn":"太阳能电池计算器"},{"en":"a powered wheelchair","cn":"电动轮椅"}],"base":"power"},"popular":{"media":{"uk":"media/uk/popular__gb_1.mp3","us":"media/us/popular__us_1.mp3"},"oxford":{"phon":"ˈpɒpjələ(r)","pos":"adjective","senses":[{"en":"liked or enjoyed by a large number of people","cn":"大众喜爱的；广受欢迎的；当红的","lab":"ironic","ex":{"en":"Andalucia is a popular tourist destination.","cn":"安达卢西亚是一个受欢迎的旅游目的地。"}},{"en":"right or appropriate for the taste and knowledge of ordinary people","cn":"通俗的；大众化的","g":"[only before noun]","lab":"sometimes disapproving","ex":{"en":"popular music/songs/culture/fiction","cn":"流行音乐／歌曲／文化／小说"}},{"en":"shared by a large number of people","cn":"普遍的；大众的；流行的","g":"[only before noun]","ex":{"en":"There's a popular misconception that it's a difficult instrument to play.","cn":"人们普遍误解它是一种很难演奏的乐器。"}},{"en":"connected with the ordinary people of a country","cn":"民众的；百姓的","g":"[only before noun]","ex":{"en":"The party still has widespread popular support.","cn":"这个政党仍然广受民众支持。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"受喜爱的；受欢迎的；当红的","en":"Something that is popular is enjoyed or liked by a lot of people.","ex":{"en":"This is the most popular ball game ever devised","cn":"这是有史以来发明出的最受欢迎的球类运动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）讨人喜欢的，得人心的","en":"Someone who is popular is liked by most people, or by most people in a particular group.","ex":{"en":"He remained the most popular politician in France","cn":"他一直是法国最受人爱戴的政治家。"}},{"pos":"ADJ 形容词","cn":"（报纸、电视节目、艺术形式等）通俗的，流行的，大众化的","en":"Popular newspapers, television programmes, or forms of art are aimed at ordinary people and not at experts or intellectuals.","ex":{"en":"Once again the popular press in Britain has been rife with stories about their marriage.","cn":"英国通俗报刊又一次对他们的婚姻进行了铺天盖地的报道。"}},{"pos":"ADJ 形容词","cn":"（想法、情绪或态度）普遍的","en":"Popular ideas, feelings, or attitudes are approved of or held by most people.","ex":{"en":"Contrary to popular belief, the oil companies can't control the price of crude","cn":"与人们普遍的看法相反，石油公司并不能控制原油价格。"}},{"pos":"ADJ 形容词","cn":"（政治活动）民众的，人民的","en":"Popular is used to describe political activities which involve the ordinary people of a country, and not just members of political parties.","ex":{"en":"The late President Ferdinand Marcos was overthrown by a popular uprising in 1986.","cn":"已故总统费迪南德·马科斯于1986年被民众起义赶下了台。"}}]},"examples":[{"en":"( ironic ) ‘Our dog got into the neighbour's garden again!’ ‘You'll be popular.’ “","cn":"我们的狗又钻进邻家的花园了！” “你要有好受的了。”"},{"en":"These policies are unlikely to prove popular with middle-class voters.","cn":"这些政策不大可能博得中产阶级选民的欢心。"}]},"pow":{"oxford":{"phon":"paʊ","pos":"exclamation","senses":[{"en":"used to express the sound of an explosion, a gun firing or somebody hitting somebody else","cn":"（爆炸声、枪声或打人的声音）嘭，乒，砰"},{"en":"a person, usually a member of the armed forces, who is captured by the enemy during a war and kept in a prison camp until the war has finished (the abbreviation for ‘prisoner of war’)","cn":"战俘，俘虏（全写为 prisoner of war）","ex":{"en":"a POW camp","cn":"战俘营"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 prisoner of war","en":"A POW is the same as a prisoner of war ."}]},"media":{"uk":"media/uk/pow__gb_1.mp3","us":"media/us/pow__us_1.mp3"},"examples":[{"en":"a POW camp","cn":"战俘营"}]},"politically":{"media":{"uk":"media/uk/politically__gb_1.mp3","us":"media/us/politically__us_1.mp3"},"oxford":{"phon":"pəˈlɪtɪkli","pos":"adverb","senses":[{"en":"in a way that is connected with politics","cn":"政治上","ex":{"en":"a politically sensitive issue","cn":"一个政治上敏感的议题"}}]},"examples":[{"en":"It makes sense politically as well as economically.","cn":"这在经济上和政治上都有道理。"},{"en":"a politically sensitive issue","cn":"一个政治上敏感的议题"}]},"positive":{"media":{"uk":"media/uk/positive__gb_1.mp3","us":"media/us/positive__us_1.mp3"},"oxford":{"phon":"ˈpɒzətɪv","pos":"adjective","senses":[{"en":"good or useful","cn":"良好的；有助益的；正面的","sc":"effective/useful","ex":{"en":"The tests have so far yielded positive results.","cn":"到目前为止，测试已取得积极结果。"}},{"en":"expressing agreement or support","cn":"表示赞同的；拥护的","sc":"effective/useful","ex":{"en":"It's always nice to get positive feedback.","cn":"得到赞赏的回应总是令人高兴。"}},{"en":"directed at dealing with something or producing a successful result","cn":"积极的；建设性的；朝着成功的","sc":"effective/useful","ex":{"en":"We must take positive steps to deal with the problem.","cn":"我们必须采取积极措施处理这个问题。"}},{"en":"thinking about what is good in a situation; feeling confident and sure that something good will happen","cn":"积极乐观的；自信的","sc":"confident","ex":{"en":"a positive attitude/outlook","cn":"乐观的态度／前景"}},{"en":"showing clear evidence that a particular substance or medical condition is present","cn":"阳性的；证明…存在的","sc":"scientific test","ex":{"en":"a positive pregnancy test","cn":"呈阳性反应的怀孕检测"}},{"en":"completely sure that something is correct or true","cn":"有绝对把握；确信；肯定","g":"[not before noun]","sc":"sure/definite","ex":{"en":"I can't be positive about what time it happened.","cn":"我说不准这事是什么时间发生的。"}},{"en":"giving clear and definite proof or information","cn":"证据确凿的；明确的","lab":"formal","sc":"sure/definite","ex":{"en":"The results show a positive correlation between exercise and self-esteem.","cn":"结果显示锻炼与自尊之间存在正相关。"}},{"en":"complete and definite","cn":"完全的；绝对的","g":"[only before noun]","lab":"informal","sc":"sure/definite","ex":{"en":"He has a positive genius for upsetting people.","cn":"他气人的本事可大呢。"}},{"en":"expressing something that is true, did happen, etc.; not containing words such as ‘no’, ‘not’, ‘never’, etc.","cn":"肯定的","sc":"grammar","ex":{"en":"A positive statement has a negative question tag.","cn":"积极的陈述有消极的问号。"}},{"en":"greater than zero","cn":"正数的","sc":"number/quantity"},{"en":"containing or producing the type of electricity that is carried by a proton","cn":"正电的；正极的","lab":"specialist","sc":"electricity","ex":{"en":"a positive charge","cn":"正电荷"}},{"en":"a good or useful quality or aspect","cn":"优势；优点","g":"[countable, uncountable]","sc":"good quality","ex":{"en":"What are the positives and negatives of going this route?","cn":"走这条路线的优劣各是什么？"},"pos":"noun"},{"en":"the result of a test or an experiment that shows that a substance or condition is present","cn":"阳性结果（或反应）","g":"[countable]","sc":"result of test","ex":{"en":"The result can be a false positive—indicating a problem where none actually exists.","cn":"结果可能是假阳性，即显示有问题，但其实没有问题。"},"pos":"noun"},{"en":"a developed film showing light and dark areas and colours as they actually were, especially one printed from a negative","cn":"正片","g":"[countable]","lab":"specialist","sc":"in photography","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"抱有希望的；有信心的；积极的","en":"If you are positive about things, you are hopeful and confident, and think of the good aspects of a situation rather than the bad ones.","ex":{"en":"Be positive about your future and get on with living a normal life","cn":"要对自己的未来充满信心，继续过一种正常的生活。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愉悦的；有益的","en":"A positive fact, situation, or experience is pleasant and helpful to you in some way.","ex":{"en":"The parting from his sister had a positive effect on John","cn":"和姐姐分开对约翰来说有好处。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明确的；果断的","en":"If you make a positive decision or take positive action, you do something definite in order to deal with a task or problem.","ex":{"en":"There are positive changes that should be implemented in the rearing of animals","cn":"应该对动物饲养进行明确的改革。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"积极的；肯定的","en":"A positive response to something indicates agreement, approval, or encouragement.","ex":{"en":"There's been a positive response to the UN Secretary-General's recent peace efforts.","cn":"联合国秘书长近期为和平所作出的努力得到了积极的回应。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有把握的；确信的","en":"If you are positive about something, you are completely sure about it.","ex":{"en":"I'm as positive as I can be about it","cn":"我对它有绝对的把握。"}},{"pos":"ADJ 形容词","cn":"（证据）确凿的，毋庸置疑的","en":"Positive evidence gives definite proof of the truth or identity of something.","ex":{"en":"There was no positive evidence that any birth defects had arisen as a result of Vitamin A intake.","cn":"没有确凿证据证明，摄取维生素A会导致出生缺陷。"}},{"pos":"ADJ 形容词","cn":"（化验或试验结果）阳性的","en":"If a medical or scientific test is positive, it shows that something has happened or is present. HIV positive→see: ;","ex":{"en":"If the test is positive, a course of antibiotics may be prescribed","cn":"如果化验结果呈阳性，可能会开一个疗程的抗生素。"}},{"pos":"ADJ 形容词","cn":"（强调名词）完完全全的，千真万确的，实实在在的","en":"You can use positive to emphasize a noun.","ex":{"en":"Good day to you, Bernard! It's a positive delight to see you","cn":"你好，伯纳德！见到你真高兴。"}},{"pos":"ADJ 形容词","cn":"（数字）正的，大于零的","en":"A positive number is greater than zero.","ex":{"en":"It's really a simple numbers game with negative and positive numbers.","cn":"它其实就是正负数的简单数字游戏。"}},{"pos":"ADJ 形容词","cn":"带正电的；阳极的","en":"If something has a positive electrical charge, it has the same charge as a proton and the opposite charge to an electron."},{"pos":"","cn":"","en":"proof positive→see: ;"}]},"examples":[{"en":"We must take positive steps to deal with the problem.","cn":"我们必须采取积极步骤处理这个问题。"},{"en":"We have no positive evidence that she was involved.","cn":"我们没有确凿证据证明她参与其事。"}]},"pollutant":{"media":{"uk":"media/uk/pollutant__gb_1.mp3","us":"media/us/pollutant__us_1.mp3"},"oxford":{"phon":"pəˈluːtənt","pos":"noun","senses":[{"en":"a substance that pollutes something, especially air and water","cn":"污染物；污染物质","ex":{"en":"pollutants from nearby industries","cn":"附近工厂排放的污染物"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"污染物（尤指车辆尾气和工业有毒化学废弃物）","en":"Pollutants are substances that pollute the environment, especially gases from vehicles and poisonous chemicals produced as waste by industrial processes.","ex":{"en":"A steady stream of California traffic clogs the air with pollutants.","cn":"加利福尼亚川流不息的车流使空气中充斥着污染物。"}}]}},"popularity":{"media":{"uk":"media/uk/popularity__gb_1.mp3","us":"media/us/popularity__us_1.mp3"},"oxford":{"phon":"ˌpɒpjuˈlærəti","pos":"noun","senses":[{"en":"the state of being liked, enjoyed or supported by a large number of people","cn":"受欢迎；普及；流行","ex":{"en":"the increasing popularity of cycling","cn":"自行车运动的日益风行"}}]},"examples":[{"en":"Her novels have gained in popularity over recent years.","cn":"近年来她的小说渐受欢迎。"},{"en":"to win/lose popularity with the students","cn":"受到/不受学生的欢迎"}]},"port":{"oxford":{"phon":"pɔːt","pos":"noun","senses":[{"en":"a town or city with a harbour, especially one where ships load and unload goods","cn":"港口城市；口岸城市","g":"[countable]","ex":{"en":"a container/fishing port","cn":"集装箱港；渔港"}},{"en":"a place where ships load and unload goods or shelter from storms","cn":"港口；避风港","g":"[countable, uncountable]","ex":{"en":"a naval port","cn":"军港"}},{"en":"a strong sweet wine, usually dark red, that is made in Portugal. It is usually drunk at the end of a meal.","cn":"波尔图葡萄酒（葡萄牙产）","g":"[uncountable]"},{"en":"a glass of port","cn":"一杯波尔图葡萄酒","g":"[countable]"},{"en":"the side of a ship or aircraft that is on the left when you are facing forward","cn":"（船、飞机等的）左舷","g":"[uncountable]","ex":{"en":"the port side","cn":"左舷"}},{"en":"a place on a computer where you can attach another piece of equipment, often using a cable","cn":"（输出或输入）端口，接口","g":"[countable]","lab":"computing","ex":{"en":"the modem port","cn":"调制解调器端口"}},{"en":"to copy software from one system or machine to another","cn":"移植（软件）","lab":"computing","ex":{"en":"Is there a problem with apps ported from another platform?","cn":"从另一个平台移入的应用程序是否会有问题？"},"pos":"verb"},{"en":"to continue to use the same number when you change from one phone company to another","cn":"（更换电话公司时）携带（电话号码）","ex":{"en":"how to port your number to a new mobile phone","cn":"如何携号使用新手机"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"港市；口岸","en":"A port is a town by the sea or on a river, which has a harbour.","ex":{"en":"Port-Louis is an attractive little fishing port.","cn":"路易港是个漂亮的小渔港。"}},{"pos":"N-COUNT 可数名词","cn":"港；港口","en":"A port is a harbour area where ships load and unload goods or passengers.","ex":{"en":"...the bridges which link the port area to the city centre.","cn":"连接港区和市中心的桥梁"}},{"pos":"N-COUNT 可数名词","cn":"（外接设备的）端口","en":"A port on a computer is a place where you can attach another piece of equipment, for example a printer."},{"pos":"ADJ 形容词","cn":"左舷的","en":"In sailing, the port side of a ship is the left side when you are on it and facing towards the front.","ex":{"en":"Her official number is carved on the port side of the forecabin.","cn":"这艘船的注册编号刻在前舱的左舷上。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"波尔图葡萄酒","en":"Port is a type of strong, sweet red wine.","ex":{"en":"He asked for a glass of port after dinner.","cn":"晚饭后，他要了一杯波尔图葡萄酒。"}}]},"media":{"uk":"media/uk/port__gb_1.mp3","us":"media/us/port__us_1.mp3"},"examples":[{"en":"Rotterdam is a major port.","cn":"鹿特丹是一个重要的港口城市。"},{"en":"The ship spent four days in port.","cn":"这艘船在港口停泊了四天。"}]},"poor":{"media":{"uk":"media/uk/poor__gb_1.mp3","us":"media/us/poor__us_1.mp3"},"oxford":{"phon":"pɔː(r)","pos":"adjective","senses":[{"en":"having very little money; not having enough money for basic needs","cn":"贫穷的；贫寒的；清贫的","sc":"having little money","ex":{"en":"They were too poor to buy shoes for the kids.","cn":"他们穷得没钱给孩子买鞋。"}},{"en":"people who have very little money","cn":"贫困者；穷人","g":"[plural]","sc":"having little money","ex":{"en":"They provided food and shelter for the poor.","cn":"他们为贫困者提供食物和住所。"}},{"en":"deserving sympathy","cn":"可怜的；令人同情的","g":"[only before noun]","sc":"unfortunate","ex":{"en":"Have you heard about poor old Harry? His wife's left him.","cn":"你听说了老哈里的惨况吗？他妻子离他而去了。"}},{"en":"not good; of a quality that is low or lower than expected","cn":"劣质的；差的；次的","sc":"not good","ex":{"en":"the party’s poor performance in the election","cn":"该党在选举中欠佳的表现"}},{"en":"not good at something","cn":"不善于…的；不擅长…的；（能力）弱的","g":"[usually before noun]","sc":"not good","ex":{"en":"a poor swimmer","cn":"不擅游泳的人"}},{"en":"having very small amounts of something","cn":"缺乏；贫乏；缺少","sc":"having little of something","ex":{"en":"a country poor in natural resources","cn":"自然资源贫乏的国家"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）贫穷的，贫困的","en":"Someone who is poor has very little money and few possessions.","ex":{"en":"The reason our schools cannot afford better teachers is because people here are poor","cn":"我们的学校请不起好老师的原因是因为这里的人穷。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（国家、地区等）贫穷的，贫困的","en":"The people in a poor country or area have very little money and few possessions.","ex":{"en":"Many countries in the Third World are as poor as they have ever been.","cn":"很多第三世界国家仍和过去一样穷困。"}},{"pos":"ADJ 形容词","cn":"可怜的；不幸的","en":"You use poor to express your sympathy for someone.","ex":{"en":"I feel sorry for that poor child","cn":"我为那个可怜的孩子感到难过。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"劣质的；糟糕的","en":"If you describe something as poor, you mean that it is of a low quality or standard or that it is in bad condition.","ex":{"en":"The flat was in a poor state of repair","cn":"公寓严重失修。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（数量、比率等）不理想的，不合理的","en":"If you describe an amount, rate, or number as poor, you mean that it is less than expected or less than is considered reasonable.","ex":{"en":"...poor wages and working conditions.","cn":"低薪和恶劣的工作条件"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不熟练的；蹩脚的","en":"You use poor to describe someone who is not very skilful in a particular activity.","ex":{"en":"He was a poor actor","cn":"他是个蹩脚的演员。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贫乏的；缺少的","en":"If something is poor in a particular quality or substance, it contains very little of the quality or substance.","ex":{"en":"Fats and sugar are very rich in energy but poor in vitamins, minerals and dietary fibre.","cn":"脂肪和糖类热量很高，但维生素、矿物质和膳食纤维贫乏。"}}]},"examples":[{"en":"‘I have stacks of homework to do.’ ‘Oh, you poor thing. ’ “","cn":"我有一大堆的作业要做哪。” “唉呦，你好可怜哦。”"},{"en":"Have you heard about poor old Harry? His wife's left him.","cn":"你听说了老哈里的惨况吗？他妻子离他而去了。"}]},"pounce":{"media":{"uk":"media/uk/pounce__gb_1.mp3","us":"media/us/pounce__us_1.mp3","img":["media/ldoce/img/ldoce_270.png"]},"oxford":{"phon":"paʊns","pos":"verb","senses":[{"en":"to move suddenly forwards in order to attack or catch somebody/something","cn":"猛扑；突袭","ex":{"en":"The lion crouched ready to pounce.","cn":"狮子蹲下身，准备猛扑。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（人）猛扑，突袭","en":"If someone pounces on you, they come up towards you suddenly and take hold of you.","ex":{"en":"He pounced on the photographer, beat him up and smashed his camera","cn":"他突然扑向摄影师，痛打了他一顿，还摔碎了他的照相机。"}},{"pos":"VERB 动词","cn":"揪出，抓住（错误等）","en":"If someone pounces on something such as a mistake, they quickly draw attention to it, usually in order to gain an advantage for themselves or to prove that they are right.","ex":{"en":"The Democrats were ready to pounce on any Republican failings or mistakes","cn":"民主党人随时准备揪出共和党人的过失或错误。"}},{"pos":"VERB 动词","cn":"（野兽或飞禽）猛扑，突袭","en":"When an animal or bird pounces on something, it jumps on it and holds it, in order to kill it.","ex":{"en":"...like a tiger pouncing on its prey","cn":"像老虎猛扑向猎物一样"}}]},"examples":[{"en":"Rooney pounced on the loose ball and scored.","cn":"鲁尼对准无人控制的球飞起一脚，破门得分。"},{"en":"The muggers pounced on her as she got out of the car.","cn":"她一下汽车，劫匪便向她扑上去。"}]},"polo":{"media":{"img":["media/pic/equestriansports_comp.jpg","media/thumb/polo.jpg"],"uk":"media/uk/polo__gb_1.mp3","us":"media/us/polo__us_1.mp3"},"oxford":{"phon":"ˈpəʊləʊ","pos":"noun","senses":[{"en":"a game in which two teams of players riding on horses try to hit a ball into a goal using mallets (= sticks with a block of wood at one end)","cn":"马球（运动）"},{"en":"a popular British peppermint sweet, sold in tubes. Polo mints are round with a hole in the middle. They are advertised as ‘the mint with the hole’. Polos are also made with fruit flavours.","cn":"一种流行的英国薄荷糖，以管装出售。马球薄荷糖是圆形的，中间有一个洞。他们被宣传为“有洞的薄荷”。水果口味也可以制成波罗。","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"马球（运动）","en":"Polo is a game played between two teams of players. The players ride horses and use wooden hammers with long handles to hit a ball."}]}},"potential":{"media":{"uk":"media/uk/potential__gb_1.mp3","us":"media/us/potential__us_1.mp3"},"oxford":{"phon":"pəˈtenʃl","pos":"adjective","senses":[{"en":"that can develop into something or be developed in the future","cn":"潜在的；可能的","ex":{"en":"potential customers/buyers/investors/clients","cn":"潜在顾客／买家／投资者／客户"}},{"en":"the possibility of something happening or being developed or used","cn":"可能性；潜在性","g":"[uncountable]","ex":{"en":"the potential for change","cn":"变革的可能性"},"pos":"noun"},{"en":"qualities that exist and can be developed","cn":"潜力；潜质","g":"[uncountable]","ex":{"en":"All children should be encouraged to realize their full potential.","cn":"应当鼓励所有的儿童充分发挥他们的潜能。"},"pos":"noun"},{"en":"the difference in voltage between two points in an electric field or circuit","cn":"电位；电势；电压","g":"[uncountable, countable]","lab":"physics","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"潜在的；可能的","en":"You use potential to say that someone or something is capable of developing into the particular kind of person or thing mentioned.","ex":{"en":"The firm has identified 60 potential customers at home and abroad","cn":"该公司已在国内外找到60个潜在客户。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"潜力；潜质","en":"If you say that someone or something has potential, you mean that they have the necessary abilities or qualities to become successful or useful in the future.","ex":{"en":"The boy has great potential","cn":"这个男孩非常有潜质。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"可能性；潜在性","en":"If you say that someone or something has potential for doing a particular thing, you mean that it is possible they may do it. If there is the potential for something, it may happen.","ex":{"en":"John seemed as horrified as I about his potential for violence","cn":"约翰似乎和我一样害怕他自己会使用暴力。"}}]},"examples":[{"en":"First we need to identify actual and potential problems.","cn":"首先，我们需要弄清实际的问题和潜在的问题。"},{"en":"All children should be encouraged to realize their full potential.","cn":"应当鼓励所有的儿童充分发挥他们的潜能。"}]},"policeman":{"media":{"uk":"media/uk/policeman__gb_1.mp3","us":"media/us/policeman__us_1.mp3"},"oxford":{"phon":"pəˈliːsmən","pos":"noun","senses":[{"en":"a male police officer","cn":"（男）警察","lab":"British English","ex":{"en":"a plain-clothes/uniformed policeman","cn":"便衣／穿制服的警察"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男警察","en":"A policeman is a man who is a member of the police force."}]}},"possible":{"media":{"uk":"media/uk/possible__gb_1.mp3","us":"media/us/possible__us_1.mp3"},"oxford":{"phon":"ˈpɒsəbl","pos":"adjective","senses":[{"en":"that can be done or achieved","cn":"可能；能做到（或取得）","g":"[not usually before noun]","lab":"North American English","ex":{"en":"New technology has made it possible to communicate more easily.","cn":"新技术使沟通变得更容易。"}},{"en":"that might exist or happen but is not certain to","cn":"可能存在（或发生）的","ex":{"en":"the possible side effects of the drug","cn":"这种药可能产生的副作用"}},{"en":"reasonable or acceptable in a particular situation","cn":"合理的；可接受的","ex":{"en":"There are several possible explanations.","cn":"有几种合理的解释。"}},{"en":"used after adjectives to emphasize that something is the best, worst, etc. of its type","cn":"（用于形容词后表示强调）最…的","ex":{"en":"It was the best possible surprise anyone could have given me.","cn":"那是我曾感受过的最大惊喜。"}},{"en":"a person or thing that is suitable for a particular job, purpose, etc. and might be chosen","cn":"合适的人（或物）；恰当人选（或事项）","ex":{"en":"Out of all the people interviewed, there are only five possibles.","cn":"在所有面试过的人中，仅有五个合适的人选。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"做得到的；能实现的","en":"If it is possible to do something, it can be done.","ex":{"en":"If it is possible to find out where your brother is, we shall","cn":"如果能找出你兄弟在哪儿，我们就会去找。"}},{"pos":"ADJ 形容词","cn":"可能（发生）的","en":"A possible event is one that might happen.","ex":{"en":"He referred the matter to the Attorney General for possible action against several newspapers","cn":"他把对几家报纸可能提起诉讼的事宜提交首席检察官来处理。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可能的；也许的","en":"If you say that it is possible that something is true or correct, you mean that although you do not know whether it is true or correct, you accept that it might be.","ex":{"en":"It is possible that there's an explanation for all this","cn":"也许，对于所有这一切，会有一种解释。"}},{"pos":"ADJ 形容词","cn":"尽可能的","en":"If you do something as soon as possible, you do it as soon as you can. If you get as much as possible of something, you get as much of it as you can.","ex":{"en":"Please make your decision as soon as possible","cn":"请尽快作决定。"}},{"pos":"ADJ 形容词","cn":"（与形容词最高级连用，表示强调）最…的","en":"You use possible with superlative adjectives to emphasize that something has more or less of a quality than anything else of its kind.","ex":{"en":"They have joined the job market at the worst possible time","cn":"他们在最不景气的时候进入了就业市场。"}},{"pos":"ADJ 形容词","cn":"如果可能的话；要是有可能的话","en":"You use possible in expressions such as 'if possible' and 'if at all possible' when stating a wish or intention, to show that although this is what you really want, you may have to accept something different.","ex":{"en":"I need to see you, right away if possible.","cn":"我要见你，如果可能，马上。"}},{"pos":"ADJ 形容词","cn":"可能当选的","en":"If you describe someone as, for example, a possible Prime Minister, you mean that they may become Prime Minister.","ex":{"en":"Government sources are now openly speculating about a possible successor for Dr Lawrence","cn":"官方消息人士在公开推测谁有可能成为接任劳伦斯博士的人选。"}},{"pos":"N-SING 单数名词","cn":"可能；可能（做）的事","en":"The possible is everything that can be done in a situation.","ex":{"en":"He is a democrat with the skill, nerve, and ingenuity to push the limits of the possible.","cn":"他是一个手腕高超、富有胆识、足智多谋的民主党人，能够让不可能的事成为可能。"}}]},"examples":[{"en":"With the possible exception of the Beatles, no other band has become so successful so quickly.","cn":"可能除了披头士乐队这个例外，还没有哪个乐队如此转瞬走红的。"},{"en":"It's just not physically possible to finish all this by the end of the week.","cn":"要在本周末完成这一切，这在客观上是办不到的。"}]},"posture":{"oxford":{"phon":"ˈpɒstʃə(r)","pos":"noun","senses":[{"en":"the position in which you hold your body when standing or sitting","cn":"（坐、立的）姿势","g":"[uncountable, countable]","ex":{"en":"a comfortable/relaxed posture","cn":"舒适的／轻松的姿势"}},{"en":"your attitude to a particular situation or the way in which you deal with it","cn":"态度；看法；立场；处理方式","g":"[countable, usually singular]","ex":{"en":"The company has adopted an aggressive posture towards its rivals.","cn":"该公司向竞争对手摆出了强硬的姿态。"}},{"en":"to pretend to be something that you are not by saying and doing things in order to impress or trick people","cn":"故作姿态；装样子","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（坐、立的）姿势，姿态","en":"Your posture is the position in which you stand or sit.","ex":{"en":"You can make your stomach look flatter instantly by improving your posture","cn":"通过采取更好的坐姿，你的腹部马上就会看起来平坦一些。"}},{"pos":"N-COUNT 可数名词","cn":"态度；立场","en":"A posture is an attitude that you have towards something.","ex":{"en":"The military machine is ready to change its defensive posture to one prepared for action","cn":"军方随时准备由防御立场转向备战立场。"}},{"pos":"VERB 动词","cn":"故作姿态；装腔作势；装模作样","en":"You can say that someone is posturing when you disapprove of their behaviour because you think they are trying to give a particular impression in order to deceive people.","ex":{"en":"She says the President may just be posturing.","cn":"她说总统也许只是在做样子而已。"}}]},"media":{"uk":"media/uk/posture__gb_1.mp3","us":"media/us/posture__us_1.mp3"},"examples":[{"en":"Good posture is essential when working at the computer.","cn":"用电脑工作时良好的姿势极其重要。"},{"en":"The government has adopted an aggressive posture on immigration.","cn":"政府对移民入境采取了强硬的态度。"}]},"position":{"media":{"uk":"media/uk/position__gb_1.mp3","us":"media/us/position__us_1.mp3"},"oxford":{"phon":"pəˈzɪʃn","pos":"noun","senses":[{"en":"the place where somebody/something is located","cn":"位置；地方","g":"[countable]","sc":"place","ex":{"en":"Where would be the best position for the lights?","cn":"这些灯装在什么位置最好？"}},{"en":"the place where somebody/something is meant to be; the correct place","cn":"恰当位置；正确位置","g":"[countable, uncountable]","sc":"place","ex":{"en":"He took up his position by the door.","cn":"他到门边就位。"}},{"en":"the way in which somebody is sitting or standing, or the way in which something is arranged","cn":"（坐或站的）姿态，姿势；放置方式","g":"[countable, uncountable]","sc":"way somebody/something is placed","ex":{"en":"a sitting/standing/kneeling position","cn":"坐姿；站姿；跪姿"}},{"en":"the situation that somebody is in, especially when it affects what they can and cannot do","cn":"处境；地位；状况","g":"[countable, usually singular]","sc":"situation","ex":{"en":"The company's financial position is not certain.","cn":"这家公司的财务状况不明朗。"}},{"en":"an opinion on or an attitude towards a particular subject","cn":"观点；态度；立场","g":"[countable]","sc":"opinion","ex":{"en":"She has made her position very clear.","cn":"她把自己的立场表达得非常明确。"}},{"en":"a person or organization’s level of importance when compared with others","cn":"地位；等级","g":"[countable, uncountable]","sc":"level of importance","ex":{"en":"the position of women in society","cn":"妇女的社会地位"}},{"en":"a job","cn":"职位；职务","g":"[countable]","lab":"formal","sc":"job","ex":{"en":"He held a senior position in a large company.","cn":"他在一家大公司担任高级职务。"}},{"en":"a place in a race, competition, or test, when compared to others","cn":"名次","g":"[countable]","sc":"in race/competition","ex":{"en":"United's 3–0 win moved them up to third position.","cn":"联队 3:0 的胜利使他们排名升至第三。"}},{"en":"the place where somebody plays and the responsibilities they have in some team games","cn":"（队员的）职责，位置，角色","g":"[countable]","sc":"in sport","ex":{"en":"What position does he play?","cn":"他打哪个位置？"}},{"en":"a place where a group of people involved in fighting have put men and guns","cn":"阵地","g":"[countable, usually plural]","sc":"in war","ex":{"en":"They attacked the enemy positions at dawn.","cn":"黎明时分，他们向敌军阵地发起进攻。"}},{"en":"to put somebody/something in a particular position","cn":"安装；安置；使处于","ex":{"en":"She quickly positioned herself behind the desk.","cn":"她迅速在桌子后面她的位置上坐好。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"位置；方位","en":"The position of someone or something is the place where they are in relation to other things.","ex":{"en":"The ship was identified, and its name and position were reported to the coastguard","cn":"那艘船已找到，其名字和位置已报告给海岸警卫队。"}},{"pos":"N-COUNT 可数名词","cn":"姿势；安置方式","en":"When someone or something is in a particular position, they are sitting, lying, or arranged in that way.","ex":{"en":"Hold the upper back and neck in an erect position to give support for the head","cn":"挺直上背部和脖子来支撑头部"}},{"pos":"VERB 动词","cn":"安放；放置","en":"If you position something somewhere, you put it there carefully, so that it is in the right place or position.","ex":{"en":"Position trailing plants near the edges and in the sides of the basket to hang down","cn":"把蔓生植株靠边放，使其从篮子的四面垂下。"}},{"pos":"N-COUNT 可数名词","cn":"（社会）地位，身份","en":"Your position in society is the role and the importance that you have in it.","ex":{"en":"...the position of older people in society.","cn":"老年人在社会中的地位"}},{"pos":"N-COUNT 可数名词","cn":"职位；职务","en":"A position in a company or organization is a job.","ex":{"en":"He left a career in teaching to take up a position with the Arts Council","cn":"他辞去教学工作到艺术委员会任职。"}},{"pos":"N-COUNT 可数名词","cn":"（比赛、竞赛中的）名次","en":"Your position in a race or competition is how well you did in relation to the other competitors or how well you are doing.","ex":{"en":"Agassi and Sampras resumed their battle for the world's No. 1 position, both winning their opening matches","cn":"阿加西和桑普拉斯继续他们对世界第一宝座的争夺，两人在首场比赛中均获得胜利。"}},{"pos":"N-COUNT 可数名词","cn":"处境；状况；形势","en":"You can describe your situation at a particular time by saying that you are in a particular position .","ex":{"en":"He's going to be in a very difficult position indeed if things go badly for him","cn":"如果事情进展不顺利的话，他的处境将非常艰难。"}},{"pos":"N-COUNT 可数名词","cn":"态度；立场；观点","en":"Your position on a particular matter is your attitude towards it or your opinion of it.","ex":{"en":"He could be depended on to take a moderate position on most of the key issues","cn":"他应该会在大部分关键问题上采取中间立场。"}},{"pos":"N-SING 单数名词","cn":"能够/不能够","en":"If you are in a position to do something, you are able to do it. If you are in no position to do something, you are unable to do it.","ex":{"en":"The UN system will be in a position to support the extensive relief efforts needed","cn":"联合国将能满足全面救济需求。"}},{"pos":"PHRASE 短语","cn":"就位；在适当的位置","en":"If someone or something is in position, they are in their correct or usual place or arrangement.","ex":{"en":"This second door is an extra security measure and can be locked in position during the day","cn":"这第二道门是又一项安全措施，白天可以上锁。"}}]},"examples":[{"en":"United's 3–0 win moved them up to third position.","cn":"联队 3:0 的胜利使他们排名升至第三。"},{"en":"My parents always took the position that early nights meant healthy children.","cn":"我的父母总是认为孩子早睡就会身体健康。"}]},"posts":{"lemma":"post","media":{"uk":"media/uk/post__gb_1.mp3","us":"media/us/post__us_1.mp3"}},"populations":{"lemma":"population","media":{"uk":"media/uk/population__gb_1.mp3","us":"media/us/population__us_1.mp3"}},"polar":{"media":{"uk":"media/uk/polar__gb_1.mp3","us":"media/us/polar__us_1.mp3"},"oxford":{"phon":"ˈpəʊlə(r)","pos":"adjective","senses":[{"en":"connected with, or near the North or South Pole","cn":"极地的；近地极的；南极（或北极）的","ex":{"en":"the polar regions","cn":"极区"}},{"en":"connected with the poles (= the positive and negative ends) of a magnet","cn":"磁极的","lab":"specialist","ex":{"en":"polar attraction","cn":"极向引力"}},{"en":"used to describe something that is the complete opposite of something else","cn":"完全相反的；截然对立的","lab":"formal","ex":{"en":"The parents' position is often the polar opposite of the child's.","cn":"父母的观点常与孩子的完全相反。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"近地极的；极地的","en":"Polar means near the North and South Poles.","ex":{"en":"...the rigours of life in the polar regions","cn":"在极地地区生活的艰苦"}},{"pos":"ADJ 形容词","cn":"（在性质、类型等方面）完全相反的，截然对立的","en":"Polar is used to describe things which are completely opposite in character, quality, or type.","ex":{"en":"In many ways, Brett and Bernard are polar opposites.","cn":"在许多方面，布雷特和伯纳德截然不同。"}}]},"examples":[{"en":"The parents' position is often the polar opposite of the child's.","cn":"父母的观点常与孩子的完全相反。"},{"en":"polar explorers","cn":"极地探险家"}]},"possibilities":{"lemma":"possibility"},"polite":{"media":{"uk":"media/uk/polite__gb_1.mp3","us":"media/us/polite__us_1.mp3"},"oxford":{"phon":"pəˈlaɪt","pos":"adjective","senses":[{"en":"having or showing good manners and respect for the feelings of others","cn":"有礼貌的；客气的；儒雅的","ex":{"en":"Please be polite to our guests.","cn":"请礼貌待客。"}},{"en":"socially correct but not always sincere","cn":"应酬的；礼节性的；客套的","ex":{"en":"I don't know how to make polite conversation.","cn":"我不晓得怎么说应酬话。"}},{"en":"from a class of society that believes it is better than others","cn":"上流社会的","g":"[only before noun]","ex":{"en":"‘Bum’ is not a word we use in polite company.","cn":"“屁股”可不是我们当着文雅人的面说的字眼。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有礼貌的；客气的；文雅的","en":"Someone who is polite has good manners and behaves in a way that is socially correct and not rude to other people.","ex":{"en":"Everyone around him was trying to be polite, but you could tell they were all bored","cn":"他周围的每一个人都极力表现出彬彬有礼的样子，但能够看出他们都感到厌烦。"}},{"pos":"ADJ 形容词","cn":"上流的；高雅的","en":"You can refer to people who consider themselves to be socially superior and to set standards of behaviour for everyone else as polite society or polite company .","ex":{"en":"Certain words are vulgar and not acceptable in polite society.","cn":"有些字眼较粗俗，不为上流社会所接受。"}}]},"examples":[{"en":"‘Bum’ is not a word we use in polite company. “","cn":"屁股”可不是我们当着文雅人的面说的字眼。"},{"en":"The performance was greeted with polite applause.","cn":"这场演出得到了礼貌性的掌声。"}]},"police":{"media":{"uk":"media/uk/police__gb_1.mp3","us":"media/us/police__us_1.mp3"},"oxford":{"phon":"pəˈliːs","pos":"noun","senses":[{"en":"an official organization whose job is to make people obey the law and to prevent and solve crime; the people who work for this organization","cn":"警察部门；警方","ex":{"en":"Get out of the house or I'll call the police.","cn":"离开这所房子，不然我就叫警察了。"}},{"en":"to go around a particular area to make sure that nobody is breaking the law there","cn":"巡查；维护治安","ex":{"en":"The border will be policed by UN officials.","cn":"边境将由联合国官员巡查。"},"pos":"verb"},{"en":"to make sure that a particular set of rules is obeyed","cn":"监督；监管","ex":{"en":"The profession is policed by its own regulatory body.","cn":"这个行业由其自律机构监督。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"警察部门；警察机关；警方","en":"The police are the official organization that is responsible for making sure that people obey the law.","ex":{"en":"The police are also looking for a second car","cn":"警方也在寻找另一辆车。"}},{"pos":"N-PLURAL 复数名词","cn":"警察","en":"Police are men and women who are members of the official organization that is responsible for making sure that people obey the law.","ex":{"en":"More than one hundred police have ringed the area.","cn":"这一地区已被上百名警察包围。"}},{"pos":"VERB 动词","cn":"维持…的治安；守卫；保卫","en":"If the police or military forces police an area or event, they make sure that law and order is preserved in that area or at that event.","ex":{"en":"...the tiny UN observer force whose job it is to police the border","cn":"承担守卫边界职责的一小支联合国观察员部队"}},{"pos":"VERB 动词","cn":"管理；监督","en":"If a person or group in authority polices a law or an area of public life, they make sure that what is done is fair and legal.","ex":{"en":"...IMRO, the self-regulatory body that polices the investment management business.","cn":"投资管理监管组织，监督投资管理业务的自律机构"}}]},"examples":[{"en":"Hundreds of police in riot gear struggled to control the violence.","cn":"数以百计的警察身披防暴装备，奋力镇压暴乱。"},{"en":"Get out of the house or I'll call the police.","cn":"滚出这所房子，不然我就叫警察了。"}]},"poet":{"oxford":{"phon":"ˈpəʊɪt","pos":"noun","senses":[{"en":"a person who writes poems","cn":"诗人","ex":{"en":"an internationally renowned poet","cn":"蜚声国际的诗人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"诗人","en":"A poet is a person who writes poems.","ex":{"en":"He was a painter and poet.","cn":"他既是画家又是诗人。"}}]},"media":{"uk":"media/uk/poet__gb_1.mp3","us":"media/us/poet__us_1.mp3"}},"possibility":{"oxford":{"phon":"ˌpɒsəˈbɪləti","pos":"noun","senses":[{"en":"a thing that may happen or be true; the fact that something might happen or be true, but is not certain","cn":"可能；可能性","g":"[countable, uncountable]","ex":{"en":"Bankruptcy is a real possibility if sales don't improve.","cn":"如果销售情况不改善，真有破产的可能。"}},{"en":"one of the different things that you can do in a particular situation","cn":"可选择的方法","g":"[countable]","ex":{"en":"The possibilities are endless.","cn":"有无数种可能的做法。"}},{"en":"something that gives you a chance to achieve something","cn":"机会；契机","g":"[countable, usually plural]","ex":{"en":"There are countless possibilities for future research.","cn":"未来有无数的研究机会。"}},{"en":"if something has possibilities, it can be improved or made successful","cn":"潜力；改进的余地","g":"[plural]","ex":{"en":"The house is in a bad state of repair but it has possibilities.","cn":"这房子虽亟待修缮，但仍有可资利用的价值。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"可能性；可能","en":"If you say there is a possibility that something is the case or that something will happen, you mean that it might be the case or it might happen.","ex":{"en":"We were not in the least worried about the possibility that sweets could rot the teeth","cn":"我们以前完全不担心吃糖果有可能会蛀牙。"}},{"pos":"N-COUNT 可数名词","cn":"（一种）可能；可能的事","en":"A possibility is one of several different things that could be done.","ex":{"en":"The government now owns a lot of our land — one possibility would be to compensate us with other property","cn":"政府现在占了我们的大量土地，一种可能是用其他地产来对我们作出补偿。"}},{"pos":"PHRASE 短语","cn":"可能的事；能做到的事","en":"You can say 'It is not beyond the realms of possibility' or 'It is not beyond the bounds of possibility' when you are stating something that you believe is possibly true, but which other people might consider unlikely or impossible.","ex":{"en":"It's not beyond the realms of possibility that the security services do bug important public figures.","cn":"安全部门完全有可能窃听重要公众人物的谈话。"}}]},"media":{"uk":"media/uk/possibility__gb_1.mp3","us":"media/us/possibility__us_1.mp3"},"examples":[{"en":"It is not beyond the bounds of possibility that we'll all meet again one day.","cn":"我们大家将来有一天再度聚在一起，并非绝不可能。"},{"en":"Bankruptcy is a real possibility if sales don't improve.","cn":"如果销售情况得不到改善，真有破产的可能。"}]},"portion":{"media":{"uk":"media/uk/portion__gb_1.mp3","us":"media/us/portion__us_1.mp3"},"oxford":{"phon":"ˈpɔːʃn","pos":"noun","senses":[{"en":"one part of something larger","cn":"部分","ex":{"en":"a substantial/significant portion of the population","cn":"人口中的一大部分／重要部分"}},{"en":"an amount of food that is large enough for one person","cn":"（食物的）一份，一客","ex":{"en":"a generous portion of meat","cn":"一大份肉"}},{"en":"a part of something that is shared with other people","cn":"分享的部分；分担的责任","g":"[usually singular]","ex":{"en":"You must accept a portion of the blame for this crisis.","cn":"你必须承担这次危机的一部分责任。"}},{"en":"to divide something into parts or portions","cn":"把…分成若干份（或部分）","ex":{"en":"The factory portions and packs over 12 000 meals a day.","cn":"这个工厂每天分装 12 000 多份饭食。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"部分","en":"A portion of something is a part of it.","ex":{"en":"Damage was confined to a small portion of the castle","cn":"城堡仅有一小部分受损。"}},{"pos":"N-COUNT 可数名词","cn":"（饭菜的）一份，一客","en":"A portion is the amount of food that is given to one person at a meal.","ex":{"en":"Desserts can be substituted by a portion of fresh fruit","cn":"餐后甜点可以用一份新鲜水果代替。"}}]},"examples":[{"en":"The factory portions and packs over 12 000 meals a day.","cn":"这个工厂每天分装 12 000 多份饭食。"},{"en":"You must accept a portion of the blame for this crisis.","cn":"你必须承担这次危机的一部分责任。"}]},"politics":{"media":{"uk":"media/uk/politics__gb_1.mp3","us":"media/us/politics__us_1.mp3"},"oxford":{"phon":"ˈpɒlətɪks","pos":"noun","senses":[{"en":"the activities involved in getting and using power in public life, and being able to influence decisions that affect a country or a society","cn":"政治；政治事务（或活动）","g":"[uncountable + singular or plural verb]","lab":"especially North American English","ex":{"en":"world/international politics","cn":"世界／国际政治"}},{"en":"matters connected with getting or using power within a particular group or organization","cn":"权术；钩心斗角","g":"[uncountable + singular or plural verb]","lab":"disapproving","ex":{"en":"I don't want to get involved in office politics.","cn":"我不想卷入办公室的钩心斗角。"}},{"en":"a person’s political views or beliefs","cn":"（个人的）政治观点，政见，政治信仰","g":"[plural]","ex":{"en":"His politics are extreme.","cn":"他的政治观点偏激。"}},{"en":"the study of government and politics","cn":"政治学","g":"[uncountable]","ex":{"en":"a degree in Politics","cn":"政治学学位"}},{"en":"a system of political beliefs; a state of political affairs","cn":"政治思想体系；政治局势","g":"[singular]","ex":{"en":"A politics of the future has to engage with new ideas.","cn":"未来的政治制度必须同新思想结合。"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"政治；政治事务；政治活动（其后的动词既可用单数，又可用复数）","en":"Politics are the actions or activities concerned with achieving and using power in a country or society. The verb that follows politics may be either singular or plural.","ex":{"en":"The key question in British politics was how long the prime minister could survive","cn":"英国政治的关键问题是首相能坚持多久。"}},{"pos":"N-PLURAL 复数名词","cn":"政治信仰；政治主张；政治见解","en":"Your politics are your beliefs about how a country ought to be governed.","ex":{"en":"My politics are well to the left of centre.","cn":"我的政治主张相当偏左。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"政治学","en":"Politics is the study of the ways in which countries are governed.","ex":{"en":"He began studying politics and medieval history.","cn":"他开始学习政治学和中世纪史。"}},{"pos":"N-PLURAL 复数名词","cn":"手腕；权术；策略（其后的动词既可用单数，又可用复数）","en":"Politics can be used to talk about the ways that power is shared in an organization and the ways it is affected by personal relationships between people who work together. The verb that follows politics may be either singular or plural.","ex":{"en":"You need to understand how office politics influence the working environment.","cn":"你需要了解办公室权术是如何影响工作氛围的。"}}]},"examples":[{"en":"A politics of the future has to engage with new ideas.","cn":"未来的政治制度必须同新思想结合。"},{"en":"I don't want to get involved in office politics.","cn":"我不想卷入办公室的政治。"}]},"portuguese":{"media":{"uk":"media/uk/portuguese_1_gb_1.mp3","us":"media/us/portuguese_1_us_1.mp3"},"oxford":{"phon":"ˌpɔːtʃʊˈɡiːz","pos":"adjective","senses":[{"en":"from or connected with Portugal","cn":"葡萄牙的"},{"en":"a person from Portugal","cn":"葡萄牙人","g":"[countable]","pos":"noun"},{"en":"the language used in Portugal and Brazil and some other countries","cn":"葡萄牙语","g":"[uncountable]","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"葡萄牙的；葡萄牙人的；葡萄牙文化的","en":"Something that is Portuguese belongs or relates to Portugal, or its people, language, or culture.","ex":{"en":"...a former Portuguese colony.","cn":"以前的葡萄牙殖民地"}},{"pos":"N-PLURAL 复数名词","cn":"葡萄牙人","en":"The Portuguese are the people of Portugal.","ex":{"en":"...a former palace built by the Portuguese.","cn":"以前葡萄牙人修建的宫殿"}},{"pos":"N-UNCOUNT 不可数名词","cn":"葡萄牙语","en":"Portuguese is the language spoken in Portugal, Brazil, Angola, and Mozambique.","ex":{"en":"If you are intent on learning to speak Portuguese, there is no better place.","cn":"如果你想学葡萄牙语，没有比这儿更好的地方了。"}}]}},"powerhouse":{"media":{"uk":"media/uk/powerhouse__gb_1.mp3","us":"media/us/powerhouse__us_1.mp3"},"oxford":{"phon":"ˈpaʊəhaʊs","pos":"noun","senses":[{"en":"a group or an organization that is strong and effective in its activities","cn":"强大的集团；有力量的组织","ex":{"en":"China has been described as an economic powerhouse.","cn":"中国被誉为经济强国。"}},{"en":"a person who is very strong and full of energy","cn":"精力充沛的人；身强力壮的人"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"权势集团；强国","en":"A powerhouse is a country or organization that has a lot of power or influence.","ex":{"en":"Nigeria is the most populous African country and an economic powerhouse for the continent.","cn":"尼日利亚是非洲人口最稠密的国家，也是非洲大陆的经济强国。"}},{"pos":"N-COUNT 可数名词","cn":"精力充沛的人；充满活力的人","en":"If you say that someone is a powerhouse, you mean that they are very energetic."}]},"examples":[{"en":"China has been described as an ‘emerging economic powerhouse’.","cn":"中国被称为“崛起中的经济强国”。"},{"en":"Europe’s industrial powerhouse","cn":"欧洲的工业重地"}]},"poisonous":{"oxford":{"phon":"ˈpɔɪzənəs","pos":"adjective","senses":[{"en":"causing death or illness if swallowed or taken into the body","cn":"引起中毒的；有毒的","ex":{"en":"poisonous chemicals/fumes/plants","cn":"有毒化学品／烟雾／植物"}},{"en":"producing a poison that can cause death or illness if the animal or insect bites you","cn":"分泌毒素的；能毒伤人的","ex":{"en":"poisonous snakes","cn":"毒蛇"}},{"en":"extremely unpleasant or unfriendly","cn":"极端讨厌（或不友善）的；恶毒的；邪恶的","ex":{"en":"a poisonous person","cn":"有毒的人"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有毒的；引起中毒的","en":"Something that is poisonous will kill you or make you ill if you swallow or absorb it.","ex":{"en":"All parts of the yew tree are poisonous, including the berries.","cn":"紫杉的各个部分都有毒，包括浆果。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（动物）有毒的，带毒的","en":"An animal that is poisonous produces a poison that will kill you or make you ill if the animal bites you.","ex":{"en":"There are hundreds of poisonous spiders and snakes.","cn":"毒蜘蛛和毒蛇成百上千。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极令人厌恶的；会造成危害的；恶毒的","en":"If you describe something as poisonous, you mean that it is extremely unpleasant and likely to spoil or destroy a good relationship or situation.","ex":{"en":"...poisonous comments.","cn":"恶毒的评论"}}]},"media":{"uk":"media/uk/poisonous__gb_1.mp3","us":"media/us/poisonous__us_1.mp3"},"examples":[{"en":"The leaves of certain trees are poisonous to cattle.","cn":"某些树的叶子会毒害牛。"},{"en":"the poisonous atmosphere in the office","cn":"办公室里的恶劣气氛"}]},"pop":{"media":{"uk":"media/uk/pop__gb_1.mp3","us":"media/us/pop__us_1.mp3"},"oxford":{"phon":"pɒp","pos":"noun","senses":[{"en":"popular music of the sort that has been popular since the 1950s, usually with a strong rhythm and simple tunes, often contrasted with rock, soul and other forms of popular music","cn":"流行音乐（通常与摇滚乐、灵乐和其他受欢迎的音乐形式相对）","g":"[uncountable]","lab":"British English","sc":"music","ex":{"en":"rock, pop and soul","cn":"摇滚乐、流行音乐和灵乐"}},{"en":"a short, sharp, explosive sound","cn":"（短促清脆的爆裂声）砰","g":"[countable]","sc":"sound","ex":{"en":"The cork came out of the bottle with a loud pop.","cn":"软木塞砰的一声从瓶口迸了出来。"}},{"en":"a sweet fizzy drink (= with bubbles) that is not alcoholic","cn":"汽水","g":"[uncountable]","lab":"old-fashioned, informal，，","sc":"drink"},{"en":"used as a word for ‘father’, especially as a form of address","cn":"（尤用作称呼）爸，爹","g":"[singular]","lab":"especially North American English, old-fashioned, informal，，，，","sc":"father","ex":{"en":"Hi, Pop!","cn":"嗨，爸！"}},{"en":"connected with modern popular music","cn":"流行音乐的；通俗风格的","sc":"music/style","ex":{"en":"a pop song","cn":"流行歌曲"},"pos":"adjective"},{"en":"made in a modern popular style","cn":"通俗的；现代的","sc":"music/style","ex":{"en":"pop culture","cn":"通俗文化"},"pos":"adjective"},{"en":"to make a short explosive sound; to cause something to make this sound","cn":"（使）发砰砰声","g":"[intransitive, transitive]","sc":"make sound","ex":{"en":"the sound of corks popping","cn":"瓶塞被拔起时发出的砰砰声"},"pos":"verb"},{"en":"to burst, or make something burst (= break apart or open), with a short explosive sound","cn":"（使）爆裂","g":"[transitive, intransitive]","sc":"make sound","ex":{"en":"She jumped as someone popped a balloon behind her.","cn":"有人在她背后弄爆了一个气球，把她吓了一跳。"},"pos":"verb"},{"en":"to go somewhere quickly, suddenly or for a short time","cn":"（突然或匆匆）去","g":"[intransitive]","lab":"informal","sc":"go quickly","ex":{"en":"I'll pop over and see you this evening.","cn":"我今晚就赶去看你。"},"pos":"verb"},{"en":"to put something/somebody somewhere quickly, suddenly or for a short time","cn":"（迅速或突然）放置","g":"[transitive]","lab":"especially British English, informal，，","sc":"put quickly","ex":{"en":"He popped his head around the door and said hello.","cn":"他从门后探一探头，打了声招呼。"},"pos":"verb"},{"en":"to suddenly appear, especially when not expected","cn":"突然出现；冷不防冒出","g":"[intransitive]","lab":"computing","sc":"appear suddenly","ex":{"en":"The window opened and a dog's head popped out.","cn":"窗子打开了，冷不防一只狗探出头来。"},"pos":"verb"},{"en":"if your ears pop when you are going up or down in a plane, etc., the pressure in them suddenly changes","cn":"（乘飞机等升降时）耳压变化；（耳）胀","g":"[intransitive]","sc":"of ears","pos":"verb"},{"en":"if your eyes pop or pop out, they suddenly open fully because you are surprised or excited","cn":"（因激动、惊奇）张大，睁大，瞪起","g":"[intransitive]","sc":"of eyes","ex":{"en":"Her eyes nearly popped out of her head when she saw them.","cn":"她一看到他们，眼睛瞪得快要掉出来了。"},"pos":"verb"},{"en":"to take a lot of a drug, regularly","cn":"（经常大量地）服药，用毒品","g":"[transitive]","lab":"informal","sc":"take drugs","ex":{"en":"She's been popping pills for months.","cn":"她大量服药已有几个月了。"},"pos":"verb"},{"en":"to open the bonnet of a car","cn":"打开汽车的引擎盖","g":"[transitive]","lab":"North American English","sc":"take drugs","pos":"verb"},{"en":"population","cn":"人口","ex":{"en":"pop. 200 000","cn":"人口 20 万"},"pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"因特网接入点","en":"A POP is equipment that gives access to the Internet. POP is an abbreviation for (缩略=) 'point of presence'."}]},"examples":[{"en":"Why don't you pop in (= visit us) for a drink next time you're in the area?","cn":"下次来到这一带时，就到我们这儿小酌一杯如何？"},{"en":"She jumped as someone popped a balloon behind her.","cn":"有人在她背后弄爆了一个气球，把她吓了一跳。"}]},"poorly":{"media":{"uk":"media/uk/poorly__gb_1.mp3","us":"media/us/poorly__us_1.mp3"},"oxford":{"phon":"ˈpɔːli","pos":"adverb","senses":[{"en":"in a way that is not good enough","cn":"不够好地；不能令人满意地","ex":{"en":"a poorly attended meeting (= at which there are not many people)","cn":"寥寥几个人参加的会议"}},{"en":"ill","cn":"有病；不舒服","ex":{"en":"She felt poorly.","cn":"她觉得不舒服。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"生病的；身体不舒服的","en":"If someone is poorly, they are ill.","ex":{"en":"I've just phoned Julie and she's still poorly.","cn":"我刚给朱莉打了电话，她身体还是不舒服。"}}]},"examples":[{"en":"Our candidate fared poorly in the election (= did not get many votes).","cn":"我们的候选人在选举中得票不多。"},{"en":"The job is relatively poorly paid.","cn":"相对而言，这工作报酬很低。"}]},"poems":{"lemma":"poem"},"poles":{"lemma":"pole"},"poem":{"oxford":{"phon":"ˈpəʊɪm","pos":"noun","senses":[{"en":"a piece of writing in which the words are chosen for their sound and the images they suggest, not just for their obvious meanings. The words are arranged in separate lines, usually with a repeated rhythm, and often the lines rhyme at the end.","cn":"诗；韵文","lab":"US English","ex":{"en":"His collected poems were published after the war.","cn":"他的诗集在战后出版。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"诗；韵文","en":"A poem is a piece of writing in which the words are chosen for their beauty and sound and are carefully arranged, often in short lines which rhyme."}]},"media":{"uk":"media/uk/poem__gb_1.mp3","us":"media/us/poem__us_1.mp3"},"examples":[{"en":"I decided to write a poem about how I felt.","cn":"我决定把我的感受写成一首诗。"}]},"postures":{"lemma":"posture"},"pose":{"media":{"uk":"media/uk/pose__gb_1.mp3","us":"media/us/pose__us_1.mp3"},"oxford":{"phon":"pəʊz","pos":"verb","senses":[{"en":"to create a threat, problem, etc. that has to be dealt with","cn":"造成（威胁、问题等）；引起；产生","g":"[transitive]","ex":{"en":"to pose a threat/risk/challenge/danger","cn":"产生威胁／风险／挑战／危险"}},{"en":"to ask a question, especially one that needs serious thought","cn":"提问；质询","g":"[transitive]","lab":"formal","ex":{"en":"The new play poses some challenging questions.","cn":"这个新剧目提出了一些富挑战性的问题。"}},{"en":"to sit or stand in a particular position in order to be painted, drawn or photographed","cn":"（为画像、摄影）摆好姿势","g":"[intransitive]","ex":{"en":"The delegates posed for a group photograph.","cn":"代表们摆好姿势准备拍集体照。"}},{"en":"to pretend to be somebody in order to trick other people","cn":"佯装；冒充；假扮","g":"[intransitive]","ex":{"en":"The gang entered the building posing as workmen.","cn":"这伙匪徒冒充工人混进了大楼。"}},{"en":"to dress or behave in a way that is intended to impress other people","cn":"招摇；炫耀；拿姿作态","g":"[intransitive]","lab":"disapproving","ex":{"en":"I saw him out posing in his new sports car.","cn":"我看见他开着他的崭新跑车招摇过市。"}},{"en":"a particular position in which somebody stands, sits, etc., especially in order to be painted, drawn or photographed","cn":"（尤指为画像、拍照等摆的）姿势","ex":{"en":"He adopted a relaxed pose for the camera.","cn":"他摆了个悠闲的姿势拍照。"},"pos":"noun"},{"en":"a way of behaving that is not sincere and is intended to impress or trick people","cn":"装腔作势；故作姿态","lab":"disapproving","ex":{"en":"This show of concern is just a pose.","cn":"这种关心只是一种姿态。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"产生（问题）；造成（威胁、危险等）","en":"If something poses a problem or a danger, it is the cause of that problem or danger.","ex":{"en":"This could pose a threat to jobs in the coal industry","cn":"这可能会给煤炭产业的就业造成威胁。"}},{"pos":"VERB 动词","cn":"提出；陈述","en":"If you pose a question, you ask it. If you pose an issue that needs considering, you mention the issue.","ex":{"en":"When I finally posed the question, 'Why?' he merely shrugged.","cn":"当我最后问“为什么”时，他只是耸了耸肩。"}},{"pos":"VERB 动词","cn":"冒充；假装","en":"If you pose as someone, you pretend to be that person in order to deceive people.","ex":{"en":"The team posed as drug dealers to trap the ringleaders.","cn":"该队队员装扮成毒品贩子，诱捕罪犯头目。"}},{"pos":"VERB 动词","cn":"摆姿势（以供人摄影或绘画）","en":"If you pose for a photograph or painting, you stay in a particular position so that someone can photograph you or paint you.","ex":{"en":"Before going into their meeting the six foreign ministers posed for photographs.","cn":"开会前，6位外交部长合影留念。"}},{"pos":"VERB 动词","cn":"装模作样；装腔作势","en":"You can say that people are posing when you think that they are behaving in an insincere or exaggerated way because they want to make a particular impression on other people.","ex":{"en":"He criticized them for dressing outrageously and posing pretentiously.","cn":"他批评她们衣着暴露而且矫揉造作。"}},{"pos":"N-COUNT 可数名词","cn":"姿势；姿态","en":"A pose is a particular way that you stand, sit, or lie, for example when you are being photographed or painted.","ex":{"en":"We have had several preliminary sittings in various poses.","cn":"我们进行了几次预拍摄，摆了各种不同的造型。"}},{"pos":"N-COUNT 可数名词","cn":"装模作样；装腔作势","en":"A pose is an insincere or exaggerated way of behaving that is intended to make a particular impression on other people.","ex":{"en":"In many writers modesty is a pose, but in Ford it seems to have been genuine.","cn":"很多作家都是故作谦虚，但福特却似乎表里如一。"}}]},"examples":[{"en":"I saw him out posing in his new sports car.","cn":"我看见他开着他的崭新跑车招摇过市。"},{"en":"The task poses no special problems.","cn":"这项任务不会造成特别的问题。"}]},"powerful":{"media":{"uk":"media/uk/powerful__gb_1.mp3","us":"media/us/powerful__us_1.mp3"},"oxford":{"phon":"ˈpaʊəfl","pos":"adjective","senses":[{"en":"being able to control and influence people and events","cn":"有权势的；有影响力的","ex":{"en":"an incredibly powerful organization","cn":"影响力极大的组织"}},{"en":"having great power or force; very effective","cn":"强有力的；力量大的；很有效的","ex":{"en":"a powerful engine","cn":"大功率引擎"}},{"en":"having a strong effect on your thoughts, feelings or body","cn":"（对人的思想、情感或身体）有强烈作用的","ex":{"en":"a powerful image/symbol/speech","cn":"有力的图像／象征／演说"}},{"en":"physically strong","cn":"健壮的；强壮的","ex":{"en":"a powerful body","cn":"健壮的体魄"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有权力的；有势力的；有影响力的","en":"A powerful person or organization is able to control or influence people and events.","ex":{"en":"You're a powerful man — people will listen to you.","cn":"你是有影响力的人，大家会听你的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"强壮的；强健的","en":"You say that someone's body is powerful when it is physically strong.","ex":{"en":"Hans flexed his powerful muscles","cn":"汉斯活动了一下他那强健的肌肉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（机器）大功率的；强效的；高效能的","en":"A powerful machine or substance is effective because it is very strong.","ex":{"en":"The more powerful the car the more difficult it is to handle.","cn":"汽车的功率越大，就越难驾驭。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（气味）强烈的，浓的","en":"A powerful smell is very strong.","ex":{"en":"There was a powerful smell of stale beer.","cn":"有一种呛人的过期啤酒味。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（声音）响亮的，洪亮的","en":"A powerful voice is loud and can be heard from a long way away.","ex":{"en":"At that moment Mrs. Jones's powerful voice interrupted them, announcing a visitor.","cn":"就在那一刻，琼斯夫人响亮的声音打断了他们，说有人来访。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（文章、演讲或艺术品）极具感染力的，有震撼力的","en":"You describe a piece of writing, speech, or work of art as powerful when it has a strong effect on people's feelings or beliefs.","ex":{"en":"...Bleasdale's powerful 11-part drama about a corrupt city leader.","cn":"布利兹戴尔创作的关于一个腐败市领导的极具感染力的电视剧，共有11集"}}]},"examples":[{"en":"Only the intervention of powerful friends obtained her release.","cn":"经过有影响力的朋友们斡旋她才得以释放。"},{"en":"She argued powerfully for reform.","cn":"她雄辩滔滔，力主改革。"}]},"possession":{"media":{"uk":"media/uk/possession__gb_1.mp3","us":"media/us/possession__us_1.mp3"},"oxford":{"phon":"pəˈzeʃn","pos":"noun","senses":[{"en":"something that you own or have with you at a particular time","cn":"个人财产；私人物品","g":"[countable, usually plural]","sc":"having/owning","ex":{"en":"Prisoners were allowed no personal possessions.","cn":"囚犯不允许携带任何个人财物。"}},{"en":"the state of having or owning something","cn":"具有；拥有","g":"[uncountable]","lab":"formal","sc":"having/owning","ex":{"en":"The possession of a passport is essential for foreign travel.","cn":"出国旅行必须持有护照。"}},{"en":"the state of having control of the ball","cn":"控球状态","g":"[uncountable]","sc":"in sport","ex":{"en":"to win/get/lose possession of the ball","cn":"赢得／得到／失去对球的控制"}},{"en":"the state of having illegal drugs or weapons with you at a particular time","cn":"持有违禁物；私藏毒品（或武器）","g":"[uncountable]","sc":"law","ex":{"en":"She was charged with possession.","cn":"她被控持有违禁物品。"}},{"en":"a country that is controlled or governed by another country","cn":"殖民地；托管地；属地","g":"[countable]","lab":"formal","sc":"country","ex":{"en":"The former colonial possessions are now independent states.","cn":"这些前殖民地现已是独立的国家。"}},{"en":"the situation when somebody’s mind is believed to be controlled by the Devil or by an evil spirit","cn":"鬼魂缠身；着魔","g":"[uncountable]","sc":"by evil spirit"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"占有；拥有","en":"If you are in possession of something, you have it, because you have obtained it or because it belongs to you.","ex":{"en":"Those documents are now in the possession of the Guardian","cn":"那些文件目前在《卫报》手里。"}},{"pos":"N-COUNT 可数名词","cn":"所有物；财产；财物","en":"Your possessions are the things that you own or have with you at a particular time.","ex":{"en":"People had lost their homes and all their possessions","cn":"人们失去了自己的家园和所有的财物。"}},{"pos":"N-COUNT 可数名词","cn":"属地；领地","en":"A country's possessions are countries or territories that it controls.","ex":{"en":"All of them were French possessions at one time or another.","cn":"它们都曾是法国的领地。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"鬼魂附体；着魔","en":"Possession by an evil spirit is the situation when a person's mind and body is controlled by an evil spirit.","ex":{"en":"They were convinced the girls' behaviour was due to possession by the devil.","cn":"他们相信了这些女孩之所以有如此举动是因为鬼魂附体。"}}]},"examples":[{"en":"You cannot legally take possession of the property (= start using it after buying it) until three weeks after the contract is signed.","cn":"契约签署三周以后，你才能合法取得这份产业的所有权。"},{"en":"On her father's death, she came into possession of (= received) a vast fortune.","cn":"她父亲死后，她继承了一大笔财产。"}]},"pot":{"media":{"uk":"media/uk/pot__gb_1.mp3","us":"media/us/pot__us_1.mp3","img":["media/ldoce/img/cooking_pot.jpg"]},"oxford":{"phon":"pɒt","pos":"noun","senses":[{"en":"a deep round container used for cooking things in","cn":"锅","g":"[countable]","sc":"for cooking","ex":{"en":"pots and pans","cn":"锅碗瓢盆"}},{"en":"a container made of glass, clay or plastic, used for storing food in","cn":"（盛食物的）罐，瓶，壶，盒","g":"[countable]","lab":"especially British English","sc":"container","ex":{"en":"a pot of jam","cn":"一罐果酱"}},{"en":"a container of various kinds, made for a particular purpose","cn":"（某种用途的）容器","g":"[countable]","sc":"container","ex":{"en":"a coffee pot","cn":"咖啡壶"}},{"en":"the amount contained in a pot","cn":"一罐，一瓶，一壶（的量）","g":"[countable]","sc":"container","ex":{"en":"They drank a pot of coffee.","cn":"他们喝了一壶咖啡。"}},{"en":"a bowl, etc. that is made by a potter","cn":"陶盆；陶罐；碗","g":"[countable]","sc":"container","ex":{"en":"The newly made pots are glazed when they are completely dry.","cn":"刚做好的陶罐在干透后上釉。"}},{"en":"the total amount of money that is bet in a card game","cn":"（一局纸牌游戏的）赌注总额，全部赌注","g":"[singular]","lab":"especially North American English","sc":"money"},{"en":"all the money given by a group of people in order to do something together, for example to buy food, or available for a particular purpose","cn":"凑集的资金；凑集的钱","g":"[singular]","lab":"especially North American English","sc":"money"},{"en":"cannabis (= a drug (illegal in many countries) made from the dried leaves and flowers of the hemp plant, which gives the person smoking it a feeling of being relaxed)","cn":"锅：大麻（一种由大麻植物的干叶和花朵制成的药物（在许多国家/地区是非法的），使吸烟者感到放松。","g":"[uncountable]","lab":"informal","sc":"drug","ex":{"en":"pot smoking","cn":"吸大麻"}},{"en":"a shot that somebody fires without aiming carefully","cn":"乱射；盲目射击","g":"[countable]","lab":"informal","sc":"shot","ex":{"en":"He took a pot at the neighbour's cat with his air rifle.","cn":"他用气枪向邻居的猫打了一枪。"}},{"en":"the act of hitting a ball into one of the pockets around the edge of the table","cn":"击球入袋","g":"[countable]","sc":"in billiards, etc."},{"en":"a pot belly (= a large stomach that sticks out)","cn":"锅：锅肚","g":"[countable]","lab":"informal","sc":"stomach"},{"en":"to put a plant into a flowerpot filled with soil","cn":"把…栽入盆中；种盆栽","sc":"plant","pos":"verb"},{"en":"to hit a ball into one of the pockets (= holes at the corners and edges of the table)","cn":"击（球）入袋","sc":"in billiards, etc.","ex":{"en":"He potted the black to take a 7–3 lead.","cn":"他把黑球击入袋中，以 7:3 领先。"},"pos":"verb"},{"en":"to kill an animal or a bird by shooting it","cn":"射杀，射猎（飞禽或走兽）","sc":"shoot","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"锅","en":"A pot is a deep round container used for cooking stews, soups, and other food.","ex":{"en":"...metal cooking pots.","cn":"金属炒锅"}},{"pos":"N-COUNT 可数名词","cn":"茶壶；咖啡壶","en":"You can use pot to refer to a teapot or coffee pot.","ex":{"en":"There's tea in the pot.","cn":"壶里有茶。"}},{"pos":"N-COUNT 可数名词","cn":"（装果酱、油漆等的）罐，桶","en":"A pot is a cylindrical container for jam, paint, or some other thick liquid.","ex":{"en":"Hundreds of jam pots lined her scrubbed shelves.","cn":"她那擦得干干净净的架子上排列着几百个果酱罐。"}},{"pos":"N-COUNT 可数名词","cn":"同 flowerpot","en":"A pot is the same as a flowerpot ."},{"pos":"VERB 动词","cn":"把…栽入盆中","en":"If you pot a young plant, or part of a plant, you put it into a container filled with soil, so it can grow there.","ex":{"en":"Pot the cuttings individually.","cn":"把插条分别栽入盆中。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"大麻","en":"Pot is sometimes used to refer to the drugs cannabis and marijuana."},{"pos":"QUANT 数量词","cn":"一大笔；很多；大量","en":"If you have pots of money, you have a lot of it.","ex":{"en":"He must have pots of money.","cn":"他一定有很多钱。"}},{"pos":"N-SING 单数名词","cn":"（一盘纸牌游戏中各玩家所下的）赌注总额，全部赌注","en":"In a card game, the pot is the money from all the players which the winner of the game will take as a prize."},{"pos":"N-SING 单数名词","cn":"公共基金","en":"You can refer to a fund consisting of money from several people as the pot .","ex":{"en":"I've taken some money from the pot for wrapping paper.","cn":"我已从公共基金里拿了一些钱买包装纸。"}},{"pos":"N-COUNT 可数名词","cn":"大肚子；罗汉肚","en":"Someone who has a pot has a round, fat stomach which sticks out, either because they eat or drink too much, or because they have had very little to eat for some time."},{"pos":"N-COUNT 可数名词","cn":"（幼儿用的）便壶","en":"A pot is a deep bowl which a small child uses instead of a toilet."},{"pos":"VERB 动词","cn":"（斯诺克及台球中）击（球）入袋","en":"In the games of snooker and billiards, if you pot a ball, you succeed in hitting it into one of the pockets.","ex":{"en":"He did not pot a ball for the next two frames.","cn":"他在接下来的两局中一杆未进。"}},{"pos":"PHRASE 短语","cn":"（因无人照料或经营）垮掉，没落，衰落；荒废","en":"If something goes to pot, it loses all its good qualities because nobody looks after it or works at it.","ex":{"en":"The neighbourhood really is going to pot.","cn":"这个街区确实在走向败落。"}},{"pos":"PHRASE 短语","cn":"碰运气；撞大运","en":"If you take pot luck, you decide to do something even though you do not know what you will get as a result. pot of gold→see: ;","ex":{"en":"If you haven't made an appointment, take pot luck and knock on the door","cn":"如果你没有预约，就敲门试试运气吧。"}}]},"examples":[{"en":"You're welcome to stay to supper, but you'll have to take pot luck (= eat whatever is available).","cn":"欢迎你留下来吃晚饭，不过你得有什么就吃什么了。"},{"en":"Her handwriting's gone to pot since she started using a computer all the time.","cn":"自从她开始完全使用电脑后，她的手写就荒疏了。"}]},"pools":{"lemma":"pool","media":{"img":["media/pic/hobbies_comp.jpg","media/thumb/pool.jpg"],"uk":"media/uk/pool__gb_1.mp3","us":"media/us/pool__us_1.mp3"}},"pointed":{"media":{"uk":"media/uk/pointed__gb_1.mp3","us":"media/us/pointed__us_1.mp3"},"oxford":{"phon":"ˈpɔɪntɪd","pos":"adjective","senses":[{"en":"having a sharp end","cn":"尖的；有尖头的","ex":{"en":"a pointed chin","cn":"尖下巴"}},{"en":"aimed in a clear and often critical way against a particular person or their behaviour","cn":"尖锐的；尖刻的；明确的","ex":{"en":"a pointed comment/remark","cn":"一针见血的评论／言论"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有尖头的；尖的","en":"Something that is pointed has a point at one end.","ex":{"en":"...a pointed roof.","cn":"尖屋顶"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尖锐的；直截了当的；批评性的","en":"Pointed comments or behaviour express criticism in a clear and direct way.","ex":{"en":"I couldn't help but notice the pointed remarks slung in my direction","cn":"我不能不注意到针对我的尖锐言辞。"}}]},"examples":[{"en":"His words were a pointed reminder of her position.","cn":"他刻意提醒了她的身分。"},{"en":"a pointed comment/remark","cn":"一针见血的评论/说话"}],"base":"point"},"pouring":{"lemma":"pour","media":{"uk":"media/ldoce/hwd/bre/d/ld41pouring.mp3","us":"media/ldoce/hwd/ame/b/laadpouring.mp3"}},"power":{"media":{"uk":"media/uk/power__gb_1.mp3","us":"media/us/power__us_1.mp3"},"oxford":{"phon":"ˈpaʊə(r)","pos":"noun","senses":[{"en":"the ability to control people or things","cn":"控制力；影响力；操纵力","g":"[uncountable]","sc":"control","ex":{"en":"He has the power to make things very unpleasant for us.","cn":"他有能力把我们搞得狼狈不堪。"}},{"en":"political control of a country or an area","cn":"统治；政权","g":"[uncountable]","lab":"especially North American English","sc":"control","ex":{"en":"Hitler seized power in Germany in 1933.","cn":"1933年希特勒在德国掌权。"}},{"en":"energy that can be collected and used to operate a machine, to make electricity, etc.","cn":"能；能量；动力","g":"[uncountable]","sc":"energy","ex":{"en":"nuclear/wind/solar power","cn":"核能；风能；太阳能"}},{"en":"the public supply of electricity","cn":"电力供应","g":"[uncountable]","lab":"also especially North American English","sc":"energy","ex":{"en":"They've switched off the power.","cn":"他们关掉了电源。"}},{"en":"the quality of having great power or force, or of being very effective","cn":"强劲；有力","g":"[uncountable]","sc":"energy","ex":{"en":"The ship was helpless against the power of the storm.","cn":"那艘船只能任凭强大的暴风雨肆虐。"}},{"en":"physical strength used in action; physical strength that somebody possesses and might use","cn":"（身体的）力量；体力","g":"[uncountable]","sc":"energy","ex":{"en":"He hit the ball with as much power as he could.","cn":"他用尽全力击球。"}},{"en":"the ability or opportunity to do something","cn":"能力；机会","g":"[uncountable]","sc":"ability","ex":{"en":"I will do everything in my power to help you.","cn":"我将尽全力帮助你。"}},{"en":"a particular ability of the body or mind","cn":"（身体、心智的）某种能力","g":"[uncountable]","sc":"ability","ex":{"en":"Spiderman uses his powers to fight crime.","cn":"蜘蛛侠用他的神奇力量打击犯罪。"}},{"en":"all the abilities of a person’s body or mind","cn":"（全部）体力，智力","g":"[plural]","sc":"ability","ex":{"en":"At 26, he is at the height of his powers and ranked fourth in the world.","cn":"26 岁时，他处于巅峰状态，排名世界第四。"}},{"en":"the right or authority of a person or group to do something","cn":"权力；职权；权势","g":"[countable, usually plural, uncountable]","sc":"authority","ex":{"en":"The powers of the police must be clearly defined.","cn":"警察的职权必须明确界定。"}},{"en":"a country with a lot of influence in world affairs, or with great military strength","cn":"有影响力的大国；军事强国","g":"[countable]","sc":"country","ex":{"en":"He transformed a backward country into a world power.","cn":"他把一个落后国家改造成世界强国。"}},{"en":"strength or influence in a particular area of activity","cn":"某方面的力量（或影响）；实力","g":"[uncountable]","sc":"influence","ex":{"en":"These companies have enormous economic power.","cn":"这些公司财力雄厚。"}},{"en":"the influence of a particular thing or group within society","cn":"（某事物或社会集团的）影响力，势力","g":"[uncountable]","sc":"influence","ex":{"en":"Hollywood star power","cn":"好莱坞明星的影响力"}},{"en":"the number of times that an amount is to be multiplied by itself","cn":"乘方；幂","g":"[countable, usually singular]","sc":"mathematics","ex":{"en":"4 to the power of 3 is 43 (= 4 × 4 × 4 = 64).","cn":"4 的 3 次方是 43。"}},{"en":"the amount by which a lens can make objects appear larger","cn":"放大倍数；放大率","g":"[uncountable]","sc":"of lens","ex":{"en":"the power of a microscope/telescope","cn":"显微镜／望远镜的放大率"}},{"en":"a good or evil spirit that controls the lives of others","cn":"正义（或邪恶）力量","g":"[countable]","sc":"good/evil spirit","ex":{"en":"the powers of darkness (= the forces of evil)","cn":"黑暗势力"}},{"en":"to supply a machine or vehicle with the energy that makes it work","cn":"驱动，推动（机器或车辆）","g":"[transitive, usually passive]","sc":"supply energy","ex":{"en":"The aircraft is powered by a jet engine.","cn":"这架飞机由喷气发动机驱动。"},"pos":"verb"},{"en":"to move or move something very quickly and with great power in a particular direction","cn":"（使）迅猛移动，快速前进","g":"[intransitive, transitive]","sc":"move quickly","ex":{"en":"He powered through the water.","cn":"他在水中迅速游动。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"权力；权势；操纵力","en":"If someone has power, they have a lot of control over people and activities.","ex":{"en":"She interviewed six women who have reached positions of great power and influence","cn":"她采访了6名身居高位，并且颇具影响力的女士。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"能力；才能","en":"Your power to do something is your ability to do it.","ex":{"en":"Human societies have the power to solve the problems confronting them","cn":"人类社会有能力解决面临的问题。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"在…能力范围之内","en":"If it is in or within your power to do something, you are able to do it or you have the resources to deal with it.","ex":{"en":"Your debt situation is only temporary, and it is within your power to resolve it","cn":"你的债务情况只是暂时的，你有能力解决好。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（法律赋予当权者的）权力，权限，职权","en":"If someone in authority has the power to do something, they have the legal right to do it.","ex":{"en":"The Prime Minister has the power to dismiss and appoint senior ministers","cn":"首相有权任免高级部长。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"政权；统治权","en":"If people take power or come to power, they take charge of a country's affairs. If a group of people are in power, they are in charge of a country's affairs.","ex":{"en":"In 1964 Labour came into power","cn":"工党于1964年上台。"}},{"pos":"N-COUNT 可数名词","cn":"强国；大国","en":"You can use power to refer to a country that is very rich or important, or has strong military forces.","ex":{"en":"In Western eyes, Iraq is a major power in an area of great strategic importance.","cn":"在西方人眼里，伊拉克是位于具有重要战略意义的地区的一个重要强国。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"动力；功率力","en":"The power of something is the ability that it has to move or affect things.","ex":{"en":"The Roadrunner had better power, better tyres, and better brakes.","cn":"“路行者”汽车的性能、轮胎和刹车都更好。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"能源；能量；（尤指）电力","en":"Power is energy, especially electricity, that is obtained in large quantities from a fuel source and used to operate lights, heating, and machinery.","ex":{"en":"Nuclear power is cleaner than coal","cn":"核能比煤清洁。"}},{"pos":"VERB 动词","cn":"给…提供能量；驱动（机器）","en":"The device or fuel that powers a machine provides the energy that the machine needs in order to work.","ex":{"en":"The 'flywheel' battery, it is said, could power an electric car for 600 miles on a single charge","cn":"据说“飞轮”电池充电一次就能驱动电动汽车行驶600英里。"}},{"pos":"ADJ 形容词","cn":"电动的","en":"Power tools are operated by electricity.","ex":{"en":"...large power tools, such as chainsaws.","cn":"大型电动工具，如链锯"}},{"pos":"N-SING 单数名词","cn":"（数学中的）幂，乘方","en":"In mathematics, power is used in expressions such as 2 to the power of 4 or 2 to the 4th power to indicate that 2 must be multiplied by itself 4 times. This is written in numbers as 24, or 2 x 2 x 2 x 2, which equals 16.","ex":{"en":"Any number to the power of nought is equal to one.","cn":"任何数的0次方等于1。"}},{"pos":"PHRASE 短语","cn":"当权者，当局（尤指对其不赞同或不能理解其言行）","en":"You can refer to people in authority as the powers that be, especially when you want to say that you disagree with them or do not understand what they say or do.","ex":{"en":"The powers that be, in this case the independent Television Association, banned the advertisement altogether","cn":"掌权的，在这件事中即独立的电视协会，干脆禁播了那则电视广告。"}},{"pos":"","cn":"","en":"相关词组：power ahead power up"}]},"examples":[{"en":"He has the power to make things very unpleasant for us.","cn":"他掌握着我们的命运，可以把我们搞得狼狈不堪。"},{"en":"At 26, he is at the height of his powers and ranked fourth in the world. * 26","cn":"岁时，他处于巅峰状态，排名世界第四。"}]},"political":{"media":{"uk":"media/uk/political__gb_1.mp3","us":"media/us/political__us_1.mp3"},"oxford":{"phon":"pəˈlɪtɪkl","pos":"adjective","senses":[{"en":"connected with the state, government or public affairs","cn":"政治的；政府的；政权的","ex":{"en":"a monarch without political power","cn":"没有政治权力的君主"}},{"en":"connected with the different groups working in politics, especially their policies and the competition between them","cn":"政党的；党派的","ex":{"en":"a political party/leader/opponent","cn":"政党；政治领袖／对手"}},{"en":"interested in or active in politics","cn":"关心政治的；政治上活跃的","ex":{"en":"She became very political at university.","cn":"她上大学时开始十分热衷于政治。"}},{"en":"connected with power, status, etc. within an organization, rather than with matters of principle","cn":"争权夺利的；人事纠纷的","ex":{"en":"I suspect that he was dismissed for political reasons.","cn":"我怀疑他被解职是人事上的原因。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"政治的；政治上的","en":"Political means relating to the way power is achieved and used in a country or society.","ex":{"en":"All other political parties there have been completely banned","cn":"那里其他所有政党已被彻底取缔。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"对政治感兴趣的；从事政治的","en":"Someone who is political is interested or involved in politics and holds strong beliefs about it.","ex":{"en":"Oh I'm not political, I take no interest in politics","cn":"噢，我不关心政治，对政治一点也不感兴趣。"}}]},"examples":[{"en":"She became very political at university.","cn":"她上大学时开始十分热衷于政治。"},{"en":"I suspect that he was dismissed for political reasons.","cn":"我怀疑他被解职是人事上的原因。"}]},"pointing":{"media":{"uk":"media/uk/pointing__gb_1.mp3","us":"media/us/pointing__us_1.mp3"},"oxford":{"phon":"ˈpɔɪntɪŋ","pos":"noun","senses":[{"en":"the mortar (= a mixture of sand, water, etc. that becomes hard when dry) that is put in the spaces between the bricks or stones in a wall to hold them together; the method of filling in the spaces with mortar","cn":"（勾墙砖、石缝用的）砂浆，灰浆；勾缝","ex":{"en":"Check the pointing is in good condition.","cn":"检查指向是否良好。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（对建筑物外墙砖、石砌缝的）勾嵌","en":"Pointing is a way of filling in the gaps between the bricks or stones on the outside of a building so that the surface becomes sealed.","ex":{"en":"He did the pointing in the stonework himself.","cn":"他自己完成了建筑石造部分的勾嵌。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（勾嵌砖或石墙砌缝的）水泥","en":"Pointing is the cement between the bricks or stones in a wall.","ex":{"en":"Cracks, bulges, crumbling pointing and damp patches mean trouble.","cn":"裂缝、凸起、剥落的勾缝和湿斑都意味着存在问题。"}}]},"base":"point"},"pound":{"media":{"uk":"media/uk/pound__gb_1.mp3","us":"media/us/pound__us_1.mp3"},"oxford":{"phon":"paʊnd","pos":"noun","senses":[{"en":"the unit of money in the UK, worth 100 pence","cn":"英镑（英国货币单位，等于 100 便士）","g":"[countable]","lab":"specialist","sc":"money","ex":{"en":"a ten-pound note","cn":"一张十英镑的钞票"}},{"en":"the unit of money of several other countries","cn":"镑（英国以外某些国家的货币单位）","g":"[countable]","sc":"money","ex":{"en":"His salary will be about 5 000 Egyptian pounds per month.","cn":"他的薪水将是大约每月 5 000 埃及镑。"}},{"en":"the value of the British pound compared with the value of the money of other countries","cn":"英镑与外币的比值","g":"[singular]","lab":"finance","sc":"money","ex":{"en":"the strength/weakness of the pound against other currencies","cn":"英镑坚挺／疲软"}},{"en":"a unit for measuring weight, equal to 0.454 of a kilogram","cn":"磅（重量单位，合 0.454 千克）","g":"[countable]","sc":"weight","ex":{"en":"half a pound of butter","cn":"半磅黄油"}},{"en":"a place where vehicles that have been parked illegally are kept until their owners pay to get them back","cn":"违章停车车辆扣留场","g":"[countable]","sc":"for cars"},{"en":"a place where dogs that have been found in the street without their owners are kept until their owners claim them","cn":"流浪狗收留所","g":"[countable]","sc":"for dogs"},{"en":"to hit something/somebody hard many times, especially in a way that makes a lot of noise","cn":"反复击打；连续砰砰地猛击","g":"[intransitive, transitive]","sc":"hit","ex":{"en":"Heavy rain pounded on the roof.","cn":"暴雨𠳐𠳐地砸在屋顶上。"},"pos":"verb"},{"en":"to move with noisy steps","cn":"咚咚地走","g":"[intransitive]","sc":"walk noisily","ex":{"en":"She pounded along the corridor after him.","cn":"她跟着他在走廊里咚咚地走过。"},"pos":"verb"},{"en":"to beat quickly and loudly","cn":"（心脏）狂跳，怦怦地跳","g":"[intransitive]","sc":"of heart/blood","ex":{"en":"Her heart was pounding with excitement.","cn":"她激动得心脏怦怦直跳。"},"pos":"verb"},{"en":"to hit something many times in order to break it into smaller pieces","cn":"捣碎；击碎","g":"[transitive]","sc":"break into pieces","ex":{"en":"The seeds were pounded to a fine powder.","cn":"籽粒被捣成了细粉。"},"pos":"verb"},{"en":"to attack an area with a large number of bombs over a period of time","cn":"狂轰滥炸","g":"[transitive]","sc":"attack with bombs","ex":{"en":"The area is still being pounded by rebel guns.","cn":"这个地区仍然遭受着叛军炮火的轰击。"},"pos":"verb"},{"en":"to be played loudly","cn":"大声播放","g":"[intransitive]","sc":"of music","ex":{"en":"Rock music was pounding out from the jukebox.","cn":"自动点唱机高声播放着摇滚乐。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"英镑（英国货币单位，等于100便士）；镑（埃及等国的货币单位）","en":"The pound is the unit of money which is used in Britain. It is represented by the symbol £. One British pound is divided into a hundred pence. Some other countries, for example Egypt, also have a unit of money called a pound .","ex":{"en":"Beer cost three pounds a bottle","cn":"啤酒每瓶3英镑。"}},{"pos":"N-SING 单数名词","cn":"英镑币制；镑币制","en":"The pound is used to refer to the British currency system, and sometimes to the currency systems of other countries which use pounds.","ex":{"en":"The pound is expected to continue to increase against most other currencies.","cn":"英镑对大多数其他货币的汇率有望继续升高。"}},{"pos":"N-COUNT 可数名词","cn":"磅（英美等一些讲英语的国家的重量单位，合0.454千克）","en":"A pound is a unit of weight used mainly in Britain, America, and other countries where English is spoken. One pound is equal to 0.454 kilograms. A pound of something is a quantity of it that weighs one pound. →see usage note at:","ex":{"en":"Her weight was under ninety pounds.","cn":"她的体重不足90磅。"}},{"pos":"N-COUNT 可数名词","cn":"（流浪猫狗的）收留所，待领场","en":"A pound is a place where dogs and cats found wandering in the street are taken and kept until they are claimed by their owners."},{"pos":"N-COUNT 可数名词","cn":"（违章停放车辆的）扣留场","en":"A pound is a place where cars that have been parked illegally are taken by the police and kept until they have been claimed by their owners."},{"pos":"VERB 动词","cn":"用力击打；连续砰砰地猛击","en":"If you pound something or pound on it, you hit it with great force, usually loudly and repeatedly.","ex":{"en":"He pounded the table with his fist","cn":"他用拳头猛击桌子。"}},{"pos":"VERB 动词","cn":"把…捣成粉状；捣碎；舂烂","en":"If you pound something, you crush it into a paste or a powder or into very small pieces.","ex":{"en":"She paused as she pounded the maize grains.","cn":"她捣玉米粒时停了一下。"}},{"pos":"VERB 动词","cn":"（常因恐惧而心脏）剧烈跳动，怦怦地跳","en":"If your heart is pounding, it is beating with an unusually strong and fast rhythm, usually because you are afraid.","ex":{"en":"I'm sweating, my heart is pounding. I can't breathe.","cn":"我浑身冒汗，心脏狂跳，呼吸困难。"}},{"pos":"PHRASE 短语","cn":"（不顾别人痛苦而坚决要求的）应得的东西","en":"If you say that someone demands their pound of flesh, you mean that they insist on getting something they are entitled to, even though it may cause distress to the person it is demanded from.","ex":{"en":"Banks are quick to demand their pound of flesh when overdrafts run a little over the limit.","cn":"透支稍微超出限额时，银行便会很快要求归还欠款。"}}]},"examples":[{"en":"The pound closed slightly down at $1.534.","cn":"英镑的汇价略跌，收盘时为 1.534 美元。"},{"en":"What would you do if you won a million pounds?","cn":"你要是赢了一百万英镑，你想怎么用？"}]},"poignancy":{"media":{"uk":"media/uk/poignancy__gb_1.mp3","us":"media/us/poignancy__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"辛酸;惨痛","en":"Poignancy is the quality that something has when it affects you deeply and makes you feel very sad.","ex":{"en":"The film contains moments of almost unbearable poignancy","cn":"电影中有几段几乎让人辛酸得不忍目睹。"}}]},"examples":[{"en":"Of particular poignancy was the photograph of their son with his sisters, taken the day before he died.","cn":"特别令人感伤的是他们的儿子去世前一天和姐妹们的合影。"},{"en":"the poignancy of parting and separation","cn":"别离的痛苦"}],"oxford":{"phon":"ˈpɔɪnjənsi","pos":"noun","senses":[{"en":"the fact of having a strong effect on your feelings, especially in a way that makes you feel sad","cn":"对你的感情有强烈影响的事实，尤其是以一种让你感到悲伤的方式","ex":{"en":"the poignancy of parting and separation","cn":"别离的痛苦"}}]}},"poison":{"oxford":{"phon":"ˈpɔɪzn","pos":"noun","senses":[{"en":"a substance that causes death or harm if it gets into the body","cn":"毒物；毒药；毒素","ex":{"en":"Some mushrooms contain a deadly poison.","cn":"有些蘑菇含有致命毒素。"}},{"en":"an idea, a feeling, etc. that is extremely harmful","cn":"极有害的思想（或心情等）；精神毒药","ex":{"en":"the poison of racial hatred","cn":"种族仇恨这种害人的思想"}},{"en":"to harm or kill a person or an animal by giving them poison","cn":"毒死；毒害","ex":{"en":"He was believed to poison his enemies.","cn":"人们相信他毒害了他的敌人。"},"pos":"verb"},{"en":"to put poison in or on something","cn":"下毒；在…中放毒","ex":{"en":"a poisoned arrow","cn":"毒箭"},"pos":"verb"},{"en":"to have a bad effect on something","cn":"毒化；败坏；使恶化","ex":{"en":"His comment served only to poison the atmosphere still further.","cn":"他的评论只是令气氛更加恶化了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"毒物；毒药；毒素","en":"Poison is a substance that harms or kills people or animals if they swallow it or absorb it.","ex":{"en":"Poison from the weaver fish causes paralysis, swelling, and nausea","cn":"龙的毒素会引起瘫痪、肿胀和恶心。"}},{"pos":"VERB 动词","cn":"（人）使中毒，毒杀，毒害","en":"If someone poisons another person, they kill the person or make them ill by giving them poison.","ex":{"en":"The rumours that she had poisoned him could never be proved.","cn":"她曾下毒害他的谣言永远都无法得到证实。"}},{"pos":"VERB 动词","cn":"（物质）使中毒，毒死","en":"If you are poisoned by a substance, it makes you very ill and sometimes kills you.","ex":{"en":"Employees were taken to hospital yesterday after being poisoned by fumes","cn":"因吸入有害气体而中毒的员工昨天被送进了医院。"}},{"pos":"VERB 动词","cn":"在…中放毒；在…上涂毒","en":"If someone poisons a food, drink, or weapon, they add poison to it so that it can be used to kill someone.","ex":{"en":"If I was your wife I would poison your coffee.","cn":"如果我是你老婆，我会在你的咖啡里下毒。"}},{"pos":"VERB 动词","cn":"破坏，污染（水、空气或土地）","en":"To poison water, air, or land means to damage it with harmful substances such as chemicals.","ex":{"en":"...the textile and fibre industries that taint the air, poison the water and use vast amounts of natural resources","cn":"污染空气、破坏水源并消耗大量自然资源的纺织纤维工业"}},{"pos":"VERB 动词","cn":"危害；败坏；毒化","en":"Something that poisons a good situation or relationship spoils it or destroys it.","ex":{"en":"The whole atmosphere has really been poisoned.","cn":"整个气氛已全然遭到破坏。"}},{"pos":"PHRASE 短语","cn":"（通常指以谎言）使（对…）产生恶感，使（对…）心怀仇视","en":"If someone poisons your mind against another person, they make you dislike that person, usually by telling you things that are not true."}]},"media":{"uk":"media/uk/poison__gb_1.mp3","us":"media/us/poison__us_1.mp3"},"examples":[{"en":"Large sections of the river have been poisoned by toxic waste from factories.","cn":"工厂的有毒废弃物污染了大段大段的河流。"},{"en":"His comment served only to poison the atmosphere still further.","cn":"他的评论只是令气氛更加恶化了。"}]},"portable":{"media":{"uk":"media/uk/portable__gb_1.mp3","us":"media/us/portable__us_1.mp3"},"oxford":{"phon":"ˈpɔːtəbl","pos":"adjective","senses":[{"en":"that is easy to carry or to move","cn":"便携式的；手提的；轻便的","lab":"figurative","ex":{"en":"a portable TV","cn":"手提电视机"}},{"en":"written in such a way that it can be run on computers of different types","cn":"可移植的；可在不同系统上运行的","lab":"computing","ex":{"en":"The applications are available in portable versions that can be run from a flash drive on computers from different manufacturers.","cn":"这些应用程序有便携式版本，可以从不同制造商的计算机上的闪存驱动器运行。"}},{"en":"a small version of a machine, such as a television or computer, that is easy to carry","cn":"便携设备（如电视或电脑等）","ex":{"en":"new video games for consoles and portables","cn":"游戏主机和掌机平台的新电子游戏"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻便的；手提式的；便于携带的","en":"A portable machine or device is designed to be easily carried or moved.","ex":{"en":"There was a little portable television switched on behind the bar","cn":"柜台后面有一台开着的便携式小型电视机。"}},{"pos":"N-COUNT 可数名词","cn":"手提式电视机；袖珍收音机；笔记本电脑","en":"A portable is something such as a television, radio, or computer which can be easily carried or moved.","ex":{"en":"We bought a colour portable for the bedroom.","cn":"我们买了一台便携式小彩电放在卧室里。"}}]},"examples":[{"en":"The new light cover increases this model's portability.","cn":"新型的轻质外壳使这种型号携带更轻便。"},{"en":"( figurative ) a portable loan/pension (= that can be moved if you change banks, jobs, etc.)","cn":"可转移贷款/养老金"}]},"poke":{"media":{"uk":"media/uk/poke__gb_1.mp3","us":"media/us/poke__us_1.mp3","img":["media/ldoce/img/ldoce_264.png"]},"oxford":{"phon":"pəʊk","pos":"verb","senses":[{"en":"to quickly push your fingers or another object into somebody/something","cn":"（用手指或其他东西）捅，戳，杵","g":"[transitive]","ex":{"en":"She poked him in the ribs with her elbow.","cn":"她用胳膊肘顶他的肋部。"}},{"en":"to push something somewhere or move it in a particular direction with a small quick movement","cn":"推；捅；戳；探","g":"[transitive]","ex":{"en":"He poked his head around the corner to check that nobody was coming.","cn":"他从转角处探出头来，查看有没有人过来。"}},{"en":"if an object is poking out of, through, etc. something, you can see a part of it that is no longer covered by something else","cn":"露出；伸出；探出","g":"[intransitive]","ex":{"en":"The end of the cable was left poking out of the wall.","cn":"电缆头从墙里露出来了。"}},{"en":"to make a hole in something by pushing your finger or another object into it","cn":"捅窟窿；扎洞","g":"[transitive]","ex":{"en":"The kids poked holes in the ice with sticks.","cn":"孩子们用棍子在冰上戳洞。"}},{"en":"to have sex with somebody","cn":"与（某人）性交","g":"[transitive]","lab":"taboo, slang，，"},{"en":"the action of quickly pushing your fingers or another object into somebody/something","cn":"捅；戳；拨；挑","g":"[countable, usually singular]","ex":{"en":"to give the fire a poke","cn":"拨一拨火"},"pos":"noun"},{"en":"power in a car","cn":"（汽车的）马力，推进力","g":"[uncountable]","lab":"British English","ex":{"en":"I prefer something with a bit more poke.","cn":"我想要马力再大些的。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（用手指或尖物）戳，捅，杵","en":"If you poke someone or something, you quickly push them with your finger or with a sharp object.","ex":{"en":"Lindy poked him in the ribs.","cn":"琳迪戳了戳他的肋部。"}},{"pos":"VERB 动词","cn":"把…戳进；把…插入","en":"If you poke one thing into another, you push the first thing into the second thing.","ex":{"en":"He poked his finger into the hole.","cn":"他把手指插入孔中。"}},{"pos":"VERB 动词","cn":"（从后面或下面）露出，冒出","en":"If something pokes out of or through another thing, you can see part of it appearing from behind or underneath the other thing.","ex":{"en":"He saw the dog's twitching nose poke out of the basket","cn":"他看到那只狗一抽一抽的鼻子从篮子里冒出来。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（头）伸出；（使）探出","en":"If you poke your head through an opening or if it pokes through an opening, you push it through, often so that you can see something more easily.","ex":{"en":"Julie tapped on my door and poked her head in","cn":"朱莉轻轻地敲了敲我的门，探进头来。"}},{"pos":"","cn":"","en":"to poke fun at→see: ; to poke your nose into something→see: ;"},{"pos":"","cn":"","en":"相关词组：poke around poke at"}]},"examples":[{"en":"The police spent the day poking around in his office but found nothing.","cn":"警察花了一天时间搜查他的办公室，但一无所获。"},{"en":"He poked his head around the corner to check that nobody was coming.","cn":"他从转角处探出头来，查看有没有人过来。"}]},"potato":{"oxford":{"phon":"pəˈteɪtəʊ","pos":"noun","senses":[{"en":"a round white vegetable with a brown or red skin that grows underground as part of a plant also called a potato","cn":"马铃薯；土豆；洋芋","ex":{"en":"Will you peel the potatoes for me?","cn":"你给我削土豆皮好不好？"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"马铃薯；土豆","en":"Potatoes are quite round vegetables with brown or red skins and white insides. They grow under the ground."},{"pos":"PHRASE 短语","cn":"棘手的问题；烫手山芋；意见不一的复杂问题","en":"You can refer to a difficult subject that people disagree on as a hot potato .","ex":{"en":"...a political hot potato such as abortion.","cn":"类似堕胎这样政治上的烫手山芋"}}]},"media":{"img":["media/ldoce/img/potato.jpg","media/pic/vegetables_garlic_comp.jpg"],"uk":"media/uk/potato__gb_1.mp3","us":"media/us/potato__us_1.mp3"},"examples":[{"en":"Will you peel the potatoes for me?","cn":"你给我削土豆皮好不好？"},{"en":"roast/boiled/baked/fried potatoes","cn":"烘/煮/烤/炸土豆"}]},"powerless":{"media":{"uk":"media/uk/powerless__gb_1.mp3","us":"media/us/powerless__us_1.mp3"},"oxford":{"phon":"ˈpaʊələs","pos":"adjective","senses":[{"en":"without power to control or to influence somebody/something","cn":"无影响力的；无权的","ex":{"en":"powerless minorities","cn":"弱势的少数族群"}},{"en":"completely unable to do something","cn":"无能为力","ex":{"en":"I saw what was happening, but I was powerless to help.","cn":"我眼看着事情发生，却无力相助。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无权力的；无影响力的","en":"Someone who is powerless is unable to control or influence events.","ex":{"en":"If you don't have money, you're powerless.","cn":"如果你没有钱，就寸步难行。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无能为力的；做不到的","en":"If you are powerless to do something, you are completely unable to do it.","ex":{"en":"People are being murdered every day and I am powerless to stop it","cn":"每天都有人被杀，而我却无力阻止。"}}]},"examples":[{"en":"When the enemy attacked, we were completely powerless against them.","cn":"敌人进攻的时候，我们毫无抵御能力。"},{"en":"I saw what was happening, but I was powerless to help.","cn":"我眼看着事情发生，却无力相助。"}]},"politician":{"oxford":{"phon":"ˌpɒləˈtɪʃn","pos":"noun","senses":[{"en":"a person whose job involves politics, especially as an elected member of parliament, etc.","cn":"从政者；政治家","lab":"also North American English, informal，，","ex":{"en":"democratically elected politicians","cn":"民选政治家"}},{"en":"a person who is good at using different situations in an organization to try to get power or advantage for himself or herself","cn":"政客；见风使舵者；投机钻营者","lab":"disapproving","ex":{"en":"Marcos was a consummate politician: energetic and ruthless.","cn":"马科斯是一位完美无缺的政治家：充满活力，铁面无私。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"从政者，政治家（尤指议会或国会成员）","en":"A politician is a person whose job is in politics, especially a member of parliament or congress.","ex":{"en":"They have arrested a number of leading opposition politicians.","cn":"他们已经逮捕了数名反对党领袖。"}}]},"media":{"uk":"media/uk/politician__gb_1.mp3","us":"media/us/politician__us_1.mp3"},"examples":[{"en":"politicians who are trying to get the minority vote","cn":"努力争取少数族群选票的政治家"},{"en":"a British Labour politician","cn":"英国工党政治家"}]},"poverty-stricken":{"oxford":{"phon":"ˈpɒvəti strɪkən","pos":"adjective","senses":[{"en":"extremely poor; with very little money","cn":"赤贫的；一贫如洗的","ex":{"en":"poverty-stricken families/countries","cn":"贫困家庭/国家"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极为贫穷的；极其贫困的","en":"Poverty-stricken people or places are extremely poor.","ex":{"en":"...a teacher of poverty-stricken kids","cn":"教特困家庭的孩子的老师"}}]},"media":{"uk":"media/uk/poverty_stricken_1_gb_1.mp3","us":"media/us/poverty_stricken_1_us_1.mp3"},"examples":[{"en":"poverty-stricken families","cn":"赤贫的家庭"}]},"poker":{"media":{"uk":"media/uk/poker__gb_1.mp3","us":"media/us/poker__us_1.mp3","img":["media/ldoce/img/poker.jpg"]},"oxford":{"phon":"ˈpəʊkə(r)","pos":"noun","senses":[{"en":"a card game for two or more people, in which the players bet on the values of the cards they hold","cn":"扑克牌游戏","g":"[uncountable]"},{"en":"a metal stick for moving or breaking up coal in a fire","cn":"通条；拨火棍","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"扑克牌游戏","en":"Poker is a card game that people usually play in order to win money.","ex":{"en":"Lon and I play in the same weekly poker game.","cn":"我和朗每周和同一帮人聚在一起打扑克。"}},{"pos":"N-COUNT 可数名词","cn":"拨火棒；通条","en":"A poker is a metal bar which you use to move coal or wood in a fire in order to make it burn better.","ex":{"en":"Mrs Malone took up the poker and stirred at the little fire burning beside her.","cn":"马隆夫人拿起拨火棒，拨弄了一下身旁燃烧着的小火。"}}]},"examples":[{"en":"Can you play poker ?","cn":"你会玩扑克吗？"}]},"poets":{"lemma":"poet"},"poured":{"lemma":"pour"},"potentially":{"oxford":{"phon":"pəˈtenʃəli","pos":"adverb","senses":[{"en":"used to say that something may develop into something","cn":"潜在地；可能地","ex":{"en":"a potentially dangerous situation","cn":"有潜在危险的局势"}}]},"media":{"uk":"media/uk/potentially__gb_1.mp3","us":"media/us/potentially__us_1.mp3"},"examples":[{"en":"a potentially dangerous situation","cn":"有潜在危险的局势"}]},"politicians":{"lemma":"politician"},"populist":{"media":{"uk":"media/uk/populist__gb_1.mp3","us":"media/us/populist__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平民主义的；民粹主义的","en":"If you describe a politician or an artist as populist, you mean that they claim to care about the interests and opinions of ordinary people rather than those of a small group.","ex":{"en":"...Jose Sarney, the current populist president","cn":"若泽·萨尔内，现任平民主义总统"}}]},"examples":[{"en":"a populist leader","cn":"民粹主义领袖"},{"en":"a party of populists","cn":"民粹党"}],"oxford":{"phon":"ˈpɒpjəlɪst","pos":"adjective","senses":[{"en":"believing in or supporting populism (= a type of politics that claims to represent the opinions and wishes of ordinary people)","cn":"民粹主义的；平民主义的","ex":{"en":"a populist leader","cn":"民粹主义领袖"}},{"en":"a person who believes in or supports populism (= a type of politics that claims to represent the opinions and wishes of ordinary people)","cn":"民粹主义这；平民主义者","ex":{"en":"a party of populists","cn":"民粹党"},"pos":"noun"}]}},"pool":{"media":{"img":["media/pic/hobbies_comp.jpg","media/thumb/pool.jpg"],"uk":"media/uk/pool__gb_1.mp3","us":"media/us/pool__us_1.mp3"},"oxford":{"phon":"puːl","pos":"noun","senses":[{"en":"an area of water that has been created for people to swim in","cn":"游泳池","g":"[countable]","sc":"for swimming","ex":{"en":"an indoor/outdoor pool","cn":"室内／室外游泳池"}},{"en":"the building that contains a public pool","cn":"泳池：包含公共泳池的建筑物","sc":"for swimming"},{"en":"a small area of still water, especially one that has formed naturally","cn":"水坑，水塘，池塘（尤指自然形成的）","g":"[countable]","sc":"of water","ex":{"en":"freshwater/thermal pools","cn":"淡水／温水池塘"}},{"en":"a small amount of liquid or light lying on a surface","cn":"一摊（液体）；一小片（液体或光）","g":"[countable]","sc":"of liquid/light","ex":{"en":"The body was lying in a pool of blood.","cn":"尸体倒卧在血泊之中。"}},{"en":"a supply of things or money that is shared by a group of people and can be used when needed","cn":"共用的资源（或资金）","g":"[countable]","sc":"group of things/people","ex":{"en":"a pool of cars used by the firm’s sales force","cn":"公司销售人员共用的车辆"}},{"en":"a group of people available for work when needed","cn":"（统称）备用人员","g":"[countable]","sc":"group of things/people","ex":{"en":"a pool of cheap labour","cn":"廉价后备劳动力"}},{"en":"a game for two people played with 16 balls on a table, often in pubs and bars. Players use cues (= long sticks) to try to hit the balls into pockets at the edge of the table.","cn":"普尔；落袋台球","g":"[uncountable]","sc":"game","ex":{"en":"a pool table","cn":"普尔球台"}},{"en":"a form of gambling in the UK in which people try to win money by saying what the results of football matches will be","cn":"池：英国的一种赌博形式，人们试图通过说足球比赛的结果来赢钱","g":"[plural]","sc":"football","ex":{"en":"He does the pools every week.","cn":"他每周都去赌足球普尔。"}},{"en":"to collect money, information, etc. from different people so that it can be used by all of them","cn":"集中资源（或材料等）","ex":{"en":"The students work individually, then pool their ideas in groups of six.","cn":"学生先分头工作，然后六人一组交流心得。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 swimming pool","en":"A pool is the same as a swimming pool .","ex":{"en":"...a heated indoor pool","cn":"室内温水泳池"}},{"pos":"N-COUNT 可数名词","cn":"池塘；水池；水洼","en":"A pool is a fairly small area of still water.","ex":{"en":"The pool had dried up and was full of bracken and reeds.","cn":"水塘已经干涸，里面都是欧洲蕨和芦苇。"}},{"pos":"N-COUNT 可数名词","cn":"（液体的）一摊；（光的）一片","en":"A pool of liquid or light is a small area of it on the ground or on a surface.","ex":{"en":"She was found lying in a pool of blood","cn":"她被发现躺在一片血泊中。"}},{"pos":"N-COUNT 可数名词","cn":"备用数量；可用数目","en":"A pool of people, money, or things is a quantity or number of them that is available for an organization or group to use.","ex":{"en":"The available pool of healthy manpower was not as large as military officials had expected","cn":"可用的健壮人力没有军官预计的那么多。"}},{"pos":"VERB 动词","cn":"共用，聚拢（资金、知识、设备等）","en":"If a group of people or organizations pool their money, knowledge, or equipment, they share it or put it together so that it can be used for a particular purpose.","ex":{"en":"We pooled ideas and information","cn":"我们集思广益，共享信息。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"落袋台球戏","en":"Pool is a game played on a large table covered with a cloth. Players use a long stick called a cue to hit a white ball across the table so that it knocks coloured balls with numbers on them into six holes around the edge of the table.","ex":{"en":"We played pool together and were good mates","cn":"我们一起打过台球，是好哥们儿。"}},{"pos":"N-PLURAL 复数名词","cn":"（下注猜足球比赛结果的）赌球","en":"If you do the pools, you take part in a gambling competition in which people try to win money by guessing correctly the results of football matches.","ex":{"en":"The odds of winning the pools are about one in 20 million.","cn":"赌球获胜的几率大约是二千万分之一。"}}]},"examples":[{"en":"The students work individually, then pool their ideas in groups of six.","cn":"学生先分头工作，然后六人一组交流意见。"},{"en":"Police forces across the country are pooling resources in order to solve this crime.","cn":"全国各地警方通力合作以侦破这宗罪案。"}]},"poisoning":{"media":{"uk":"media/uk/poisoning__gb_1.mp3","us":"media/us/poisoning__us_1.mp3"},"oxford":{"phon":"ˈpɔɪzənɪŋ","pos":"noun","senses":[{"en":"the fact or state of poison having got into the body","cn":"中毒；服毒","ex":{"en":"a series of deaths caused by carbon monoxide poisoning","cn":"一氧化碳中毒引起的一连串死亡"}},{"en":"the act of killing or harming somebody/something by giving them poison","cn":"毒害；毒杀；投毒","ex":{"en":"The police suspected poisoning.","cn":"警方怀疑有人下毒。"}}]},"examples":[{"en":"At least 10 000 children are involved in accidental poisonings every year.","cn":"每年至少有 1 万名儿童意外中毒。"},{"en":"a series of deaths caused by carbon monoxide poisoning","cn":"一氧化碳中毒引起的一连串死亡"}],"base":"poison"},"politeness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving or speaking in a way that is correct for the social situation you are in, and showing that you are careful to consider other people’s needs and feelings","cn":""},{"en":"having good manners and knowing the correct way to behave in social situations","cn":""}]},"examples":[{"en":"She’s always very polite.","cn":"","src":"ld"},{"en":"We left the party as soon as it was polite to do so.","cn":"","src":"ld"}],"media":{"uk":"media/uk/politeness__gb_1.mp3","us":"media/us/politeness__us_1.mp3"},"oxford":{"phon":"pəˈlaɪtnəs","pos":"noun","senses":[{"en":"good manners and respect for the feelings of others","cn":"有礼貌的；客气的；儒雅的","ex":{"en":"He stood up out of politeness and offered her his seat.","cn":"他出于礼貌站了起来，要把座位让给她。"}},{"en":"the fact of being socially correct but not always sincere","cn":"应酬的；礼节性的；客套的","ex":{"en":"They welcomed him in with exaggerated politeness.","cn":"他们以夸张的礼貌欢迎他进来。"}}]}},"potatoes":{"lemma":"potato"},"pollution":{"media":{"uk":"media/uk/pollution__gb_1.mp3","us":"media/us/pollution__us_1.mp3"},"oxford":{"phon":"pəˈluːʃn","pos":"noun","senses":[{"en":"the process of making air, water, soil, etc. dirty; the state of being dirty","cn":"污染；玷污；弄脏","lab":"especially British English","ex":{"en":"air/water pollution","cn":"空气／水污染"}},{"en":"substances that make air, water, soil, etc. dirty","cn":"污染物；秽物；垃圾","ex":{"en":"beaches covered with pollution","cn":"秽物狼藉的海滩"}},{"en":"harmful or annoying levels of noise, or of artificial light at night","cn":"噪声污染；（夜间扰人的）强烈灯光","ex":{"en":"Heavy traffic flow is a major source of noise pollution in urban areas.","cn":"密集的车流是市区噪声污染的一个主要来源。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指有毒化学品造成的）污染","en":"Pollution is the process of polluting water, air, or land, especially with poisonous chemicals.","ex":{"en":"The fine was for the company's pollution of the air near its plants","cn":"罚款是因该公司对厂房周边空气造成了污染。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"污染物","en":"Pollution is poisonous or dirty substances that are polluting the water, air, or land somewhere.","ex":{"en":"The level of pollution in the river was falling.","cn":"这条河中的污染物水平在下降。"}}]},"examples":[{"en":"to reduce levels of environmental pollution","cn":"降低环境污染的程度"},{"en":"beaches covered with pollution","cn":"秽物狼藉的海滩"}]},"positioning":{"oxford":{"phon":"pəˈzɪʃənɪŋ","pos":"noun","senses":[{"en":"the act of putting somebody/something in a particular position","cn":"安装；安置；使处于","ex":{"en":"the positioning of speed cameras","cn":"测速摄像机的定位"}}]},"media":{"uk":"media/uk/positioning__gb_1.mp3","us":"media/us/positioning__us_1.mp3"},"base":"position"},"poverty":{"media":{"uk":"media/uk/poverty__gb_1.mp3","us":"media/us/poverty__us_1.mp3"},"oxford":{"phon":"ˈpɒvəti","pos":"noun","senses":[{"en":"the state of being poor","cn":"贫穷；贫困","g":"[uncountable]","lab":"US English","ex":{"en":"conditions of extreme/abject poverty","cn":"极度贫穷的状况"}},{"en":"a lack of something; poor quality","cn":"贫乏；短缺；劣质","g":"[uncountable, singular]","ex":{"en":"There is a poverty of colour in her work.","cn":"她的作品缺乏色彩。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"贫穷；贫困","en":"Poverty is the state of being extremely poor.","ex":{"en":"According to World Bank figures, 41 per cent of Brazilians live in absolute poverty","cn":"根据世界银行的统计数字，41%的巴西人生活在赤贫中。"}},{"pos":"N-SING 单数名词","cn":"贫乏；短缺；低劣","en":"You can use poverty to refer to any situation in which there is not enough of something or its quality is poor.","ex":{"en":"Britain has suffered from a poverty of ambition.","cn":"英国一直缺乏远大理想。"}}]},"examples":[{"en":"Many elderly people live in poverty.","cn":"许多老年人生活于贫困之中。"},{"en":"There is a poverty of colour in her work.","cn":"她的作品缺乏色彩。"}]},"possibly":{"media":{"uk":"media/uk/possibly__gb_1.mp3","us":"media/us/possibly__us_1.mp3"},"oxford":{"phon":"ˈpɒsəbli","pos":"adverb","senses":[{"en":"used to say that something might exist, happen or be true, but you are not certain","cn":"可能；或许","ex":{"en":"It was possibly their worst performance ever.","cn":"这也许是他们迄今为止最糟糕的表现。"}},{"en":"used with can/could to emphasize that you are surprised, annoyed, etc. about something","cn":"（与 can 或 could 连用，强调惊奇、恼怒等）","lab":"usually ironic","ex":{"en":"You can't possibly mean that!","cn":"你绝不会是那个意思吧！"}},{"en":"used with could to ask somebody politely to do something","cn":"（与 could 连用，表示委婉的请求）","ex":{"en":"Could you possibly open that window?","cn":"请你把那扇窗子打开好吗？"}},{"en":"used with can/could to say that somebody will do or has done as much as they can in order to make something happen","cn":"（与 can 或 could 连用）尽量，尽可能","ex":{"en":"I will come as soon as I possibly can.","cn":"我会尽快赶来的。"}},{"en":"used with negatives, especially can't/couldn't, to say strongly that you cannot do something or that something cannot or could not happen or be done","cn":"（与 can’t、couldn’t 等否定词连用，以加强语气）","ex":{"en":"I can't possibly tell you that!","cn":"我绝不会把那件事告诉你的！"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"或许；也许","en":"You use possibly to indicate that you are not sure whether something is true or might happen.","ex":{"en":"Exercise will not only lower blood pressure but possibly protect against heart attacks","cn":"锻炼不仅会降低血压，而且可能对心脏病有预防效果。"}},{"pos":"ADV 副词","cn":"（表示对所见或所闻感到惊讶、困惑或震惊）","en":"You use possibly to emphasize that you are surprised, puzzled, or shocked by something that you have seen or heard.","ex":{"en":"It was the most unexpected piece of news one could possibly imagine","cn":"这条新闻最出人意料了，真是让人想象不到。"}},{"pos":"ADV 副词","cn":"尽量；尽可能地","en":"You use possibly to emphasize that someone has tried their hardest to do something, or has done it as well as they can.","ex":{"en":"They've done everything they can possibly think of","cn":"凡是能想到的，他们都去做了。"}},{"pos":"ADV 副词","cn":"（加强语气）无论如何也","en":"You use possibly to emphasize that something definitely cannot happen or definitely cannot be done.","ex":{"en":"No I really can't possibly answer that!","cn":"不，我无论如何也回答不了那个问题。"}}]},"examples":[{"en":"‘Let me buy it for you.’ ‘That's very kind of you, but I couldn't possibly (= accept). ’ “","cn":"这个，我买给你吧。” “您太客气了。可我决不能让您破费呀。”"},{"en":"She found it difficult to get on with her, possibly because of the difference in their ages.","cn":"她觉得很难与她相处，这可能是因为她们年龄上的差距。"}]},"poses":{"lemma":"pose","media":{"uk":"media/uk/pose__gb_1.mp3","us":"media/us/pose__us_1.mp3"}},"poll":{"media":{"uk":"media/uk/poll__gb_1.mp3","us":"media/us/poll__us_1.mp3"},"oxford":{"phon":"pəʊl","pos":"noun","senses":[{"en":"the process of questioning people who are representative of a larger group in order to get information about the general opinion","cn":"民意测验；民意调查","g":"[countable]","ex":{"en":"to carry out/conduct a poll","cn":"进行民意测验"}},{"en":"the process of voting at an election; the process of counting the votes","cn":"选举投票；计票","g":"[countable]","ex":{"en":"The final result of the poll will be known tomorrow.","cn":"最终的投票结果将于明天公布。"}},{"en":"the number of votes given in an election","cn":"投票数","g":"[singular]","ex":{"en":"Labour is ahead in the poll.","cn":"工党的得票数领先。"}},{"en":"to receive a particular number of votes in an election","cn":"获得（票数）","g":"[transitive, intransitive]","ex":{"en":"They polled 39 per cent of the vote in the last election.","cn":"在上届选举中，他们获得了 39% 的选票。"},"pos":"verb"},{"en":"to ask a large number of members of the public what they think about something","cn":"对…进行民意调查","g":"[transitive, usually passive]","ex":{"en":"Over 50 per cent of those polled were against the proposed military action.","cn":"超过 50% 的民意调查受访者反对拟议的军事行动。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"民意测验；民意调查","en":"A poll is a survey in which people are asked their opinions about something, usually in order to find out how popular something is or what people intend to do in the future.","ex":{"en":"Polls show that the European treaty has gained support in Denmark","cn":"民意测验显示该欧盟条约已在丹麦获得支持。"}},{"pos":"VERB 动词","cn":"对…进行民意测验（或调查）","en":"If you are polled on something, you are asked what you think about it as part of a survey.","ex":{"en":"More than 18,000 people were polled","cn":"超过1.8万人接受了民意测验。"}},{"pos":"N-PLURAL 复数名词","cn":"政治选举；大选；投票地点","en":"The polls means an election for a country's government, or the place where people go to vote in an election.","ex":{"en":"In 1945, Winston Churchill was defeated at the polls","cn":"温斯顿·丘吉尔在1945年的大选中被击败。"}},{"pos":"VERB 动词","cn":"获得（…票数）","en":"If a political party or a candidate polls a particular number or percentage of votes, they get that number or percentage of votes in an election.","ex":{"en":"It was a disappointing result for the Greens who polled three percent","cn":"这个结果让绿党感到失望，他们只获得了3%的选票。"}}]},"examples":[{"en":"Over 50% of those polled were against the proposed military action.","cn":"民调中有超过 50% 的人反对拟议的军事行动。"},{"en":"They polled 39% of the vote in the last election.","cn":"在上届选举中，他们获得了 39% 的选票。"}]},"population":{"media":{"uk":"media/uk/population__gb_1.mp3","us":"media/us/population__us_1.mp3"},"oxford":{"phon":"ˌpɒpjuˈleɪʃn","pos":"noun","senses":[{"en":"all the people who live in a particular area, city or country; the total number of people who live there","cn":"（地区、国家等的）人口，人口数量","g":"[countable + singular or plural verb, uncountable]","ex":{"en":"One third of the world’s population consumes/consume two thirds of the world’s resources.","cn":"世界上三分之一的人口消耗着全球三分之二的资源。"}},{"en":"a particular group of people or animals living in a particular area","cn":"（统称）某地域的生物；族群；人口","g":"[countable + singular or plural verb]","ex":{"en":"the adult/student/working population","cn":"成人／学生／就业人口"}},{"en":"a collection of items being statistically analysed","cn":"（统称）某领域的生物；族群；人口","lab":"statistics","ex":{"en":"When populations are small, random events can lead them to behave atypically.","cn":"当人口规模较小时，随机事件可能会导致他们表现得异常。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（某一国家或地区的）全体人民，人口","en":"The population of a country or area is all the people who live in it.","ex":{"en":"Bangladesh now has a population of about 110 million.","cn":"孟加拉国现有大约1.1亿人口。"}},{"pos":"N-COUNT 可数名词","cn":"（某一国家或地区某类人或动物的）总数","en":"If you refer to a particular type of population in a country or area, you are referring to all the people or animals of that type there.","ex":{"en":"...75.6 per cent of the male population over sixteen.","cn":"16岁以上男性中的75.6%"}}]},"examples":[{"en":"One third of the world's population consumes/consume two thirds of the world's resources.","cn":"世界上三分之一的人口消耗着全球三分之二的资源。"},{"en":"the adult/working/rural, etc. population of the country","cn":"一国的成年人口、劳动人口、农村人口等"}]},"positions":{"lemma":"position","media":{"uk":"media/uk/position__gb_1.mp3","us":"media/us/position__us_1.mp3"}},"pornography":{"media":{"uk":"media/uk/pornography__gb_1.mp3","us":"media/us/pornography__us_1.mp3"},"oxford":{"phon":"pɔːˈnɒɡrəfi","pos":"noun","senses":[{"en":"magazines, DVDs, websites, etc. that describe or show naked people and sexual acts in order to make people feel sexually excited, especially in a way that many other people find offensive","cn":"淫秽作品；色情杂志（或影碟、网站等）","ex":{"en":"child pornography","cn":"儿童色情作品"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（总称）色情（或淫秽）作品","en":"Pornography refers to books, magazines, and films that are designed to cause sexual excitement by showing naked people or referring to sexual acts.","ex":{"en":"A nationwide campaign against pornography began in the summer.","cn":"一场全国性打击淫秽作品的行动在夏季打响了。"}}]},"examples":[{"en":"child pornography","cn":"儿童色情作品"}]},"porter":{"media":{"uk":"media/uk/porter__gb_1.mp3","us":"media/us/porter__us_1.mp3"},"oxford":{"phon":"ˈpɔːtə(r)","pos":"noun","senses":[{"en":"a person whose job is carrying people’s bags and other loads, especially at a train station, an airport or in a hotel","cn":"（尤指火车站、机场或旅馆）行李员，搬运工","ex":{"en":"Some Sherpas act as guides and porters for mountaineering expeditions.","cn":"一些夏尔巴人充当登山探险的向导和搬运工。"}},{"en":"a person whose job is to move patients from one place to another in a hospital","cn":"（医院里护送病人的）护工","lab":"British English"},{"en":"a person whose job is to be in charge of the entrance to a hotel, large building, college, etc.","cn":"门卫；门房","lab":"British English","ex":{"en":"the night porter","cn":"夜班门卫"}},{"en":"a person whose job is helping passengers on a train, especially in a sleeping car","cn":"（尤指卧铺车厢的）列车服务员","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"看门人；门房","en":"A porter is a person whose job is to be in charge of the entrance of a building such as a hotel."},{"pos":"N-COUNT 可数名词","cn":"（火车站或宾馆的）行李员，搬运工","en":"A porter is a person whose job is to carry things, for example people's luggage at a railway station or in a hotel."},{"pos":"N-COUNT 可数名词","cn":"（列车卧车的）服务生","en":"A porter on a train is a person whose job is to make up beds in the sleeping car and to help passengers."},{"pos":"N-COUNT 可数名词","cn":"（医院运送病人的）护工，勤杂工","en":"In a hospital, a porter is someone whose job is to move patients from place to place."}]},"examples":[{"en":"The hotel porter will get you a taxi.","cn":"旅馆的门卫会给你叫出租车的。"},{"en":"the night porter","cn":"夜班门卫"}]},"positively":{"oxford":{"phon":"ˈpɒzətɪvli","pos":"adverb","senses":[{"en":"used to emphasize the truth of a statement, especially when this is surprising or when it contrasts with a previous statement","cn":"绝对地；肯定地","ex":{"en":"Some diets may be positively dangerous.","cn":"有些饮食可能是非常危险的。"}},{"en":"in a way that shows you are thinking of the good things about a situation, not the bad","cn":"乐观地；肯定地；积极地","ex":{"en":"Very few of those interviewed spoke positively about their childhood.","cn":"接受采访的人当中，很少有人说他们的童年是快乐的。"}},{"en":"in a way that shows you approve of or agree with something/somebody","cn":"赞成地；积极地","ex":{"en":"The industry has responded positively to these developments.","cn":"该行业对这些发展做出了积极的回应。"}},{"en":"in a way that leaves no possibility of doubt","cn":"明确地；明白无误地","ex":{"en":"Her attacker has now been positively identified by police.","cn":"袭击她的人现在已被警方确认。"}},{"en":"in a way that contains or produces the type of electricity that is opposite to that carried by an electron","cn":"带（或产生）正电地","lab":"specialist","ex":{"en":"positively charged protons","cn":"带正电的质子"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"确实；肯定地","en":"You use positively to emphasize that you really mean what you are saying.","ex":{"en":"This is positively the worst thing that I can even imagine","cn":"这确实是我能想象到的最糟糕的事情。"}},{"pos":"ADV 副词","cn":"的的确确；毋庸置疑","en":"You use positively to emphasize that something really is the case, although it may sound surprising or extreme.","ex":{"en":"He's changed since he came back — he seems positively cheerful","cn":"他回来后变了个样，看起来确实很高兴。"}}]},"media":{"uk":"media/uk/positively__gb_1.mp3","us":"media/us/positively__us_1.mp3"},"examples":[{"en":"Very few of those interviewed spoke positively about their childhood.","cn":"接受采访的人当中，很少有人说他们的童年是快乐的。"},{"en":"The instructions were not just confusing, they were positively misleading.","cn":"这些指示不单令人费解，而且肯定会误导人。"}]},"pope":{"media":{"uk":"media/uk/pope__gb_1.mp3","us":"media/us/pope__us_1.mp3"},"oxford":{"phon":"pəʊp","pos":"noun","senses":[{"en":"the leader of the Roman Catholic Church, who is also the Bishop of Rome","cn":"教皇","ex":{"en":"the election of a new pope","cn":"新教皇的选举"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（天主教）教皇","en":"The Pope is the head of the Roman Catholic Church.","ex":{"en":"...the Pope's message to the people.","cn":"教皇给人们的训诫"}}]},"examples":[{"en":"‘Will they arrive late?’ ‘Is the Pope a Catholic?’ “","cn":"他们会迟到吗？” “这还用问吗？”"},{"en":"the election of a new pope","cn":"新教宗的选举"}]},"posting":{"oxford":{"phon":"ˈpəʊstɪŋ","pos":"noun","senses":[{"en":"an act of sending somebody to a particular place to do their job, especially for a limited period of time","cn":"派驻","lab":"especially British English","ex":{"en":"an overseas posting","cn":"派驻海外"}},{"en":"a message sent to a discussion group on the internet; a piece of writing that forms part of a blog","cn":"（发送到互联网讨论组的）帖子，信息；博文；网志文章","ex":{"en":"job postings on the website","cn":"网站上的职位发布"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"派任；外派","en":"If you get a posting to a different town or country, your employers send you to work there, usually for several years.","ex":{"en":"He was rewarded with a posting to New York","cn":"作为奖励，他被派往纽约工作。"}},{"pos":"N-COUNT 可数名词","cn":"（军队的）派驻，派遣","en":"If a member of an armed force gets a posting to a particular place, they are sent to live and work there for a period.","ex":{"en":"...awaiting his posting to a field ambulance corps in early 1941.","cn":"他1941年年初等待被派往野战救护队"}},{"pos":"N-COUNT 可数名词","cn":"（因特网上的）帖子","en":"A posting is a message that is placed on the Internet, for example on a bulletin board or website, for everyone to read.","ex":{"en":"Postings on the Internet can be accessed from anywhere in the world.","cn":"因特网上的帖子在世界任何一个地方都能读到。"}}]},"media":{"uk":"media/uk/posting__gb_1.mp3","us":"media/us/posting__us_1.mp3"},"examples":[{"en":"an overseas posting","cn":"派驻海外"},{"en":"shortly before his posting to South Africa","cn":"在他被派往南非前不久"}],"base":"post"},"possessed":{"media":{"uk":"media/uk/possessed__gb_1.mp3","us":"media/us/possessed__us_1.mp3"},"oxford":{"phon":"pəˈzest","pos":"adjective","senses":[{"en":"controlled by an evil spirit","cn":"着了魔","ex":{"en":"She has convinced herself that she is possessed by the devil.","cn":"她确信自己被魔鬼附了身。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"着魔的；鬼怪附体的","en":"If someone is described as being possessed by an evil spirit, it is believed that their mind and body are controlled by an evil spirit.","ex":{"en":"She even claimed the couple's daughter was possessed by the devil","cn":"她甚至宣称那对夫妇的女儿被魔鬼附了体。"}},{"pos":"ADJ 形容词","cn":"拥有的；占有的；具有的","en":"If someone or something is possessed of a particular quality, ability, or feature, they have that quality, ability, or feature. If someone is possessed of a particular feeling or belief, they have that feeling or belief.","ex":{"en":"He is possessed of the most brilliant talents","cn":"他才华横溢。"}}]},"examples":[{"en":"He flew out of the room like a man possessed.","cn":"他猛然冲出房门，像着了魔似的。"},{"en":"She has convinced herself that she is possessed by the devil.","cn":"她确信自己被魔鬼附了身。"}],"base":"possess"},"poetry":{"media":{"uk":"media/uk/poetry__gb_1.mp3","us":"media/us/poetry__us_1.mp3"},"oxford":{"phon":"ˈpəʊətri","pos":"noun","senses":[{"en":"poems in general; poems as a genre of literature","cn":"诗歌；诗","g":"[uncountable]","lab":"US English","ex":{"en":"lyric/epic poetry","cn":"抒情诗；史诗"}},{"en":"a quality of beauty, style and feeling","cn":"优美；诗意","g":"[uncountable, singular]","lab":"approving","ex":{"en":"There was poetry in all her gestures.","cn":"她一举一动都很优美。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（作为文学形式的）诗，诗歌，韵文","en":"Poems, considered as a form of literature, are referred to as poetry .","ex":{"en":"...Russian poetry","cn":"俄罗斯诗歌"}},{"pos":"N-UNCOUNT 不可数名词","cn":"诗的意境；诗一般美的事物","en":"You can describe something very beautiful as poetry .","ex":{"en":"His music is purer poetry than a poem in words.","cn":"他的音乐比真正的诗歌更具诗意。"}}]},"examples":[{"en":"There was poetry in all her gestures.","cn":"她一举一动都很优美。"},{"en":"epic/lyric/pastoral, etc. poetry","cn":"史诗、抒情诗、田园诗等"}]},"powder":{"media":{"img":["media/pic/makeup_comp.jpg","media/thumb/powder.jpg"],"uk":"media/uk/powder__gb_1.mp3","us":"media/us/powder__us_1.mp3"},"oxford":{"phon":"ˈpaʊdə(r)","pos":"noun","senses":[{"en":"a dry mass of very small fine pieces or grains","cn":"粉末；细面","g":"[uncountable, countable]","ex":{"en":"milk/chilli/cocoa powder","cn":"奶粉；辣椒粉；可可粉"}},{"en":"a very fine, soft, dry substance that you can put on your face to make it look smooth and dry","cn":"扑面粉；美容粉","g":"[uncountable]","ex":{"en":"I only use lipstick and a little powder.","cn":"我只用口红和一点粉。"}},{"en":"explosive powder used especially in bombs or fireworks","cn":"火药","g":"[uncountable]"},{"en":"to put powder on something","cn":"傅粉；抹粉","ex":{"en":"She powdered her face and put on her lipstick.","cn":"她往脸上搽了粉，又涂上了口红。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"粉末；细面","en":"Powder consists of many tiny particles of a solid substance.","ex":{"en":"Put a small amount of the powder into a container and mix with water","cn":"把少量粉末放入容器，加水混合。"}},{"pos":"N-MASS 物质名词","cn":"同 face powder","en":"Powder is the same as face powder ."},{"pos":"VERB 动词","cn":"往…上搽粉；往…上抹粉","en":"If a woman powders her face or some other part of her body, she puts face powder or talcum powder on it.","ex":{"en":"She powdered her face and applied her lipstick and rouge.","cn":"她往脸上搽了粉，抹了口红和胭脂。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"同 gunpowder","en":"Powder is the same as gunpowder .","ex":{"en":"The smell of powder was in the air.","cn":"空气里有股火药味儿。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"粉状雪；干细雪","en":"Powder is very fine snow.","ex":{"en":"...a day's powder skiing.","cn":"一天的滑雪时光"}}]},"examples":[{"en":"A wide range of cleaning fluids and powders is available.","cn":"有各种各样的清洗液和去污粉供应。"},{"en":"She powdered her face and put on her lipstick.","cn":"她往脸上搽了粉，又涂上了口红。"}]},"possessive":{"oxford":{"phon":"pəˈzesɪv","pos":"adjective","senses":[{"en":"demanding total attention or love; not wanting somebody to be independent","cn":"要求悉心关爱的；占有欲强的","ex":{"en":"Some parents are too possessive of their children.","cn":"有些父母过分要求子女百依百顺。"}},{"en":"not liking to lend things or share things with others","cn":"不愿分享的；有独占欲望的","ex":{"en":"Jimmy's very possessive about his toys.","cn":"吉米的玩具谁也碰不得。"}},{"en":"showing that something belongs to somebody/something","cn":"表示所属关系的；所有格的","g":"[usually before noun]","lab":"grammar","ex":{"en":"possessive pronouns (= yours, theirs, etc.)","cn":"物主代词"}},{"en":"a pronoun or a form of a word that expresses the fact that something belongs to somebody/something","cn":"所有格；属有词","g":"[countable]","ex":{"en":"‘Ours’ and ‘their’ are possessives.","cn":"ours 和 their 是所有格形式。"},"pos":"noun"},{"en":"the special form of a word that expresses belonging","cn":"所有格","g":"[singular]","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"占有欲强的；有控制欲的","en":"Someone who is possessive about another person wants all that person's love and attention.","ex":{"en":"Danny could be very jealous and possessive about me","cn":"丹尼很爱吃醋，对我的占有欲很强。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不愿与人分享的；自私的","en":"Someone who is possessive about things that they own does not like other people to use them.","ex":{"en":"People were very possessive about their coupons.","cn":"人们很想独占礼券。"}},{"pos":"ADJ 形容词","cn":"（语法中）所有格的","en":"In grammar, a possessive determiner or possessive adjective is a word such as 'my' or 'his' which shows who or what something belongs to or is connected with. The possessive form of a name or noun has 's added to it, as in 'Jenny's' or 'cat's'."},{"pos":"N-COUNT 可数名词","cn":"所有格；物主代词","en":"A possessive is a possessive determiner or the possessive form of a name or noun."}]},"media":{"uk":"media/uk/possessive__gb_1.mp3","us":"media/us/possessive__us_1.mp3"},"examples":[{"en":"Some parents are too possessive of their children.","cn":"有些父母过分要求子女百依百顺。"},{"en":"‘Ours’ and ‘their’ are possessives. * ours","cn":"和 their 是所有格形式。"}]},"possess":{"media":{"uk":"media/uk/possess__gb_1.mp3","us":"media/us/possess__us_1.mp3"},"oxford":{"phon":"pəˈzes","pos":"verb","senses":[{"en":"to have or own something","cn":"有；拥有","lab":"formal","ex":{"en":"He was charged with possessing a shotgun without a licence.","cn":"他被控无照拥有猎枪。"}},{"en":"to have a particular quality or feature","cn":"具有（特质）","lab":"formal","ex":{"en":"I'm afraid he doesn't possess a sense of humour.","cn":"恐怕他没有什么幽默感。"}},{"en":"to have a powerful effect on somebody and control the way that they think, behave, etc.","cn":"攫住；支配；控制","lab":"literary","ex":{"en":"A terrible fear possessed her.","cn":"一种可怕的恐惧占据了她的心。"}},{"en":"to make somebody do something that seems strange or unreasonable","cn":"使言行失常","ex":{"en":"What possessed him to say such a thing?","cn":"他着了什么魔竟说出这种话来？"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"占有；拥有","en":"If you possess something, you have it or own it.","ex":{"en":"He was then arrested and charged with possessing an offensive weapon","cn":"他随后被逮捕，并被控拥有攻击性武器。"}},{"pos":"VERB 动词","cn":"具备，具有（特定品质、才能等）","en":"If someone or something possesses a particular quality, ability, or feature, they have it.","ex":{"en":"...individuals who are deemed to possess the qualities of sense, loyalty and discretion","cn":"被认为具备了理性、忠诚和判断力的人"}},{"pos":"VERB 动词","cn":"（情感或信仰）影响，控制","en":"If a feeling or belief possesses you, it strongly influences your thinking or behaviour.","ex":{"en":"Absolute terror possessed her","cn":"她恐惧到了极点。"}},{"pos":"PHRASE 短语","cn":"（表示惊讶）是什么驱使…（干…），是什么促使…（做…）","en":"If you ask what possessed someone to do something, you are emphasizing your great surprise that they have done something which you consider foolish or dangerous.","ex":{"en":"What on earth had possessed her to agree to marry him?","cn":"究竟是什么让她同意嫁给他的？"}}]},"examples":[{"en":"The gallery possesses a number of the artist's early works.","cn":"这家画廊藏有一些那位画家的早期作品。"},{"en":"What possessed him to say such a thing?","cn":"他着了什么魔竟说出这种话来？"}]},"pocket":{"media":{"uk":"media/uk/pocket__gb_1.mp3","us":"media/us/pocket__us_1.mp3","img":["media/ldoce/img/pool_table.jpg"]},"oxford":{"phon":"ˈpɒkɪt","pos":"noun","senses":[{"en":"a small piece of material like a small bag sewn into or onto a piece of clothing so that you can carry things in it","cn":"衣袋；口袋；兜","sc":"in clothing","ex":{"en":"a jacket/coat/shirt/trouser pocket","cn":"夹克／外套／衬衫／裤子口袋"}},{"en":"a small bag or container fastened to something so that you can put things in it, for example, in a car door or in a bag","cn":"（附在车门上、提包内等的）小口袋，小容器","sc":"small container","ex":{"en":"Information about safety procedures is in the pocket in front of you (= on a plane).","cn":"安全求生的资料放在您前方的小袋子里。"}},{"en":"used to talk about the amount of money that you have to spend","cn":"钱财；财力；资金","g":"[usually singular]","sc":"money","ex":{"en":"We have holidays to suit every pocket.","cn":"我们有适合各种程度消费的度假方式。"}},{"en":"a small group or area that is different from everyone or everything around it","cn":"（与周围不同的）小组织，小区域","sc":"small group/area","ex":{"en":"There are still a few isolated pockets of resistance to the new regime.","cn":"现在仍有零星孤立的势力反对新政权。"}},{"en":"any of the holes or nets around the edges of the table used in the games of billiards, pool or snooker, which you have to hit the ball into","cn":"球袋；网袋","sc":"in billiards, etc."},{"en":"to put something into your pocket","cn":"把…放进衣袋","sc":"put into pocket","ex":{"en":"She paid for the drink and pocketed the change without counting it.","cn":"她付了饮料费，把找回的零钱数都没数就装进了口袋。"},"pos":"verb"},{"en":"to take or keep something, especially an amount of money, that does not belong to you","cn":"攫取；揩油；中饱私囊","sc":"money","ex":{"en":"He regularly charges passengers more than the normal fare and pockets the difference.","cn":"他经常多收乘客票钱，把差额塞进自己的腰包。"},"pos":"verb"},{"en":"to earn or win an amount of money","cn":"挣；赚下","sc":"money","ex":{"en":"Last year, she pocketed over $1 million in advertising contracts.","cn":"去年，她从广告合同中赚了 100 多万美元。"},"pos":"verb"},{"en":"to hit a ball into a pocket","cn":"击（球）入球袋","sc":"in billiards, etc.","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"衣袋；口袋；兜","en":"A pocket is a kind of small bag which forms part of a piece of clothing, and which is used for carrying small things such as money or a handkerchief.","ex":{"en":"He took his flashlight from his jacket pocket and switched it on","cn":"他从夹克口袋里拿出手电筒，打开开关。"}},{"pos":"N-COUNT 可数名词","cn":"钱；财力","en":"You can use pocket in a lot of different ways to refer to money that people have, get, or spend. For example, if someone gives or pays a lot of money, you can say that they dig deep into their pocket. If you approve of something because it is very cheap to buy, you can say that it suits people's pockets .","ex":{"en":"When you come to choosing a dining table, it really is worth digging deep into your pocket for the best you can afford.","cn":"选购餐桌时，尽财力所能买最好的是很值得的。"}},{"pos":"ADJ 形容词","cn":"（可）放在衣袋里的；小型的；袖珍的","en":"You use pocket to describe something that is small enough to fit into a pocket, often something that is a smaller version of a larger item.","ex":{"en":"...a pocket calculator.","cn":"袖珍计算器"}},{"pos":"N-COUNT 可数名词","cn":"（作为发生处或与周围不同的）小块地区","en":"A pocket of something is a small area where something is happening, or a small area which has a particular quality, and which is different from the other areas around it.","ex":{"en":"He survived the earthquake after spending 3 days in an air pocket","cn":"他在气窝里度过了3天，得以从地震中幸存。"}},{"pos":"VERB 动词","cn":"把…装进腰包；将…据为己有","en":"If someone who is in possession of something valuable such as a sum of money pockets it, they steal it or take it for themselves, even though it does not belong to them.","ex":{"en":"Dishonest importers would be able to pocket the VAT collected from customers.","cn":"不诚实的进口商将会能够把从顾客那里收取的增值税据为己有。"}},{"pos":"VERB 动词","cn":"（常指以轻松或看似不公平的方式）赢得，获得，赚得","en":"If you say that someone pockets something such as a prize or sum of money, you mean that they win or obtain it, often without needing to make much effort or in a way that seems unfair.","ex":{"en":"He pocketed more money from this tournament than in his entire three years as a professional.","cn":"他在这次锦标赛上获得的奖金比他整整3年职业生涯的收入都多。"}},{"pos":"VERB 动词","cn":"把…放入衣袋","en":"If someone pockets something, they put it in their pocket, for example because they want to steal it or hide it.","ex":{"en":"Anthony snatched his letters and pocketed them","cn":"安东尼抓过他的信，塞入了口袋。"}},{"pos":"PHRASE 短语","cn":"（钱）在口袋里留不住，一有就想花掉","en":"If you say that some money is burning a hole in someone's pocket, you mean that they want to spend it as soon as possible.","ex":{"en":"It's Saturday, you're down the high street and you've got a few quid burning a hole in your pocket.","cn":"周六走在商街上，口袋里有几个钱忍不住想要花掉。"}},{"pos":"PHRASE 短语","cn":"在（某人）掌握之中；受制于（某人）","en":"If you say that someone is in someone else's pocket, you disapprove of the fact that the first person is willing to do whatever the second person tells them, for example out of weakness or in return for money.","ex":{"en":"The board of directors must surely have been in Johnstone's pocket.","cn":"董事会肯定已被约翰斯通掌控了。"}},{"pos":"PHRASE 短语","cn":"为（自己或某人）牟利；使（自己或某人）中饱私囊","en":"If you say that someone is lining their own or someone else's pockets, you disapprove of them because they are making money dishonestly or unfairly.","ex":{"en":"It is estimated that 5,000 bank staff could be lining their own pockets from customer accounts.","cn":"据估计可能会有5,000名银行职员利用客户账户中饱私囊。"}},{"pos":"PHRASE 短语","cn":"缺钱；赔钱","en":"If you are out of pocket, you have less money than you should have or than you intended, for example because you have spent too much or because of a mistake.","ex":{"en":"They were well out of pocket — they had spent far more in Hollywood than he had earned","cn":"他们非常缺钱——他们在好莱坞的花费已经远远超出了他的收入。"}},{"pos":"PHRASE 短语","cn":"扒窃","en":"If someone picks your pocket, they steal something from your pocket, usually without you noticing.","ex":{"en":"They were more in danger of having their pockets picked than being shot at.","cn":"比起遭到枪击，他们被人扒窃的危险更大。"}}]},"examples":[{"en":"She paid for the drink and pocketed the change without counting it.","cn":"她付了饮料费，把找回的零钱数都没数就装进了口袋。"},{"en":"He regularly charges passengers more than the normal fare and pockets the difference.","cn":"他经常多收乘客票钱，把差额塞进自己的腰包。"}]},"poster":{"media":{"uk":"media/uk/poster__gb_1.mp3","us":"media/us/poster__us_1.mp3"},"oxford":{"phon":"ˈpəʊstə(r)","pos":"noun","senses":[{"en":"a large notice, often with a picture on it, that is put in a public place to advertise something","cn":"招贴画；海报","ex":{"en":"campaign/election posters","cn":"竞选／选举海报"}},{"en":"a large picture that is printed on paper and put on a wall as decoration","cn":"（大幅）装饰画","ex":{"en":"posters of her favourite pop stars","cn":"她所喜爱的流行歌星的大幅画片"}},{"en":"a person who posts a message on a message board (= a place on a website where people can read or write messages)","cn":"（在网络留言板上）发布消息的人，张贴信息的人"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大幅广告；海报；招贴画","en":"A poster is a large notice or picture that you stick on a wall or board, often in order to advertise something."}]},"examples":[{"en":"posters of her favourite pop stars","cn":"她所喜爱的流行歌星的海报"},{"en":"a poster campaign (= an attempt to educate people about sth by using posters )","cn":"招贴宣传运动"}]},"policy":{"media":{"uk":"media/uk/policy__gb_1.mp3","us":"media/us/policy__us_1.mp3"},"oxford":{"phon":"ˈpɒləsi","pos":"noun","senses":[{"en":"a plan of action agreed or chosen by a political party, a business, etc.","cn":"政策；方针","g":"[countable, uncountable]","lab":"especially North American English","ex":{"en":"the present government’s policy on education","cn":"现政府的教育政策"}},{"en":"a principle that you believe in that influences how you behave; a way in which you usually behave","cn":"原则；为人之道","g":"[countable, uncountable]","lab":"formal","ex":{"en":"She is following her usual policy of ignoring all offers of help.","cn":"她遵循着自己的一贯原则，对于他人的主动帮助一概不予理睬。"}},{"en":"a written statement of a contract of insurance","cn":"保险单","g":"[countable]","ex":{"en":"Check the terms of the policy before you sign.","cn":"仔细阅读保险单的条款后再签字。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（尤指政治、经济或商业方面的）政策，方针，策略","en":"A policy is a set of ideas or plans that is used as a basis for making decisions, especially in politics, economics, or business.","ex":{"en":"...plans which include changes in foreign policy and economic reforms.","cn":"包括转变外交政策和改革经济的计划"}},{"pos":"N-COUNT 可数名词","cn":"（针对某一问题或某国的）政策，态度，行动","en":"An official organization's policy on a particular issue or towards a country is their attitude and actions regarding that issue or country.","ex":{"en":"...the organisation's future policy towards South Africa.","cn":"该组织未来对南非的政策"}},{"pos":"N-COUNT 可数名词","cn":"保险单；保险契约","en":"An insurance policy is a document which shows the agreement that you have made with an insurance company.","ex":{"en":"You are advised to read the small print of household and motor insurance policies.","cn":"建议阅读家庭财产和汽车保险单中的附属细则。"}}]},"examples":[{"en":"She is following her usual policy of ignoring all offers of help.","cn":"她遵循着自己的一贯原则，对于他人的主动帮助一概不予理睬。"},{"en":"The company has adopted a firm policy on shoplifting.","cn":"那家公司对店内行窃采取了严厉的措施。"}]},"point":{"media":{"uk":"media/uk/point__gb_1.mp3","us":"media/us/point__us_1.mp3","img":["media/ldoce/img/point.jpg"]},"oxford":{"phon":"pɔɪnt","pos":"noun","senses":[{"en":"a thing that somebody says or writes giving their opinion or stating a fact","cn":"论点；观点；见解","g":"[countable]","sc":"opinion/fact","ex":{"en":"She made several interesting points in the article.","cn":"她在文章中提出了几个有趣的观点。"}},{"en":"the main or most important idea in something that is said or done","cn":"重点；要点；核心问题","g":"[countable]","sc":"main idea","ex":{"en":"The point is you shouldn't have to wait so long to see a doctor.","cn":"关键是看病不该等那么长时间。"}},{"en":"the purpose or aim of something","cn":"意图；目的；理由","g":"[uncountable, singular]","sc":"purpose","ex":{"en":"What's the point of all this violence?","cn":"这些暴行的意图何在？"}},{"en":"a particular detail or fact","cn":"具体细节（或事实）","g":"[countable]","sc":"detail","ex":{"en":"Can you explain that point again?","cn":"你能再解释一下那一点吗？"}},{"en":"a particular quality or feature that somebody/something has","cn":"特点；特性；特征","g":"[countable]","sc":"quality","ex":{"en":"Tact is not one of her strong points.","cn":"她不善于圆通处事。"}},{"en":"a particular time or stage of development","cn":"时刻；关头；瞬间；阶段","g":"[countable]","sc":"time","ex":{"en":"We had reached the point when there was no money left.","cn":"我们曾落到身无分文的地步。"}},{"en":"a particular place or area","cn":"某地方；地点","g":"[countable]","sc":"place","ex":{"en":"I'll wait for you at the meeting point in the arrivals hall.","cn":"我将在到港大厅的迎接处等你。"}},{"en":"one of the marks of direction around a compass","cn":"（罗盘上的）罗经点，方位点","g":"[countable]","sc":"direction","ex":{"en":"the points of the compass (= N, S, E, W, etc.)","cn":"罗盘上的罗经点"}},{"en":"an individual unit that adds to a score in a game or sports competition","cn":"得分；点","g":"[countable]","sc":"in competition","ex":{"en":"to win/lose a point","cn":"赢／输一分"}},{"en":"a mark or unit on a scale of measurement","cn":"（单位）点；标度","g":"[countable]","sc":"measurement","ex":{"en":"The party's share of the vote fell by ten percentage points.","cn":"该党的得票率下跌了十个百分点。"}},{"en":"a unit of credit towards an award or benefit","cn":"分；积点","g":"[countable]","sc":"measurement","ex":{"en":"Applicants are awarded points on criteria such as education, skills and knowledge of English.","cn":"申请人将根据教育、技能和英语水平等标准评分。"}},{"en":"the sharp, thin end of something","cn":"尖端；尖头","g":"[countable]","sc":"sharp end","ex":{"en":"the point of a pencil/knife/pin","cn":"铅笔／刀／大头针尖"}},{"en":"a narrow piece of land that stretches into the sea","cn":"岬角；尖地；海角","g":"[countable]","sc":"land","ex":{"en":"The ship sailed around the point.","cn":"那条船绕过了岬角。"}},{"en":"a small round mark used in writing, especially the mark that separates a whole number from the part that comes after it","cn":"小数点；点","g":"[countable]","sc":"punctuation","ex":{"en":"two point six (2.6)","cn":"二点六"}},{"en":"a very small dot of light or colour","cn":"光点；色点","g":"[countable]","sc":"of light/colour","ex":{"en":"The stars were points of light in the sky.","cn":"天空中的点点光亮就是星星。"}},{"en":"a place in a wall, etc. where a piece of equipment can be connected to electricity","cn":"（电源）插座","g":"[countable]","lab":"British English","sc":"for electricity","ex":{"en":"a power/shaver/telephone point","cn":"电源／剃须刀／电话插座"}},{"en":"the hard tops of the toes of a kind of shoe that a ballet dancer balances on","cn":"（芭蕾舞鞋的）硬鞋尖","g":"[plural]","sc":"in ballet"},{"en":"a piece of track at a place where a railway line divides that can be moved to allow a train to change tracks","cn":"转辙器；道岔；尖轨","g":"[plural]","lab":"British English","sc":"on railway track"},{"en":"a unit of measurement for the size of letters in printing or on a computer screen, etc.","cn":"（印刷物或计算机屏幕上字体大小的单位）点，磅值","g":"[uncountable]","sc":"size of letters","ex":{"en":"Change the text to 10 point.","cn":"把文本字体大小变为 10 点。"}},{"en":"to stretch out your finger or something held in your hand towards somebody/something in order to show somebody where a person or thing is","cn":"（用手指头或物体）指，指向","g":"[intransitive, transitive, no passive]","sc":"show with finger","ex":{"en":"‘What's your name?’ he asked, pointing at the child with his pen.","cn":"他用笔指着小孩问：“你叫什么名字？”"},"pos":"verb"},{"en":"to aim something at somebody/something","cn":"瞄准","g":"[transitive]","sc":"aim","ex":{"en":"He pointed the gun at her head.","cn":"他举枪对准了她的头。"},"pos":"verb"},{"en":"to face in or be directed towards a particular direction","cn":"对着；朝向","g":"[intransitive]","sc":"face direction","ex":{"en":"The telescope was pointing in the wrong direction.","cn":"望远镜对错了方向。"},"pos":"verb"},{"en":"to direct your cursor at a particular point on the screen; to link to a particular web page","cn":"（在屏幕上）用光标指着；链接（浏览器）到","g":"[intransitive, transitive]","sc":"on a computer","ex":{"en":"Shopping on the Web is pretty simple—you just point and click and wait.","cn":"网上购物很简单，只需将光标对准，点击并等待。"},"pos":"verb"},{"en":"to lead to or suggest a particular development or logical argument","cn":"（意思上）指向；引导；指引","g":"[intransitive, transitive]","sc":"lead to","ex":{"en":"The evidence seems to point in that direction.","cn":"证据似乎指向那个方向。"},"pos":"verb"},{"en":"to show somebody which way to go","cn":"指路；指点","g":"[transitive]","sc":"show the way","ex":{"en":"I wonder if you could point me in the right direction for the bus station.","cn":"请问您能指点我到公共汽车站往哪个方向走吗？"},"pos":"verb"},{"en":"to stretch your toes and foot so that they form a straight line with your leg","cn":"绷直（脚尖）","g":"[transitive]","sc":"toes","ex":{"en":"Reach up with your arms and point your toes.","cn":"手臂向上伸展，脚尖绷直。"},"pos":"verb"},{"en":"to put mortar (= a mixture of sand, water, etc that becomes hard when dry) between the bricks, stones, etc. used to build a wall","cn":"（用灰泥）抹砖缝，勾缝","g":"[transitive]","sc":"wall","ex":{"en":"The house needs pointing before winter.","cn":"房子在冬天之前需要指点。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"观点；看法；论点","en":"You use point to refer to something that someone has said or written.","ex":{"en":"We disagree with every point Mr Blunkett makes","cn":"布伦基特先生提出的观点我们一个都不同意。"}},{"pos":"N-SING 单数名词","cn":"论据；道理","en":"If you say that someone has a point, or if you take their point, you mean that you accept that what they have said is important and should be considered.","ex":{"en":"'If he'd already killed once, surely he'd have killed Sarah?' She had a point there","cn":"“如果他杀过一次人，那他一定已经杀了萨拉吧？”她说得有道理。"}},{"pos":"N-SING 单数名词","cn":"要点；核心问题","en":"The point of what you are saying or discussing is the most important part that provides a reason or explanation for the rest.","ex":{"en":"'Did I ask you to talk to me?' — 'That's not the point.'","cn":"“我请你跟我谈了吗？”——“问题不在这儿。”"}},{"pos":"N-SING 单数名词","cn":"意义；目的；作用","en":"If you ask what the point of something is, or say that there is no point in it, you are indicating that a particular action has no purpose or would not be useful.","ex":{"en":"What was the point of thinking about him?","cn":"想他有什么用呢？"}},{"pos":"N-COUNT 可数名词","cn":"细节；方面；特性","en":"A point is a detail, aspect, or quality of something or someone.","ex":{"en":"Many of the points in the report are correct","cn":"报告中的很多细节是正确的。"}},{"pos":"N-COUNT 可数名词","cn":"地点；地方；（表示位置的）点，处","en":"A point is a particular place or position where something happens.","ex":{"en":"As a mark of respect the emperor met him at a point several weeks' march from the capital","cn":"出于尊重，皇帝在离首都还有几个星期路程的地方迎接了他。"}},{"pos":"N-SING 单数名词","cn":"（某一）时刻，阶段","en":"You use point to refer to a particular time, or to a particular stage in the development of something.","ex":{"en":"We're all going to die at some point","cn":"我们都将在某个时间死去。"}},{"pos":"N-COUNT 可数名词","cn":"尖；尖端；尖头","en":"The point of something such as a pin, needle, or knife is the thin, sharp end of it."},{"pos":"","cn":"（口语中表示）小数点","en":"In spoken English, you use point to refer to the dot or mark in a decimal number that separates the whole numbers from the fractions.","ex":{"en":"This is FM stereo one oh three point seven","cn":"这里是调频立体声103.7。"}},{"pos":"N-COUNT 可数名词","cn":"（用作某些体育运动等计分单位的）点，分","en":"In some sports, competitions, and games, a point is one of the single marks that are added together to give the total score.","ex":{"en":"They lost the 1977 World Cup final to Australia by a single point","cn":"他们在1977年的世界杯决赛中仅以一分之差输给了澳大利亚队。"}},{"pos":"N-COUNT 可数名词","cn":"罗经（方位）点","en":"The points of the compass are directions such as North, South, East, and West.","ex":{"en":"Sightseers arrived from all points of the compass.","cn":"观光者来自四面八方。"}},{"pos":"N-PLURAL 复数名词","cn":"（铁轨的）轨尖，道岔","en":"On a railway track, the points are the levers and rails at a place where two tracks join or separate. The points enable a train to move from one track to another.","ex":{"en":"...the rattle of the wheels across the points.","cn":"驶过道岔的车轮发出的哐啷哐啷声"}},{"pos":"N-COUNT 可数名词","cn":"插座","en":"A point is an electric socket.","ex":{"en":"...too far away from the nearest electrical point.","cn":"离最近的电掣位也太远"}},{"pos":"VERB 动词","cn":"（用手指）指","en":"If you point at a person or thing, you hold out your finger towards them in order to make someone notice them.","ex":{"en":"I pointed at the boy sitting nearest me","cn":"我指了指坐得离我最近的男孩。"}},{"pos":"VERB 动词","cn":"把…对准；使朝向","en":"If you point something at someone, you aim the tip or end of it towards them.","ex":{"en":"David Khan pointed his finger at Mary","cn":"戴维·卡恩用手指指着玛丽。"}},{"pos":"VERB 动词","cn":"指向；朝向","en":"If something points to a place or points in a particular direction, it shows where that place is or it faces in that direction.","ex":{"en":"An arrow pointed to the toilets","cn":"箭头指向卫生间。"}},{"pos":"VERB 动词","cn":"显示；表明","en":"If something points to a particular situation, it suggests that the situation exists or is likely to occur.","ex":{"en":"Earlier reports pointed to pupils working harder, more continuously, and with enthusiasm","cn":"早些时候的报告显示学生学习更为刻苦、持久，并且怀有学习热情。"}},{"pos":"VERB 动词","cn":"着重指出；强调；以…为证明","en":"If you point to something that has happened or that is happening, you are using it as proof that a particular situation exists.","ex":{"en":"George Fodor points to other weaknesses in the way the campaign has progressed","cn":"乔治·福多尔以运动开展过程中的其他不足为证。"}},{"pos":"VERB 动词","cn":"（用水泥等）勾嵌（砖或石墙的砌缝）","en":"When builders point a wall, they put a substance such as cement into the gaps between the bricks or stones in order to make the wall stronger and seal it."},{"pos":"PHRASE 短语","cn":"离题的；不相关的","en":"If you say that something is beside the point, you mean that it is not relevant to the subject that you are discussing.","ex":{"en":"Brian didn't like it, but that was beside the point.","cn":"布赖恩不喜欢它，但那并不重要。"}},{"pos":"PHRASE 短语","cn":"谈到正题；讲到关键问题","en":"When someone comes to the point or gets to the point, they start talking about the thing that is most important to them.","ex":{"en":"He came to the point at once. 'You did a splendid job on this case.'","cn":"他立刻切入正题道：“这件案子你处理得很棒。”"}},{"pos":"PHRASE 短语","cn":"证明自己的论点","en":"If you make your point or prove your point, you prove that something is true, either by arguing about it or by your actions or behaviour.","ex":{"en":"I think you've made your point, dear","cn":"亲爱的，我想你已证明你的观点了。"}},{"pos":"PHRASE 短语","cn":"特意；故意","en":"If you make a point of doing something, you do it in a very deliberate or obvious way.","ex":{"en":"She made a point of spending as much time as possible away from Osborne House.","cn":"她特意尽可能地不呆在奥斯本庄园。"}},{"pos":"PHRASE 短语","cn":"正要…之际；就要…之时","en":"If you are on the point of doing something, you are about to do it.","ex":{"en":"He was on the point of saying something when the phone rang","cn":"他正要说话时电话铃响了。"}},{"pos":"PHRASE 短语","cn":"切题的；中肯的","en":"Something that is to the point is relevant to the subject that you are discussing, or expressed neatly without wasting words or time.","ex":{"en":"Mr. Baker was smiling and to the point","cn":"贝克先生微笑着，说得很中肯。"}},{"pos":"PHRASE 短语","cn":"有一点；在一定程度上","en":"If you say that something is true up to a point, you mean that it is partly but not completely true.","ex":{"en":"'Was she good?' — 'Mmm. Up to a point.'","cn":"“她行不行？”——“嗯，某种程度上来说还可以。”"}},{"pos":"","cn":"","en":"a case in point→see: ; in point of fact→see: ; to point the finger at someone→see: ; a sore point→see: ;"},{"pos":"","cn":"","en":"相关词组：point out"}]},"examples":[{"en":"I couldn't do the job — I've never been to Spain and, more to the point, I don't speak Spanish.","cn":"这个工作我做不了 — 我从未去过西班牙；而更重要的是，我不会说西班牙语。"},{"en":"The climber was at/on the point of death when they found him.","cn":"当他们发现那个登山者的时候，他已奄奄一息。"}]},"poring":{"lemma":"pore"},"policemen":{"lemma":"policeman"},"portrays":{"lemma":"portray"},"points":{"lemma":"point"},"positioned":{"lemma":"position"},"populated":{"oxford":{"phon":"ˈpɒpjuleɪt","pos":"verb","senses":[{"en":"to live in an area and form its population","cn":"居住于；生活于；构成 … 的人口"},{"en":"to move people or animals to an area to live there","cn":"迁移；移居；殖民于"}]}},"poorest":{"lemma":"poor"},"polled":{"lemma":"poll"},"possessions":{"lemma":"possession"},"powers":{"lemma":"power"},"poplars":{"oxford":{"phon":"ˈpɒplə(r)","pos":"noun","senses":[{"en":"a tall straight tree with soft wood","cn":"杨，杨树（树干高，木质较软）"}]}},"postgraduates":{"oxford":{"phon":"ˌpəʊstˈɡrædʒuət","pos":"noun","senses":[{"en":"a person who already holds a first degree and who is doing advanced study or research; a graduate student","cn":"研究生"}]}},"powders":{"lemma":"powder"},"polishing":{"lemma":"polish","media":{"uk":"media/ldoce/hwd/bre/2/polish_n0205.mp3","us":"media/ldoce/hwd/ame/9/polish1.mp3","img":["media/ldoce/img/polish.jpg"]}},"posted":{"lemma":"post"},"policies":{"lemma":"policy"},"pockets":{"lemma":"pocket"},"pounds":{"lemma":"pound"},"pondering":{"lemma":"ponder"},"popularised":{"oxford":{"phon":"ˈpɒpjələraɪz","pos":"verb","senses":[{"en":"to make a lot of people know about sth and enjoy it","cn":"宣传；宣扬；推广"},{"en":"to make a difficult subject easier to understand for ordinary people","cn":"使通俗化；使普及"}]}},"pored":{"lemma":"pore"},"potteries":{"lemma":"pottery","media":{"uk":"media/ldoce/hwd/bre/2/p028-000009925.mp3","us":"media/ldoce/hwd/ame/0/lpd_potteries.mp3"}},"pollutants":{"lemma":"pollutant"},"portray":{"collins":{"senses":[{"pos":"VERB 动词","cn":"扮演；饰演","en":"When an actor or actress portrays someone, he or she plays that person in a play or film.","ex":{"en":"In 1975 he portrayed the king in a Los Angeles revival of 'Camelot'.","cn":"他1975年在洛杉矶重新上演的剧目《卡米洛》中扮演国王。"}},{"pos":"VERB 动词","cn":"描绘；描述","en":"When a writer or artist portrays something, he or she writes a description or produces a painting of it.","ex":{"en":"...this northern novelist, who accurately portrays provincial domestic life.","cn":"这位准确描述外省家庭生活的北方小说家"}},{"pos":"VERB 动词","cn":"表现；刻画","en":"If a film, book, or television programme portrays someone in a certain way, it represents them in that way.","ex":{"en":"She says the programme portrayed her as a 'lady of easy virtue'.","cn":"她说这个节目把她刻画成了一个“水性杨花的女人”。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to talk or write about a person, place, event etc, in order to show what they are like","cn":""},{"en":"to describe someone or something to someone. This phrase is more commonly used than describe in everyday spoken English","cn":""},{"en":"to describe someone or something in a piece of writing","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you paint a picture of someone, either in words or in paint, you portray them. Actors portray characters too."}]},"collocations":{"phrases":["ADV. accurately | clearly | dramatically, graphically, vividly an incident that graphically portrays the dangers associated with this sport ","VERB + PORTRAY attempt to, try to","PREP. as trying to portray themselves as the victims"]},"media":{"uk":"media/ldoce/hwd/bre/b/portray0205.mp3","us":"media/ldoce/hwd/ame/d/portray.mp3"},"examples":[{"en":"Throughout the trial, he portrayed himself as the victim.","cn":"在审讯过程中，他始终把自己说成是受害者。"},{"en":"Her father will be portrayed by Sean Connery.","cn":"肖恩 · 康纳利将饰演她的父亲。"}],"oxford":{"phon":"pɔːˈtreɪ","pos":"verb","senses":[{"en":"to show somebody/something in a picture; to describe somebody/something in a piece of writing","cn":"描绘；描画；描写","ex":{"en":"The painting portrays the duke’s third wife.","cn":"这幅画画的是公爵的第三位妻子。"}},{"en":"to describe or show somebody/something in a particular way, especially when this does not give a complete or accurate impression of what they are like","cn":"将…描写成；给人以某种印象；表现","ex":{"en":"Throughout the trial, he portrayed himself as the victim.","cn":"在审讯过程中，他始终把自己说成是受害者。"}},{"en":"to act a particular role in a film or play","cn":"扮演；饰演","ex":{"en":"Her father will be portrayed by Jim Broadbent.","cn":"她的父亲将由吉姆·布罗德本特饰演。"}}]}},"potent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很有效的；强有力的","en":"Something that is potent is very effective and powerful.","ex":{"en":"Their most potent weapon was the Exocet missile","cn":"飞鱼导弹是他们最有攻击力的武器。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a medicine, treatment etc is effective , it achieves the result that you want","cn":""},{"en":"if a medicine, treatment etc works , it has the effect that you want it to have","cn":""},{"en":"a medicine or drug that is powerful or potent is very strong and works very quickly so that it should be used very carefully","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Potent means really strong, but not like a body builder. Use potent instead to describe things like intense smells, powerful magic potions, and very influential people."}]},"collocations":{"phrases":["VERBS be | become","ADV. extremely, highly, particularly, very | pretty, quite The vodka must have been pretty potent stuff."]},"media":{"uk":"media/ldoce/hwd/bre/f/potent0205.mp3","us":"media/ldoce/hwd/ame/e/potent.mp3"},"examples":[{"en":"a very potent alcoholic brew","cn":"烈性酒精饮料"},{"en":"a potent argument","cn":"有力的论据"}],"oxford":{"phon":"ˈpəʊtnt","pos":"adjective","senses":[{"en":"having a strong effect on your body or mind","cn":"有强效的；有力的；烈性的；影响身心的","ex":{"en":"a potent drug","cn":"猛药"}},{"en":"powerful","cn":"强大的；强有力的","ex":{"en":"a potent force","cn":"强大的力量"}}]}},"pond":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"池塘；水塘","en":"A pond is a small area of water that is smaller than a lake. Ponds are often made artificially.","ex":{"en":"She chose a bench beside the duck pond and sat down.","cn":"她在鸭塘边找了条长椅坐下。"}},{"pos":"N-SING 单数名词","cn":"大西洋","en":"People sometimes refer to the Atlantic Ocean as the pond .","ex":{"en":"Usually, the presentation is made on the other side of the pond","cn":"通常，这样的展示是在大西洋另一边进行的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an area of short grass in a garden","cn":""},{"en":"an area of ground where you grow flowers","cn":""},{"en":"an area of a garden where there are rocks with small flowers growing between them","cn":""}]},"collocations":{"phrases":["ADJ. big, large | little, small | stagnant | muddy | ornamental | garden, village | duck, fish, lily","VERB + POND build, construct, dig | fill | drain, empty The pond is drained every year.","POND + NOUN life, water","PREP. across a/the ~ She swam across the pond. | in a/the ~ There are goldfish in the pond. | into a/the ~ Her sunglasses had fallen into th","PHRASES the bottom/edge/middle/side/surface of a pond The dog raced around to the other side of the pond."]},"media":{"img":["media/ldoce/img/pond.jpg"],"uk":"media/ldoce/hwd/bre/3/pond0205.mp3","us":"media/ldoce/hwd/ame/3/pond.mp3"},"examples":[{"en":"a fish pond","cn":"养鱼池"},{"en":"my cousins from across the pond","cn":"我那从大西洋彼岸来的同辈表亲"}],"oxford":{"phon":"pɒnd","pos":"noun","senses":[{"en":"a small area of still water, especially one that is artificial","cn":"池塘，水池（尤指人工的）","ex":{"en":"a fish pond","cn":"养鱼池"}},{"en":"the Atlantic Ocean","cn":"大西洋","lab":"informal, humorous，，","ex":{"en":"He's relatively unknown on this side of the pond.","cn":"他在大西洋这一侧不是那么出名。"}}]}},"postman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"邮差；邮递员","en":"A postman is a man whose job is to collect and deliver letters and packages that are sent by post."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to collect and deliver letters","cn":"邮递员﹐邮差"}]},"collocations":{"phrases":["ADJ. local, village","POSTMAN + VERB deliver sth • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/2/postman0205.mp3","us":"media/ldoce/hwd/ame/2/postman.mp3"},"oxford":{"phon":"ˈpəʊstmən","pos":"noun","senses":[{"en":"a man whose job is to collect and deliver letters, etc.","cn":"邮递员；邮差","lab":"British English"}]}},"potty":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（幼儿的）便盆","en":"A potty is a deep bowl which a small child uses instead of a toilet."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"疯狂的；愚蠢的","en":"If you say that someone is potty, you think that they are crazy or foolish."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"crazy or silly","cn":"发疯的﹔愚蠢的"},{"en":"if something or someone is driving you potty, they are annoying you, especially if they are making it difficult for you to continue what you are doing","cn":"使某人发疯"},{"en":"to like someone very much, or be very interested in something","cn":"对某人/某事物着迷"}]},"collocations":{"phrases":["VERB + POTTY use | sit (sb) on","POTTY + NOUN training","PREP. on the ~"]},"media":{"img":["media/ldoce/img/potty.jpg"],"uk":"media/ldoce/hwd/bre/8/potty_adj0205.mp3","us":"media/ldoce/hwd/ame/6/ld41potty.mp3"},"examples":[{"en":"The kids are driving me potty!","cn":"这群小崽子烦死我了！"},{"en":"What a potty idea!","cn":"多么愚蠢的主意！"}],"oxford":{"phon":"ˈpɒti","pos":"adjective","senses":[{"en":"crazy","cn":"疯狂的；发疯的","ex":{"en":"The kids are driving me potty!","cn":"这群小崽子烦死我了！"}},{"en":"liking somebody/something a lot","cn":"喜爱；对…痴迷","ex":{"en":"She’s potty about you!","cn":"她对你很上心！"}},{"en":"a bowl that very young children use when they are too small to use a toilet","cn":"（幼儿的）便盆","pos":"noun"}]}},"poetic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"诗一般的；富有诗意的","en":"Something that is poetic is very beautiful and expresses emotions in a sensitive or moving way.","ex":{"en":"Nikolai Demidenko gave an exciting yet poetic performance.","cn":"尼古拉·杰米坚科的表演激动人心且富有诗意。"}},{"pos":"ADJ 形容词","cn":"诗的；诗歌的","en":"Poetic means relating to poetry.","ex":{"en":"There's a very rich poetic tradition in Gaelic.","cn":"盖尔语有非常深厚的诗歌传统。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to poetry, or typical of poetry","cn":"诗的﹔诗歌特有的"},{"en":"having qualities of deep feeling or graceful expression","cn":"富有诗意的﹔表达优雅的﹔诗一般的"}]},"vocab":{"pos":"adj","senses":[{"en":"Anything poetic either relates to the art of poetry or has the romantic images of poetry. A great speech can be poetic . An orange-red sunset at the beach, or a song in the moonlight can also be poetic ."}]},"collocations":{"phrases":["VERBS be, sound","ADV. very | truly The piece ends with a truly poetic slow movement. | almost | quite | self-consciously His writing is rather self-conscious"]},"media":{"uk":"media/ldoce/hwd/bre/3/poetic0205.mp3","us":"media/ldoce/hwd/ame/a/poetic.mp3"},"examples":[{"en":"There is a poetic quality to her playing.","cn":"她的演奏富有诗意。"},{"en":"poetic language","cn":"诗歌语言"}],"oxford":{"phon":"pəʊˈetɪk","pos":"adjective","senses":[{"en":"connected with poetry; being poetry","cn":"诗歌的；诗的","g":"[only before noun]","ex":{"en":"poetic language","cn":"诗歌语言"}},{"en":"like or suggesting poetry, especially because it shows imagination and deep feeling","cn":"像诗一般的；富有诗意的","lab":"approving","ex":{"en":"There is a poetic quality to her playing.","cn":"她的演奏富有诗意。"}}]}},"postcard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"明信片","en":"A postcard is a piece of thin card, often with a picture on one side, which you can write on and send to people without using an envelope."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a card that can be sent in the post without an envelope, especially one with a picture on it","cn":"明信片"}]},"collocations":{"phrases":["ADJ. picture | holiday","VERB + POSTCARD write I hate writing holiday postcards. | post, send (sb) | get, receive","POSTCARD + VERB arrive | depict sth, show sth","PREP. on a/the ~ Write your answers on a postcard. | ~ from, ~ of I sent my mum a postcard of the cathedral. | ~ to"]},"media":{"uk":"media/ldoce/hwd/bre/5/postcard0205.mp3","us":"media/ldoce/hwd/ame/b/postcard.mp3"},"examples":[{"en":"Send your answers on a postcard to the above address.","cn":"把答案写在明信片上，寄到上述地址。"},{"en":"Send us a postcard from Venice!","cn":"从威尼斯给我们寄张明信片来！"}],"oxford":{"phon":"ˈpəʊstkɑːd","pos":"noun","senses":[{"en":"a card used for sending messages by post without an envelope, especially one that has a picture on one side","cn":"明信片","ex":{"en":"colourful postcards of California","cn":"五颜六色的加利福尼亚州明信片"}}]}},"pointless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无益的；无意义的；无目的的","en":"If you say that something is pointless, you are criticizing it because it has no sense or purpose.","ex":{"en":"Violence is always pointless","cn":"暴力总是毫无意义的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not likely to have a useful result","cn":""},{"en":"completely pointless because there is no chance at all of being successful","cn":""},{"en":"not useful or effective in any way","cn":""}]},"collocations":{"phrases":["VERBS be, seem | become | consider sth, think sth She considered it pointless to plan in too much detail.","ADV. absolutely, quite, totally, utterly | a bit, fairly, rather, somewhat | apparently"]},"media":{"uk":"media/ldoce/hwd/bre/8/pointless0205.mp3","us":"media/ldoce/hwd/ame/1/pointless.mp3"},"examples":[{"en":"We searched until we knew it would be pointless to continue.","cn":"我们搜索又搜索，直到觉得继续下去也枉然时才罢手。"},{"en":"He argued pointlessly with his parents.","cn":"他无谓地和父母争论。"}],"oxford":{"phon":"ˈpɔɪntləs","pos":"adjective","senses":[{"en":"having no purpose; not worth doing","cn":"无意义的；无目标的；不值得做的","ex":{"en":"We searched until we knew it would be pointless to continue.","cn":"我们搜索又搜索，直到觉得继续下去也枉然时才罢手。"}}]}},"polio":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"脊髓灰质炎；小儿麻痹症","en":"Polio is a serious infectious disease which often makes people unable to use their legs.","ex":{"en":"Gladys was crippled by polio at the age of 3.","cn":"格拉迪丝3岁时因小儿麻痹症腿瘸了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a serious infectious disease of the nerves in the spine , that often results in someone being permanently unable to move particular muscles","cn":"脊髓灰质炎﹐小儿麻痹症"}]},"collocations":{"phrases":["VERB + POLIO have | contract | immunize sb against, vaccinate sb against","POLIO + NOUN vaccination, vaccine | virus | victim •"]},"media":{"uk":"media/ldoce/hwd/bre/0/polio0205.mp3","us":"media/ldoce/hwd/ame/4/laadpolio.mp3"},"oxford":{"phon":"ˈpəʊliəʊ","pos":"noun","senses":[{"en":"a disease that affects the central nervous system and can cause temporary or permanent paralysis (= loss of control or feeling in part or most of the body)","cn":"脊髓灰质炎；小儿麻痹症"}]}},"poultry":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"家禽","en":"You can refer to chickens, ducks, and other birds that are kept for their eggs and meat as poultry .","ex":{"en":"Dr Binger keeps poultry, pigs and goats","cn":"班热博士饲养家禽、猪和羊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"birds such as chickens and ducks that are kept on farms in order to produce eggs and meat","cn":"家禽"},{"en":"meat from birds such as chickens and ducks","cn":"家禽肉"}]},"collocations":{"phrases":["ADJ. free-range","VERB + POULTRY keep, rear He rears rabbits and poultry in the garden.","POULTRY + NOUN farming, industry | dish a wine that goes well with fish and poultry dishes"]},"media":{"uk":"media/ldoce/hwd/bre/e/poultry0205.mp3","us":"media/ldoce/hwd/ame/7/poultry.mp3"},"examples":[{"en":"Eat plenty of fish and poultry.","cn":"要多吃鱼和禽肉。"},{"en":"to keep poultry","cn":"饲养家禽"}],"oxford":{"phon":"ˈpəʊltri","pos":"noun","senses":[{"en":"chickens, ducks and geese, kept for their meat or eggs","cn":"家禽","g":"[plural]","ex":{"en":"to keep poultry","cn":"饲养家禽"}},{"en":"meat from chickens, ducks and geese","cn":"禽肉","g":"[uncountable]","ex":{"en":"Eat plenty of fish and poultry.","cn":"要多吃鱼和禽肉。"}}]}},"pointer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"建议；点子；提示","en":"A pointer is a piece of advice or information which helps you to understand a situation or to find a way of making progress.","ex":{"en":"I hope at least my daughter was able to offer you some useful pointers","cn":"我希望至少我的女儿为你提供了一些有用的建议。"}},{"pos":"N-COUNT 可数名词","cn":"暗示；线索；迹象","en":"A pointer to something suggests that it exists or gives an idea of what it is like.","ex":{"en":"His victory in the first race here on Tuesday was a timely pointer to his chance of remaining unbeaten","cn":"周二他在这里取得的第一轮比赛胜利是个及时的信号，说明他可能保持不败。"}},{"pos":"N-COUNT 可数名词","cn":"指示棒；教鞭","en":"A pointer is a long stick that is used to point at something such as a large chart or diagram when explaining something to people.","ex":{"en":"She tapped on the world map with her pointer.","cn":"她用教鞭敲了敲世界地图。"}},{"pos":"N-COUNT 可数名词","cn":"（测量仪器上的）指针","en":"The pointer on a measuring instrument is the long, thin piece of metal that points to the numbers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a useful piece of advice or information that helps you to do or understand something","cn":"提示﹔忠告﹔点子"},{"en":"something that shows how a situation is developing, or is a sign of what might happen in the future","cn":"迹象﹔线索﹔暗示"},{"en":"the small symbol, usually an arrow , that you move using a computer’s mouse to point to the place on the screen where you want to work, start a program etc","cn":"指针﹐光标"}]},"collocations":{"phrases":["ADJ. good, important | clear, obvious | practical, useful","VERB + POINTER give (sb), provide (sb with)","PREP. ~ for The examiners comments include pointers for future study. | ~ to His symptoms gave no obvious pointer to a possible diagnosis. |","PHRASES a pointer to the future 2 sth used for pointing","ADJ. mouse Move the mouse pointer to the menu bar. | light A light pointer is often useful with a slide projector."]},"media":{"uk":"media/ldoce/hwd/bre/4/pointer0205.mp3","us":"media/ldoce/hwd/ame/a/pointer.mp3"},"examples":[{"en":"The surge in car sales was regarded as an encouraging pointer to an improvement in the economy.","cn":"汽车销售量的激增被视为经济回升的指标。"},{"en":"Here are some pointers on how to go about the writing task.","cn":"关于这项写作任务，以下有几点建议。"}],"oxford":{"phon":"ˈpɔɪntə(r)","pos":"noun","senses":[{"en":"a piece of advice","cn":"提示；建议","lab":"informal","ex":{"en":"Here are some pointers on how to go about the writing task.","cn":"关于这项写作任务，有以下几点建议。"}},{"en":"a sign that something exists; a sign that shows how something may develop in the future","cn":"标志；迹象；兆头；动向","ex":{"en":"The surge in car sales was regarded as an encouraging pointer to an improvement in the economy.","cn":"汽车销售量的激增被视为经济回升的标志。"}},{"en":"a thin piece of metal that points to the numbers on a dial on a piece of equipment for measuring something","cn":"（刻度盘的）指针"},{"en":"a stick used to point to things on a map or picture on a wall","cn":"指示杆"},{"en":"a small symbol, for example an arrow, that marks a point on a computer screen","cn":"指针（光标）","lab":"computing","ex":{"en":"Move the mouse pointer to the menu bar.","cn":"将鼠标光标移到菜单栏。"}},{"en":"a large dog used in hunting, trained to stand still with its nose pointing towards the birds that are being hunted","cn":"指示猎狗，指示犬（经训练用以指示猎物等）"}]}},"portrayal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（角色的）扮演，刻画，演绎","en":"An actor's portrayal of a character in a play or film is the way that he or she plays the character.","ex":{"en":"Mr Ying is well-known for his portrayal of a prison guard in the film 'The Last Emperor'.","cn":"英先生因其在电影《末代皇帝》中塑造的监狱看守形象而闻名。"}},{"pos":"N-COUNT 可数名词","cn":"绘画；油画；照片","en":"An artist's portrayal of something is a drawing, painting, or photograph of it.","ex":{"en":"'Scene with a Winding River' (1827) is a near-monochrome portrayal of a wood infused with silvery light.","cn":"《有弯弯河流的风景》（1827年）是一幅近乎单色调的绘画，描绘的是沐浴在银色光线里的一片树林。"}},{"pos":"N-COUNT 可数名词","cn":"描述；描写；刻画","en":"The portrayal of something in a book or film is the act of describing it or showing it.","ex":{"en":"This is a sensitive and often funny portrayal of a friendship between two 11-year-old boys.","cn":"这是对两个11岁小男孩之间的友谊所作的细腻而不乏风趣的描述。"}},{"pos":"N-COUNT 可数名词","cn":"描写；呈现；表现","en":"The portrayal of something in a book, film, or programme is the way that it is made to appear.","ex":{"en":"The media persists in its portrayal of us as muggers, dope sellers and gangsters","cn":"媒体一直把我们描绘成抢劫犯、贩毒者和歹徒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"what you say or write when you are describing a person, place, or thing","cn":""},{"en":"a description of a situation or event, based on a study of the facts, that provides people with information about it and also tries to explain it","cn":""},{"en":"a written or spoken description of something that happened","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you like the way an actor played the role of Abraham Lincoln, you might praise his portrayal of the sixteenth president."}]},"collocations":{"phrases":["ADJ. accurate, realistic, vivid | moving, poignant | chilling, frightening He is best remembered for his chilling portrayal of Norman Bates ","PREP. in the/its, etc. ~ She shows a full range of emotions in her portrayal of an ambitious politician. | ~ of His novel is a vivid portray"]},"media":{"uk":"media/ldoce/hwd/bre/5/portrayal0205.mp3","us":"media/ldoce/hwd/ame/a/laadportrayal.mp3"},"examples":[{"en":"He is best known for his chilling portrayal of Hannibal Lecter.","cn":"他以饰演令人毛骨悚然的汉尼拔 · 莱克特而著称。"},{"en":"The article examines the portrayal of gay men in the media.","cn":"这篇文章剖析了传媒对男同性恋者的描述。"}],"oxford":{"phon":"pɔːˈtreɪəl","pos":"noun","senses":[{"en":"the act of showing or describing somebody/something in a picture, play, book, etc.; a particular way in which this is done","cn":"描绘；描述；描写；展现方式","ex":{"en":"The article examines the portrayal of gay men in the media.","cn":"这篇文章剖析了传媒对男同性恋者的描述。"}}]}},"pout":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（恼怒或性感地）撅嘴","en":"If someone pouts, they stick out their lips, usually in order to show that they are annoyed or to make themselves sexually attractive.","ex":{"en":"He whined and pouted when he did not get what he wanted.","cn":"他要是没得到想要的东西就会发牢骚、撅嘴。"}},{"pos":"VERB 动词","cn":"撅着嘴说","en":"If someone pouts, they say something with a pout.","ex":{"en":"'You're no fun,' she pouted.","cn":"她撅着嘴说：“你一点都不风趣。”"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to push out your lower lip because you are annoyed or unhappy, or in order to look sexually attractive","cn":"噘起（嘴唇）﹐噘嘴〔因不高兴或为显得性感〕"}]},"vocab":{"pos":"1 v n 2 n","senses":[{"en":"When something doesn’t go your way and you get annoyed about it, that’s a pout . And when you let the world know about it by thrusting out your lower lip, you are pouting . Get over it."}]},"collocations":{"phrases":["ADV. slightly | prettily, sulkily Her lips pouted sulkily.","PREP. at She pouted prettily at him."]},"media":{"uk":"media/ldoce/hwd/bre/5/pout0205.mp3","us":"media/ldoce/hwd/ame/8/pout1.mp3"},"examples":[{"en":"Her lips were set in a pout of annoyance.","cn":"她愠恼地撅起了双唇。"},{"en":"Her lips pouted invitingly.","cn":"她挑逗地撮起双唇。"}],"oxford":{"phon":"paʊt","pos":"verb","senses":[{"en":"if you pout, pout your lips or if your lips pout, you push out your lips, to show you are annoyed or to look sexually attractive","cn":"（恼怒或性感地）噘嘴","ex":{"en":"He pouted angrily.","cn":"他生气地噘起嘴。"}},{"en":"an expression on your face in which your lips are pushed out to show you are annoyed or to look sexually attractive","cn":"（恼怒或性感地）噘嘴","ex":{"en":"Her lips were set in a pout of annoyance.","cn":"她生气地嘟着嘴巴。"},"pos":"noun"}]}},"pony":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"矮种马；小型马","en":"A pony is a type of small horse."},{"pos":"","cn":"","en":"相关词组：pony up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small horse","cn":"矮种马﹐小型马"},{"en":"to find or produce a particular amount of money","cn":"搞到﹔支付；付（钱）"}]},"collocations":{"phrases":["VERB + PONY pit Pit ponies were used in most mines at the turn of the last century. | polo | wild","VERB + PONY ride | lead | brush down | saddle | shoe","PONY + VERB neigh, whinny | canter, gallop, trot, walk | prance | jump","PONY + NOUN club | ride | riding, trekking","PHRASES a pony and cart/trap"]},"media":{"uk":"media/ldoce/hwd/bre/0/pony_las2_br.mp3","us":"media/ldoce/hwd/ame/c/pony.mp3"},"examples":[{"en":"Each guest had to pony up $40 for the meal.","cn":"每位来宾都得为这顿饭付 40 元。"},{"en":"All investors had to pony up a minimum of $5000.","cn":"各投资者必须最少出资5,000美元。"}],"oxford":{"phon":"ˈpəʊni","pos":"noun","senses":[{"en":"a type of small horse","cn":"小型马；矮马"},{"en":"£25","cn":"25 英镑","lab":"British English, slang，，"}]}},"portugal":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in southwest Europe, west of Spain, which is a member of the EU (European Union). Population: 10,799,270 (2014). Capital: Lisbon. Portugal's traditional industries include fishing and wine, and its more modern industries include clothing and car part","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/p028-000009903.mp3","us":"media/ldoce/hwd/ame/4/p028-000009903.mp3"},"oxford":{"phon":"ˈpɔːtʃʊɡl","pos":"noun","senses":[{"en":"a country in south-western Europe","cn":"葡萄牙（西南欧国家）"}]}},"portrait":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"肖像；画像","en":"A portrait is a painting, drawing, or photograph of a particular person.","ex":{"en":"Lucian Freud has been asked to paint a portrait of the Queen.","cn":"卢西恩·弗洛伊德已受邀为女王画肖像画。"}},{"pos":"N-COUNT 可数名词","cn":"描绘；描写；描述","en":"A portrait of a person, place, or thing is a verbal description of them.","ex":{"en":"...this gripping, funny portrait of Jewish life in 1950s London.","cn":"这段扣人心弦、令人捧腹的对伦敦20世纪50年代犹太人生活的描写"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"shapes, lines etc painted or drawn on a surface, especially as a piece of art, and often showing what someone or something looks like","cn":""},{"en":"a picture drawn with a pencil, pen etc","cn":""},{"en":"a picture that is drawn quickly","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A portrait is a portrayal of a person, usually showing the person's face (but not always). A portrait can be a painting, a photograph, an ink drawing, a sculpture — or even a description in words or in a film."}]},"collocations":{"phrases":["ADJ. full-length, half-length, head and shoulders | oil, pastel, pencil, etc. | photographic, sculptural | equestrian, family, group, royal ","VERB + PORTRAIT do, paint, photograph | sit for | commission | write | display, exhibit, show","PORTRAIT + VERB hang Ancient family portraits hung on the walls of the staircase.","PORTRAIT + NOUN gallery | artist, painter, photographer sitting to a fashionable portrait painter","PREP. ~ by, ~ of a portrait of the Queen by Annigoni • Note at ART"]},"media":{"img":["media/ldoce/img/portrait.jpg"],"uk":"media/ldoce/hwd/bre/6/portrait_n0205.mp3","us":"media/ldoce/hwd/ame/7/portrait.mp3"},"examples":[{"en":"He had his portrait painted in uniform.","cn":"他让人画了一幅身着制服的画像。"},{"en":"a portrait of life at the French court","cn":"对法国宫廷生活的详细描述"}],"oxford":{"phon":"ˈpɔːtreɪt","pos":"noun","senses":[{"en":"a painting, drawing or photograph of a person, especially of the head and shoulders","cn":"肖像；半身画像；半身照","lab":"US English","ex":{"en":"a portrait of his wife","cn":"他妻子的肖像"}},{"en":"a detailed description of somebody/something","cn":"详细的描述；描绘","ex":{"en":"a portrait of life at the French court","cn":"对法国宫廷生活的详细描述"}},{"en":"the way of printing a document in which the top of the page is one of the shorter sides","cn":"纵向打印","ex":{"en":"You can print landscape and portrait pages in the same document.","cn":"您可以在同一文档中打印横向和纵向页面。"}}]}},"postponement":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"推迟；延期；延缓","en":"The postponement of an event is the act of delaying it happening or arranging for it to take place at a later time than originally planned.","ex":{"en":"The postponement was due to a dispute over where the talks should be held.","cn":"会谈推迟是因为对会谈地点存在争议。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change the date or time of a planned event or action to a later one","cn":""},{"en":"to decide to do something later than you planned to do it or later than you should do it, especially because there is a problem or because you do not want to do it now","cn":""},{"en":"to not do something until something else has happened or until a more suitable time","cn":""}]},"collocations":{"phrases":["ADJ. further, repeated | indefinite","VERB + POSTPONEMENT ask for, call for, request, seek They are calling for a further postponement of the election date. | announce | force, r","PREP. ~ until The death of one of the candidates forced postponement of the voting until 1 June."]},"media":{"uk":"media/ldoce/hwd/bre/3/postpone0205.mp3","us":"media/ldoce/hwd/ame/c/postpone.mp3"},"examples":[{"en":"Riots led to the postponement of local elections.","cn":"骚乱致使地方选举延期了。"},{"en":"The match had to be postponed until next week.","cn":""}],"oxford":{"phon":"pəˈspəʊnmənt","pos":"noun","senses":[{"en":"a change to the date or time of an event so that it will take place later than originally planned","cn":"延后，延缓，延期","ex":{"en":"Riots led to the postponement of local elections.","cn":"骚乱致使地方选举延期了。"}}]}},"pore":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（皮肤上的）毛孔","en":"Your pores are the tiny holes in your skin.","ex":{"en":"The size of your pores is determined by the amount of oil they produce.","cn":"毛孔大小取决于其出油多少。"}},{"pos":"N-COUNT 可数名词","cn":"（植物表面的）气孔","en":"The pores of a plant are the tiny holes on its surface.","ex":{"en":"A plant's lungs are the microscopic pores in its leaves.","cn":"植物的肺就是其叶片上微细的气孔。"}},{"pos":"VERB 动词","cn":"仔细阅读；认真钻研","en":"If you pore over or through information, you look at it and study it very carefully.","ex":{"en":"We spent hours poring over travel brochures","cn":"我们花了数小时仔细阅读旅游宣传册。"}},{"pos":"PHRASE 短语","cn":"极度；非常","en":"You can say that someone has a certain quality or emotion coming from every pore to emphasize the strength of that quality or emotion.","ex":{"en":"She oozes sexuality from every pore","cn":"她浑身上下每个毛孔都散发着性感。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the small holes in your skin that liquid, especially sweat , can pass through, or a similar hole in the surface of a plant 〔","cn":"皮肤的〕毛孔﹔〔植物表面的〕气孔﹐细孔"},{"en":"to read something carefully especially in order to check every detail or find any mistakes","cn":""},{"en":"to read something for a long time, very carefully, and with great interest","cn":""}]},"vocab":{"pos":"1 n 2 v","senses":[{"en":"That trickle of sweat didn't just miraculously appear — it was secreted out of a pore , a really tiny opening on the surface of your skin."}]},"collocations":{"phrases":["ADJ. blocked | open","VERB + PORE block | unblock | open A hot bath opens the pores. | close"]},"media":{"uk":"media/ldoce/hwd/bre/8/pore_v0205.mp3","us":"media/ldoce/hwd/ame/e/poor.mp3"},"examples":[{"en":"His lawyers are poring over the small print in the contract.","cn":"他的律师们正在审阅合同上的小号字。"},{"en":"She was poring over a book.","cn":"她在专心阅读一本书。"}],"oxford":{"phon":"pɔː(r)","pos":"noun","senses":[{"en":"one of the very small holes in your skin that sweat can pass through; one of the similar small holes in the surface of a plant or a rock","cn":"（皮肤上的）毛孔；（植物的）气孔；孔隙"}]}},"post-mortem":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"验尸；尸体检验；尸体解剖","en":"A post-mortem is a medical examination of a dead person's body in order to find out how they died."},{"pos":"N-COUNT 可数名词","cn":"（尤指对失败或出差错的事情的）事后分析；事后检讨","en":"A post-mortem is an examination of something that has recently happened, especially something that has failed or gone wrong.","ex":{"en":"The postmortem on the presidential campaign is under way.","cn":"正在对总统竞选活动进行反思。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a doctor examines someone's body to find out if there is anything wrong with them","cn":""},{"en":"a thorough examination of someone's body and general health by a doctor, especially to decide whether they are fit to do a particular job","cn":""},{"en":"a medical examination to make sure that someone is healthy - especially one that is done regularly","cn":""}]},"collocations":{"phrases":["PREP. ~ on They're doing a post-mortem on her today."]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdepost-mortem.mp3","us":"media/ldoce/hwd/ame/4/laadpost-mortem.mp3"},"examples":[{"en":"The post-mortem on the child revealed that she had been poisoned.","cn":"验尸证明这孩子是被人毒死的。"},{"en":"to hold a post-mortem on the party's election defeat","cn":"对该党竞选失败进行检讨"}],"oxford":{"phon":"ˌpəʊst ˈmɔːtəm","pos":"noun","senses":[{"en":"a medical examination of the body of a dead person in order to find out how they died","cn":"验尸；尸体解剖","ex":{"en":"to do/conduct/carry out a post-mortem","cn":"进行剖尸验证"}},{"en":"a discussion or an examination of an event after it has happened, especially in order to find out why it failed","cn":"事后反思（或剖析）","ex":{"en":"to hold a post-mortem on the party’s election defeat","cn":"对该党竞选失败进行检讨"}}]}},"postage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"邮资；邮费","en":"Postage is the money that you pay for sending letters and packages by post."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the money charged for sending a letter, package etc by post","cn":"邮资﹐邮费"}]},"collocations":{"phrases":["VERB + POSTAGE pay I had to pay &pound; 4 postage. | cover Add &pound; 3 to each order to cover postage. | include","POSTAGE + NOUN stamp | rates","PREP. for ~ It costs &pound; 60, plus &pound; 5 for postage. | in ~ Sending those books cost me a fortune in postage! | ~ on What's the post","PHRASES postage and packing All prices include postage and packing."]},"media":{"uk":"media/ldoce/hwd/bre/f/postage0205.mp3","us":"media/ldoce/hwd/ame/2/postage.mp3"},"examples":[{"en":"( BrE ) All prices include postage and packing.","cn":"所有的价格都包括邮资和包装费。"},{"en":"( NAmE ) All prices include postage and handling.","cn":"所有的价格都包括邮资和手续费。"}],"oxford":{"phon":"ˈpəʊstɪdʒ","pos":"noun","senses":[{"en":"the cost of sending a letter, etc. by post","cn":"邮资；邮费","lab":"British English","ex":{"en":"an increase in postage rates","cn":"邮费的增加"}}]}},"ponder":{"collins":{"senses":[{"pos":"VERB 动词","cn":"思索；考虑","en":"If you ponder something, you think about it carefully.","ex":{"en":"I found myself constantly pondering the question: 'How could anyone do these things?'","cn":"我发现自己总在思考这个问题：“怎么会有人做出这样的事情呢？”"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use your mind to decide about something, form an opinion, imagine something etc","cn":""},{"en":"to think about something carefully before deciding what to do","cn":""},{"en":"to carefully think about a plan or choice by comparing all the advantages and disadvantages involved","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"\"Once upon a midnight dreary, while I pondered , weak and weary\" is the first line of Edgar Allen Poe's poem The Raven . Many a deep thinker has repeated it while musing. But if you've given up deep thinking, you may say instead, \"Nevermore.\""}]},"collocations":{"phrases":["ADV. carefully, deeply, hard | (for) a moment She pondered for a moment before replying.","VERB + PONDER leave sb to He walked out of the room, leaving me to ponder what he had just said. | be forced to","PREP. about This was something I had been pondering about for some time. | on I walked up the stairs, pondering on her reaction to my news. "]},"media":{"uk":"media/ldoce/hwd/bre/f/ponder0205.mp3","us":"media/ldoce/hwd/ame/d/ponder.mp3"},"examples":[{"en":"They are pondering whether the money could be better used elsewhere.","cn":"他们正在斟酌能否把钱花到其他更适当的地方。"},{"en":"They were left to ponder on the implications of the announcement.","cn":"交由他们去琢磨这项宣告的含义。"}],"oxford":{"phon":"ˈpɒndə(r)","pos":"verb","senses":[{"en":"to think about something carefully for a period of time","cn":"沉思；考虑；琢磨","ex":{"en":"She pondered over his words.","cn":"她反复琢磨他的话。"}}]}},"poised":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（身体部位）摆好姿势不动的","en":"If a part of your body is poised, it is completely still but ready to move at any moment.","ex":{"en":"He studied the keyboard carefully, one finger poised.","cn":"他仔细研究了键盘，一个手指随时准备敲击。"}},{"pos":"ADJ 形容词","cn":"作好一切准备的；随时准备行动的","en":"If someone is poised to do something, they are ready to take action at any moment.","ex":{"en":"Britain was poised to fly medical staff to the country at short notice","cn":"英国随时准备把医护人员空运到该国。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"镇定的；沉着的；泰然自若的","en":"If you are poised, you are calm, dignified, and self-controlled.","ex":{"en":"She was self-assured, poised, almost self-satisfied","cn":"她自信、沉着，几乎有些洋洋自得。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not moving, but ready to move or do something at any moment 〔","cn":"摆好姿势〕准备行动的"},{"en":"completely ready to do something or for something to happen, when it is likely to happen soon","cn":"准备好的﹔蓄势待发的"},{"en":"to be in a position or situation in which two things have an equally strong influence","cn":"介于某事物和某事物之间的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you're poised you're self-possessed and in full control of your faculties. You're balanced, grounded, and ready for action."}]},"collocations":{"phrases":["VERBS appear, be, look, seem, stand She stood poised for a moment. | remain","ADV. delicately, finely | perfectly His manner was perfectly poised between gravity and teasing.","PREP. above/over Peter hesitated, his hand poised above the telephone. | between, for They hovered by the door, poised for flight.","PHRASES poised on the brink/edge/threshold of sth The two countries were poised on the brink of war."]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdepoised.mp3","us":"media/ldoce/hwd/ame/c/poised.mp3"},"examples":[{"en":"Kate is poised to become the highest-paid supermodel in the fashion world.","cn":"凯特决心成为时装界最高薪的超级模特儿。"},{"en":"The cup was poised on the edge of the chair.","cn":"杯子放在椅子边上（随时可能掉下来）。"}],"oxford":{"phon":"pɔɪzd","pos":"adjective","senses":[{"en":"in a position that is completely still but is ready to move at any moment","cn":"处于准备状态；蓄势待发","g":"[not before noun]","ex":{"en":"Tina was tense, her hand poised over the telephone.","cn":"蒂娜心情紧张，手悬在电话机上。"}},{"en":"in a position that is balanced but likely to change in one direction or another","cn":"（暂时）平衡，稳固","g":"[not before noun]","lab":"figurative","ex":{"en":"The cup was poised on the edge of the chair.","cn":"杯子放在椅子边上，不稳当。"}},{"en":"completely ready for something or to do something","cn":"有充分准备；准备好；蓄势待发","g":"[not before noun]","ex":{"en":"The economy is poised for recovery.","cn":"经济呈复苏之势。"}},{"en":"having a calm and confident manner and in control of your feelings and behaviour","cn":"泰然自若的；沉着自信的；稳健的","ex":{"en":"He is a remarkably poised young man.","cn":"他是个特别稳健的年轻人。"}}]},"base":"poise"},"postpone":{"collins":{"senses":[{"pos":"VERB 动词","cn":"推迟；使延期；延缓","en":"If you postpone an event, you delay it or arrange for it to take place at a later time than was originally planned. →see usage note at:","ex":{"en":"He decided to postpone the expedition until the following day","cn":"他决定把探险推迟到第二天。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change the date or time of a planned event or action to a later one","cn":"使〔事件﹑行动等〕延期﹐延迟﹐推迟"},{"en":"to decide to do something later than you planned to do it or later than you should do it, especially because there is a problem or because you do not want to do it now","cn":""},{"en":"to not do something until something else has happened or until a more suitable time","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To postpone something is to put it off till later. You can postpone an appointment today and reschedule it for tomorrow."}]},"collocations":{"phrases":["ADV. indefinitely The event has been postponed indefinitely due to lack of interest. | merely The inevitable conflict was merely postponed t","VERB + POSTPONE agree to, decide to, vote to | be forced to | ask sb to Ruth wrote at once, asking Maria to postpone her visit.","PREP. for Our visit had been postponed for several weeks. | from, to The match has been postponed from Wednesday night to Friday night. | ti"]},"media":{"uk":"media/ldoce/hwd/bre/3/postpone0205.mp3","us":"media/ldoce/hwd/ame/c/postpone.mp3"},"examples":[{"en":"We'll have to postpone the meeting until next week.","cn":"我们将不得不把会议推迟到下周举行。"},{"en":"It was an unpopular decision to postpone building the new hospital.","cn":"延迟兴建新医院的决定是不得人心的。"}],"oxford":{"phon":"pəˈspəʊn","pos":"verb","senses":[{"en":"to arrange for an event, etc. to take place at a later time or date than originally planned","cn":"推迟；延期","ex":{"en":"The game has already been postponed three times.","cn":"这场比赛已经三度延期了。"}}]}},"polythene":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"聚乙烯","en":"Polythene is a type of plastic made into thin sheets or bags and used especially to keep food fresh or to keep things dry.","ex":{"en":"Simply put them into a polythene bag and store them in the freezer for a day.","cn":"只需把它们装进保鲜袋，在冰箱里储存一天即可。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong light plastic used to make bags, sheets for covering food, small containers etc","cn":"聚乙烯"}]},"collocations":{"phrases":["ADJ. heavy-duty","VERB + POLYTHENE cover sth with, line sth with, wrap sth in","POLYTHENE + NOUN bag | sheeting"]},"media":{"uk":"media/ldoce/hwd/bre/a/polythene0205.mp3","us":"media/ldoce/hwd/ame/f/ld41polythene.mp3"},"examples":[{"en":"a polythene bag","cn":"聚乙烯袋"}],"oxford":{"phon":"ˈpɒlɪθiːn","pos":"noun","senses":[{"en":"a strong thin plastic material, used especially for making bags or for wrapping things in","cn":"聚乙烯","ex":{"en":"a polythene bag","cn":"聚乙烯袋"}}]}},"pottery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"陶器；陶瓷器皿","en":"You can use pottery to refer to pots, dishes, and other objects which are made from clay and then baked in an oven until they are hard."},{"pos":"N-UNCOUNT 不可数名词","cn":"陶土；黏土","en":"You can use pottery to refer to the hard clay that some pots, dishes, and other objects are made of.","ex":{"en":"Some bowls were made of pottery and wood.","cn":"一些碗是用陶土和木头制成的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"制陶手艺；陶艺；陶瓷制造","en":"Pottery is the craft or activity of making objects out of clay."},{"pos":"N-COUNT 可数名词","cn":"陶器工厂；陶器作坊；陶窑","en":"A pottery is a factory or other place where pottery is made."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"objects made out of baked clay","cn":"陶器"},{"en":"clay that has been shaped and baked in order to make pots, dishes etc","cn":"陶"},{"en":"the activity of making pots, dishes etc out of clay","cn":"制陶﹐陶艺"}]},"collocations":{"phrases":["ADJ. decorated, glazed, painted | hand-thrown | coarse, fine","QUANT. fragment, piece fragments of Iron Age pottery","VERB + POTTERY make, manufacture, produce | fire the kilns in which the pottery is fired","POTTERY + NOUN kiln • Note at ART"]},"media":{"uk":"media/ldoce/hwd/bre/0/pottery0205.mp3","us":"media/ldoce/hwd/ame/7/pottery.mp3","img":["media/thumb/pottery.jpg"]},"examples":[{"en":"a jug made of blue-glazed pottery","cn":"一把蓝釉陶壶"},{"en":"Roman pottery","cn":"罗马时期的陶器"}],"oxford":{"phon":"ˈpɒtəri","pos":"noun","senses":[{"en":"pots, dishes, etc. made with clay that are baked in an oven, especially when they are made by hand","cn":"陶器（尤指手工制的）","g":"[uncountable]","ex":{"en":"Roman pottery","cn":"罗马时期的陶器"}},{"en":"the clay that some dishes and pots are made of","cn":"陶土","g":"[uncountable]","ex":{"en":"a jug made of blue-glazed pottery","cn":"一把蓝釉陶壶"}},{"en":"the skill of making pots and dishes from clay, especially by hand","cn":"制陶手艺；制陶技艺","g":"[uncountable]","ex":{"en":"a pottery class","cn":"陶艺班"}},{"en":"a place where clay pots and dishes are made","cn":"制陶作坊；陶窑；陶器工厂","g":"[countable]"}]}},"poignant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人痛苦的；辛酸的；惨痛的","en":"Something that is poignant affects you deeply and makes you feel sadness or regret.","ex":{"en":"...a poignant combination of beautiful surroundings and tragic history.","cn":"美丽山水和悲惨历史让人黯然神伤的结合"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"causing people to have strong feelings – used especially about experiences, speeches, or subjects that people have strong feelings about","cn":""},{"en":"used about issues or language that make people have strong feelings","cn":""},{"en":"making you feel strong feelings of sadness or sympathy","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is poignant touches you deeply. Watching a poignant YouTube video about baby penguins chasing their mothers, for example, might give you a lump in your throat."}]},"collocations":{"phrases":["VERBS be, seem, sound | become | make sth The presence of the rest of the family made John's absence even more poignant. | find sth","ADV. deeply, extremely, particularly, unbearably, very I found his speech deeply poignant. | quite"]},"media":{"uk":"media/ldoce/hwd/bre/1/poignant0205.mp3","us":"media/ldoce/hwd/ame/f/poignant.mp3"},"examples":[{"en":"Of particular poignancy was the photograph of their son with his sisters, taken the day before he died.","cn":"特别令人感伤的是他们的儿子去世前一天和姐妹们的合影。"},{"en":"Her face was a poignant reminder of the passing of time.","cn":"她的容颜显示青春已逝，教人感伤。"}],"oxford":{"phon":"ˈpɔɪnjənt","pos":"adjective","senses":[{"en":"having a strong effect on your feelings, especially in a way that makes you feel sad","cn":"令人沉痛的；悲惨的；酸楚的","ex":{"en":"a poignant image/moment/memory, etc.","cn":"悲惨的形象、时刻、回忆等"}}]}},"porch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"门廊","en":"A porch is a sheltered area at the entrance to a building. It has a roof and sometimes has walls.","ex":{"en":"Is there a light in the porch or garden?","cn":"门廊或花园里有灯吗？"}},{"pos":"N-COUNT 可数名词","cn":"（沿外墙建造、常带顶的）走廊，游廊","en":"A porch is a raised platform built along the outside wall of a house and often covered with a roof.","ex":{"en":"We'd eat during the hot summer evenings on the front porch.","cn":"在炎热的夏夜，我们会在屋前走廊上吃晚饭。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an entrance covered by a roof outside the front door of a house or church 〔","cn":"房子或教堂前门外有顶的〕入口处﹐门廊"},{"en":"a structure built onto the front or back entrance of a house, with a floor and a roof but no walls 〔","cn":"房屋前后的〕游廊﹐走廊﹔阳台"}]},"collocations":{"phrases":["ADJ. entrance | church | back, front | north, south, west (= of a church) | pillared, projecting","PORCH + NOUN door, light","PREP. in/on the~ She stood in the porch and rang the doorbell."]},"media":{"uk":"media/ldoce/hwd/bre/9/porch0205.mp3","us":"media/ldoce/hwd/ame/e/porch.mp3"},"oxford":{"phon":"pɔːtʃ","pos":"noun","senses":[{"en":"a small area at the entrance to a building, such as a house or a church, that is covered by a roof and often has walls","cn":"门廊；门厅","ex":{"en":"She stood in the porch and rang the doorbell.","cn":"她站在门廊上按响了门铃。"}},{"en":"a platform with an open front and a roof, built onto the side of a house on the ground floor","cn":"（房屋底层有顶半敞的）走廊，游廊","lab":"North American English","ex":{"en":"They were sitting out on the porch in the cool evening air.","cn":"在傍晚的凉爽空气中，他们坐在门廊里。"}}]}},"porcelain":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"瓷","en":"Porcelain is a hard, shiny substance made by heating clay. It is used to make delicate cups, plates, and ornaments.","ex":{"en":"There were lilies everywhere in tall white porcelain vases.","cn":"高高的白色瓷瓶上绘满了百合花。"}},{"pos":"N-VAR 可变名词","cn":"瓷器","en":"A porcelain is an ornament that is made of porcelain. You can refer to a number of such ornaments as porcelain .","ex":{"en":"...decorative 17th and 18th century porcelains.","cn":"17和18世纪装饰用的瓷器"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a hard shiny white substance that is used for making expensive plates, cups etc","cn":"瓷"},{"en":"plates, cups etc made of this","cn":"瓷器"}]},"vocab":{"pos":"n","senses":[{"en":"Your mom's favorite white china plates are probably made out of porcelain . Porcelain is a nearly translucent ceramic material used to make plates, bowls, and cups."}]},"collocations":{"phrases":["ADJ. exquisite, fine | Chinese, Meissen, etc.","QUANT. piece some fine pieces of Chinese porcelain","PORCELAIN + NOUN factory | manufacturer"]},"media":{"uk":"media/ldoce/hwd/bre/0/porcelain0205.mp3","us":"media/ldoce/hwd/ame/e/porcelain.mp3"},"examples":[{"en":"a porcelain figure","cn":"瓷像"},{"en":"a porcelain vase","cn":"瓷花瓶"}],"oxford":{"phon":"ˈpɔːsəlɪn","pos":"noun","senses":[{"en":"a hard, white, shiny substance made by baking clay and used for making delicate cups, plates and other objects; objects that are made of this","cn":"瓷；瓷器","ex":{"en":"a porcelain figure","cn":"瓷像"}}]}},"poise":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"镇定；沉着；泰然自若","en":"If someone has poise, they are calm, dignified, and self-controlled.","ex":{"en":"What amazed him even more than her appearance was her poise","cn":"她的容貌让他惊叹，而更让他惊讶的是她的沉着。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（优雅的）姿势，姿态","en":"Poise is a graceful, very controlled way of standing and moving.","ex":{"en":"Ballet classes are important for poise and grace","cn":"芭蕾课对培养优雅的姿仪非常重要。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a graceful and attractive manner or appearance","cn":""},{"en":"a calm and very graceful way of moving your body, or of standing or sitting","cn":""},{"en":"a calm confident way of behaving, combined with an ability to control your feelings or reactions in difficult situations","cn":"镇定﹐自信﹐泰然自若﹐沉着"}]},"vocab":{"pos":"1 v n 2 n","senses":[{"en":"If you have poise , you are cool under stress. People with poise can handle pressure without showing it."}]},"collocations":{"phrases":["ADJ. natural the natural poise and balance of the body | social She never lost her social poise, however awkward the situation.","VERB + POISE retain | lose | recover, regain She hesitated briefly but quickly regained her poise."]},"media":{"uk":"media/ldoce/hwd/bre/7/poise_n0205.mp3","us":"media/ldoce/hwd/ame/6/poise1.mp3"},"examples":[{"en":"He was poising himself to launch a final attack.","cn":"他稳定住自己，以发动最后攻击。"},{"en":"The hawk poised in mid-air ready to swoop.","cn":"老鹰在半空中盘旋，准备俯冲。"}],"oxford":{"phon":"pɔɪz","pos":"noun","senses":[{"en":"a calm and confident manner with control of your feelings or behaviour","cn":"沉着自信；稳重；自若","ex":{"en":"His performance was full of maturity and poise.","cn":"他的表演充满了成熟和从容。"}},{"en":"the ability to move or stand in an attractive way with good control of your body","cn":"优雅的举止；仪态","ex":{"en":"the natural poise and balance of the body","cn":"身体的自然姿态与平衡"}},{"en":"to be or hold something steady in a particular position, especially above something else","cn":"（尤指在…上方）保持（某种姿势）；（使）保持平稳","ex":{"en":"The hawk poised in mid-air ready to swoop.","cn":"老鹰在半空中盘旋，准备俯冲。"},"pos":"verb"}]}},"potency":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（人、行动或思想的）影响力，支配力","en":"Potency is the power and influence that a person, action, or idea has to affect or change people's lives, feelings, or beliefs.","ex":{"en":"They testify to the extraordinary potency of his personality","cn":"这些事情证明了他非凡的人格魅力。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（药物等的）效力；药力；药效","en":"The potency of a drug, poison, or other chemical is its strength.","ex":{"en":"Sunscreen can lose its potency if left over winter in the bathroom cabinet.","cn":"如果把防晒霜在盥洗室的壁橱里放一个冬天，就有可能失效。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（男子的）性交能力，性机能","en":"Potency is the ability of a man to have sex.","ex":{"en":"Alcohol abuse in men can cause loss of sex drive and reduced potency.","cn":"男子酗酒可能导致性欲丧失和性功能下降。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the power that something has to influence people","cn":"力量﹐威力﹔影响力"},{"en":"the strength of something, especially a drug, on your mind or body 〔","cn":"尤指药物的〕效力﹐效能"},{"en":"the ability of a man to have sex 〔","cn":"男子的〕性功能"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun potency when you're talking about the strength of something. You could refer to the potency of a drug or the potency of a political leader."}]},"collocations":{"phrases":["ADJ. sexual a man at the peak of his sexual potency","VERB + POTENCY increase | affect | lose"]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41potency.mp3","us":"media/ldoce/hwd/ame/1/potency.mp3"},"examples":[{"en":"If you keep a medicine too long, it may lose its potency.","cn":"药物存放太久，可能会失去效力。"},{"en":"the potency of desire","cn":"欲望的支配力"}],"oxford":{"phon":"ˈpəʊtnsi","pos":"noun","senses":[{"en":"the power that somebody/something has to affect your body or mind","cn":"影响力；支配力；效力","g":"[uncountable, countable]","ex":{"en":"the potency of desire","cn":"欲望的支配力"}},{"en":"the ability of a man to have sex","cn":"（男子）性能力，性机能","g":"[uncountable]"}]}},"postscript":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（信末署名后的）附笔，附言，又及","en":"A postscript is something written at the end of a letter after you have signed your name. You usually write 'PS' in front of it.","ex":{"en":"A brief, handwritten postscript lay beneath his signature.","cn":"在他的签名下，有一句简短的手写附言。"}},{"pos":"N-COUNT 可数名词","cn":"（加在故事、记述、声明末尾的）附言，补充说明；补编；跋","en":"A postscript is an addition to a finished story, account, or statement, which gives further information.","ex":{"en":"As the editor's postscript reminds the reader, she was to endure two more spells of mental illness before the book was published","cn":"正如编辑在附言中提醒读者的那样，她在本书出版前还要再经历两次精神疾病发作的折磨。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a message written at the end of a letter after you have signed your name 〔","cn":"信末署名后的〕附笔﹐附言﹐又及"},{"en":"extra details or information that you add after a story or an account 〔","cn":"加在故事﹑叙述等末尾的〕附言﹐补充说明"}]},"vocab":{"pos":"n","senses":[{"en":"A postscript is text added at the end of a book or other document. Your textbook is so long that by the time you finish it, you're too exhausted to read the postscript ."}]},"media":{"uk":"media/ldoce/hwd/bre/7/postscript0205.mp3","us":"media/ldoce/hwd/ame/0/postscript.mp3"},"examples":[{"en":"There’s an interesting postscript to this tale.","cn":"这个故事后面有一段有趣的附记。"}],"oxford":{"phon":"ˈpəʊstskrɪpt","pos":"noun","senses":[{"en":"an extra message that you add at the end of a letter after you sign your name","cn":"（加于信末的）附言，又及"},{"en":"extra facts or information about a story, an event, etc. that are added after it has finished","cn":"补充；补编；后话；跋","ex":{"en":"News of the award comes as a fitting postscript to a long and successful career.","cn":"获奖的消息是对我长期而成功的职业生涯的一个恰当的后记。"}}]}}});
